window.IV=window.IV||{};IV.univ=IV.univ||{};IV.univ["u087"]={"univ":"숭실대학교","reviews":[{"univ":"숭실대학교","dept":"건축학부 실내건축전공","jeonhyeong":"학생부종합(SSU미래인재 전형)","method":"개별(2:1) / 서류기반 면접(전공 적합성(50), 인성 및 잠재력(50)) / 면접시간 15분 내외","notes":"면접 시간이 길어서 생기부의 전공과 관련된 세부적인 내용까지 물어봄.꼬리질문이 많으니 본인 생각이나 예시들을 세부적으로 정리해놓고 가는 것이 좋음.","qa":[{"q":"우리학교 실내건축학과에 지원하게 된 동기 말해 보세요.","a":"저는 1학년 통합사회 수업에서 진행했던 ‘살기 좋은 도시 만들기 프로젝트’의 조장을 맡으면서 건축에 대한 꿈을 가지게 되었습니다. 프로젝트 진행과정에서 단순 재미가 아닌 직업적 열정을 느낀다는 것을 알게 되었고, 건축 중에서도 사람들과의 직접적 교류가 가장 많다고 생각되었던 실내건축학과의 지원하게 되었습니다."},{"q":"본인이 이 학과에 지원하기 위해 특별히 노력한 점이 있을까요?","a":"고교시절 제가 직접 방문하여 기억하고 싶은 디자인이나 보완할 점이 있다고 생각되었던 공간이 있다면 기록을 해두는 활동을 하였습니다."},{"q":"그 기록들 중에 특별히 인상적이었던 장소가 있을까요?","a":"미술관을 자주 방문했었는데 전시 공간에서 인상적이었던 부분들이나 건물의 외관들을 기록해두었던 게 기억에 남습니다."},{"q":"그런 미술관을 한 군데를 답사 갔단 말인가요? 기억에 남는 미술관 특징이 무엇이라고 생각하나요?","a":"가족들과 여행을 가는 등의 일상적 경험을 속에 기억에 남는 공간들을 기록했고, 여러 미술관들을 방문했는데 기억에 남는 미술관 한 곳을 소개한다면 대구간송미술관을 말씀드리겠습니다. 건물 외관이 한 가지의 색상으로 통일되어있었지만, 건물의 기둥이 목재로 이루어져있어 한국의 전통적인 느낌을 살리면서 색다른 분위기를 만든 것 같아 기억에 남습니다."},{"q":"생기부에 본인의 건축관에 대해 고민해보는 계기가 되었다고 적혀있는데, 본인의 건축관에 대해 설명해보세요.","a":"저는 사람들이 본인의 개성과 취향을 명확하게 표현할 수 있는 공간들을 설계하고 싶습니다."},{"q":"생기부에 ‘건축과 사람들의 심리에 대한 연관성’을 조사했다고 되어있는데, 구체적인 사례를 들어서 설명해보세요.","a":"학교의 교실을 예시로 들어 설명드리겠습니다. 교실에 들어서면 학생들은 모두 선생님을 향하도록 공간이 배치되있습니다. 이런 배치는 시선과 시야의 차이는 수업의 주도자를 만들게 되면서 학생이 선생님과 관계에 대해 인지하게 되는 효과가 있습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"글로벌통상학과","jeonhyeong":"학생부종합(SSU미래인재 전형)","method":"전공적합성50+인성, 잠재력502:1 개별면접, 블라인드, 가번호 부여면접 비중 확대: 30% ->50%","notes":"","qa":[{"q":"숭실대학교 많은 학과 중에서 글로벌통상학과에 지원했는데 글로벌통상학과가 뭐하는 학과인가요?","a":"(정확하게 뭐라고 했는지 기억안남) 학생들이 ~ 국제사회의 수출입에 기여할 수 있도록 도와주는 학과인 것 같습니다"},{"q":"그럼 와서 공부하고싶은 과목 있어요?","a":"1-2학년때 국제통상개론, 관세론과 같은 기초 과목을 수강하고 영어, 중국어 등을 집중적으로 학습하며 국제무역에 대한 이론적 이해를 심화시키겠습니다. 3-4학년이 되고 심화과목을 통해 전문 지식을 쌓고 교환학생 프로그램이나 해외시장참여 기회를 적극적으로 활용해 다양한 무역 환경을 직접 경험하겠습니다."},{"q":"졸업하고는 뭐하고싶어요?","a":"숭실대학교 글로벌통상학과에서 쌓은 경험을 바탕으로 국내 기업의 해외 진출에 지원하고 국제기구에서 무역 정책을 기획하는 글로벌인재로 성장하는 것이 최종 목표입니다."},{"q":"어떤 국제기구에서 뭐하고싶은데요?","a":"환경보호와 지속가능한 발전을 위해 친환경적인 제품의 수출에 적극적인 지원을 하고싶습니다."},{"q":"현재 무역 관련해서 아는 이슈 있나요?","a":"미국의 대선으로 트럼프의 보호무역정책으로 인한 영향에 대해 말씀드리겠습니다. 미국의 보호무역 강화로 우리나라 기업의 수출 경쟁력이 약화되어 수출입의 불확실성이 커질 것입니다. 하지만 미국 내 생산기업이 많아져 일자리가 늘어나면 미국소비자의 구매력이 상승하게됩니다. 이로인해 우리나라 기업이 미국공장에서의 생산시설을 늘릴 수 있습니다."},{"q":"그런 미술관을 한 군데를 답사 갔단 말인가요? 기억에 남는 미술관 특징이 무엇이라고 생각하나요?","a":"미국 내 보호무역 정책이 확산되면 소비자들의 선택의 기회가 제한됩니다."},{"q":"수에즈 운하 봉쇄 해결책으로 미국 사례 분석한게 있는데 이게 뭔가요?","a":"미국의 주요 쇼핑몰의 수에즈운하 봉쇄 이전과 이후 물류센터를 비교하니 이후에 물류센터를 도시에 배치에 물류지연을 완화한 것을 알 수 있었습니다. 도시는 인구밀집도가 높아 많은 고객들을 효율적으로 상대 할 수 있습니다. 또한 연료비와 운송시간을 줄일 수 있다는 점을 분석했습니다."},{"q":"학교생활 할 때 힘든거 없었나요?","a":"저는 2,3학년때 반장으로서 여러 행사 준비와 학습일정을 관리하며 저의 개인적인 시작이 부족했던 날들이 있습니다. 쉽게 피로를 느껴 이를 극복하기 위해 계획적으로 시간을 분배했습니다. 중요한 일을 먼저 처리하고 쉬는시간과 같은 짧은 시간을 이용해 학급일정을 관리했습니다."},{"q":"전자상거래 전부개정안에 대해서 활동한게 있는데 이게 뭔가요?","a":"온라인 쇼핑에서 허위광고, 리뷰조작 등 다양한 소비자 피해가 증가했고 기존의 법률로는 소비자를 보호하는 데 한계가 있어 개정되었습니다. 전부개정안은 기존의 청약 철회 기간을 7일에서 14일로 연장하고 플랫폼 운영자가 판매자의 물품에 사전 검증 의무를 지게했습니다."},{"q":"탄소국경세가 뭔가요?","a":"EU로 수입되는 제품 중 자국보다 탄소배출이 많은 국가에서 생산되는 제품에 관세를 부과하는 일종의 추가 관세입니다."},{"q":"탄소국경세 도입되면 우리나라에 어떤 영향을 미치나요?","a":"철강과 석유화학은 우리나라의 주요산업이고 생산과정에서 많은 탄소가 배출되기 때문에 탄소국경세가 도입된다면 경쟁력이 떨어질 것입니다."},{"q":"‘다국적 기업의 수출 성공 핵심요인 분석 및 해외시장 확보’ 탐구진행한거 이야기해주세요","a":"수출에 있어 우위를 잡는 데에는 먼저 각 나라의 정책을 분석하고 이를 마케팅 전략에 활용한 것이였습니다. 미국의 엄격한 환경 규제에 맞서 친환경적인 제품의 수요가 늘어나 에너지효율이 높은 제품을 개발하여 수출하였습니다. 또한 긍정적이고 희망적인 슬로건과 함께 다양한 광고 속에서 소비자들이 소소한 행복을 찾을 수 있게 강력한 브랜드 이미지를 구축하였습니다."},{"q":"계속 영어토론동아리였는데 전체토론을 다 영어로 진행했나요?","a":"처음에는 전체를 영어로 진행했지만 다들 어려움을 느껴 입론과 결론만 영어로 진행했습니다"},{"q":"그럼 제일 기억에 남는 토론 주제가 뭔가요?","a":"과연 공정무역 공장에서의 제품을 구매하는 것이 아동노동착취를 하는 공장에서의 제품을 구매하는 것보다 효과적인가? 라는 주제가 가장 기억에 남는 것 같습니다."},{"q":"이 주제에 대해 어떻게 생각하나요?","a":"저는 그래도 공정무역 공장에서의 제품을 구매해야한다고 생각합니다. 공급망의 투명성을 강화하고 모든 단계를 추적해 한계를 극복해야합니다. 또한 정부의 정책적 지원을 통해 공정무역의 구조적 한계를 극복하고 보다 나은 무역형태를 만들어야한다고 생각합니다."},{"q":"모든 단계를 추적하는게 가능할까요?","a":"현실적으로 어려움이 있을 수는 있지만 국제사회의 협력을 통해서는 가능할 것 같습니다."},{"q":"우리학교와서 제일 듣고싶은 프로그램 있어요?","a":"저는 숭실대학교 글로벌통상학과의 특성화 프로그램인 GCPP에 참여하여 실제적인 현장을 방문하고 해외시장개척활동에 참여해 저의 꿈을 이루고싶습니다."},{"q":"마지막으로 하고싶은 말 있나요?","a":"먼저 면접의 기회를 주셔서 감사합니다. 숭실대학교 글로벌 통상학과는 저의 목표를 실현하기 위한 배움의 장이라고 생각합니다. 숭실대학교에서 기독교적 가치를 바탕으로 학문적인 성장뿐만 아니라 인격적으로도 발전한 국제적인 안목을 갖춘 인재가 되겠습니다. 내년 3월부터 학교 프로그램과 학업에 누구보다 충실히 임해 저의 열정과 노력을 바탕으로 교수님들과 학문발전에 기여하는 창의리더로 성장하겠습니다. 감사합니다!!"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"법학과","jeonhyeong":"학생부종합(SSU미래인재 전형)","method":"생기부 면접. 분위기는 따뜻한 편이었음. 진로 관련 활동과 관련된 질문과 행동 특기 사항에 관련한 질문을 둘 다 함.","notes":"분위기가 매우 좋았음. 당당하고 자신감 있게 답하는 것이 중요.","qa":[{"q":"법학과를 지원하기 위해 학교 생활에서 어떤 노력을 했나요?","a":"3년 내내 법과 관련된 활동을 많이 했습니다. 1,2학년 때 영자신문 동아리에서 촉법소년과 아동 학대에 관련된 기사를 작성하는 것과 3학년 때 법 동아리를 창설해 법과 관련된 다양한 활동들을 한 것이 가장 기억에 남습니다."},{"q":"법학과를 지원하는 학생들이 촉법소년과 관련된 활동을 많이 하는데 지원자는 촉법소년에 대해 어떻게 생각하는지?","a":"저는 촉법소년 연령을 하향시킬 필요가 있다고 생각합니다. 법이 제정되던 시기의 소년들과 현재의 소년들은 다른 환경에서 살아갑니다. 정보 사회에 접어들면서 범죄에 더 노출되기 쉬운 환경에서 살아가기에 연령을 하향시킬 필요가 있다고 생각합니다."},{"q":"촉법소년의 나이 하향도 해결방안이 될 수 있지만 촉법소년들의 미성숙함은 어떻게 해결할 것인지?","a":"교육기관의 도움으로 해결할 것 같습니다. 교육기관을 통해 그들의 미성숙함, 올바른 가치관 정립 등을 할 수 있을 것이라고 생각합니다"},{"q":"많은 생기부를 봐왔지만 이런 행동특성 및 종합의견을 처음 보는 것 같다. (요약) 학생의 존재와 역량이 매우 크다고 나와있다. 어떻게 하면 선생님들이 이런 의견을 써주실 수 있나?","a":"일단, 수업 전 수업에 필요한 것들을 미리 준비해놓습니다. 그리고 앞자리에 앉아 선생님의 말씀에 귀 기울여 들었던 것 같습니다. 수업 중 궁금한 게 생긴다면 부끄러워하지 않고 질문하였습니다. 또, 수업이 끝나면 헷갈렸던 것들이나 궁금했던 것들을 따로 가서 질문했습니다."},{"q":"선생님들이 힘들어하셨을 거 같은데..","a":"선생님들은 수업을 하면서 학생과 소통이 된다고 생각하셔서 매우 좋아하셨습니다. 또, 저의 적극적인 태도로 영향을 받은 주위 학생들도 선생님께 질문을 하는 등 수업에 참여하게 되어 좋다고 말씀해주셨습니다."},{"q":"대학교에 와서도 똑같이 할 것인지?","a":"(매우 당연하다는 듯이) 네. 똑같이 할 것입니다."},{"q":"어떻게 해야 친구들도 선생님들도 이뻐하는 학생이 될 수 있나?","a":"선생님들과 친구들의 의견을 잘 전달할 줄 알아야한다고 생각합니다. 선생님의 말씀을 귀 기울여 듣는 것도 매우 중요하지만 학생들의 의견을 종합해서 선생님께 전달하는 것도 매우 중요하다고 생각합니다. 또, 친구들에게도 먼저 다가가 도움이 필요한 것에는 기꺼이 도움을 줄 수 있어야합니다. 친구들의 관심분야를 파악하고 좋아하지 않을 것 같은 분야에서는 얘기를 꺼내지 않는 것입니다."},{"q":"입시 사정관들은 그럼 어떤 행동들을 싫어할 것 같은지","a":"다리를 떠는 것과 손을 떠는 행위를 좋아하시지 않을 것 같습니다. 또, 자신감 없는 태도와 자신의 생기부에 대해 잘 알지 못하는 모습을 별로 좋아하시지 않을 것 같습니다."},{"q":"그렇다면 입시 사정관들은 어떤 모습을 좋아할 것 같은지","a":"예의 바른 태도와 자신감 있는 모습을 선호하실 것 같습니다. 또, 자신의 생기부 내용에 대해 잘 파악하고 있는 모습을 좋아하실 것 같습니다."},{"q":"이런 게 바로바로 머리에 떠오르는 겁니까?","a":"네. 그런 것 같습니다.(옆에 있던 분이 재능이라고 칭찬하심)"},{"q":"마지막으로 하고 싶은 말 해주세요","a":"숭실대학교 법학과를 목표로 지난 3년 동안 항상 꾸준히 노력하고 성실하게 학교 생활을 해왔습니다. 3년 간 다사다난했고 우여곡절이 많았던 것이 어쩌면 숭실대학교를 오기 위한 하나의 발판이었다는 생각이 듭니다. 숭실대학교에 입학하게 된다면 저의 열정과 노력을 계속 이어나가겠습니다. 다른 학교는 제 안중에 없습니다. 오직 숭실대학교만 바라보고 있습니다. 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"산업정보시스템공학","jeonhyeong":"학생부종합(SSU미래인재 전형)","method":"면접관 2명, 수험생 1명의 개별면접블라인드 면접13~15분 내외","notes":"생기부 내용 확인 질문이 많음오전조 마지막이면 대기 3시간 정도 할 수 있음대기실에서 연습할 시간이 있음(휴대폰 사용불가, 자료 가져가야함)들어가니 아이스브레이킹 질문을 많이 해주심","qa":[{"q":"간단한 자기소개 및 지원동기 말씀해주세요.","a":"저는 통신사 이탈 여부를 인공지능 모델로 분석하고 버스 예약 등의 문제를 컴퓨터 프로그램을 통해 해결한 경험이 있습니다. 이 과정에서 산업과 공학간의 중요성을 알게되었고, 단순히 프로그래밍만 하는 것이 아니라 이를 통해 산업,사회문제를 해결하고 산업에 도움이 되는 기술을 만들고 싶어졌습니다. 숭실대학교가 데이터분석, 인간중심설계 모듈 등 다양한 전공 과목 교육을 들을 수 있는점과 해외산업시찰 등 다양한 비교과프로그램을 가지고 학생들에게 많은 지원을 해준다는 점이 인상깊었습니다. 그래서 숭실대학교에 관심을 가지게 되었고 인강공학, 다변량데이터분석 등의 수업을 토대로 산업사회를 이끌어 나갈 글로벌 리더가 되고싶어 이 학과에 지원하게 되었습니다."},{"q":"음 보니까 컴퓨터 코딩 활동도 많고 지원동기에서 말했다싶이 산업문제를 해결하고싶다고 했는데 활동 중 이 학과와 가장 적합한 활동?","a":"통신사 고객 이탈 여부를 인공지능 모델로 분석했던 활동이 가장 어울린다고 생각합니다. 저는 기업이 고객을 유지하기 위해 데이터 분석이 필수적이라고 생각합니다. 이에 따라 통신사를 주제로 데이터를 분류해보았습니다. 컴퓨터 비지도 학습을 활용하여 고객의 특성을 클러스팅했습니다. 랜덤포레스트 알고리즘을 이용했습니다. 그 결과 자신에게 맞는 서비스를 제공해 주었을때 고객 유치가 많이 된다는 결론을 얻었고 저는 이처럼 데이터 분석을 통해 고객을 유치하는 기술을 만들고 싶습니다."},{"q":"주관적인거 아니냐 어떤 서비스를 말하는건가?","a":"저는 공공데이터포털에서 고객의 정보를 받아왔습니다. 물론 주관적이긴하나 ott서비스, 많이 사용할시 할인해주는 등 서비스를 이용하여 분석하였고 ott서비스를 제공하는 경우 2030대 사람들이 그 통신사를 오래 사용한다는 결론을 얻었습니다."},{"q":"수학 과목을 많이 들었는데 그 중 수학과사고와통계에서 앨런매시스튜링에 대해 조사했는데 이를 설명해주세요","a":"앨런매시스튜링은 컴퓨터 과학의 아버지로 최초로 수학과 컴퓨터를 연결지은 과학자라고 알고있습니다. 또한 튜링 모델을 통해 컴퓨터를 수학적으로 설계하여 인상 깊었습니다."},{"q":"또 확률과 통계에서 베이즈정리가 뭔지 간단히 설명해주세요","a":"베이즈 정리는 간단히 말하면 조건부확률입니다. 원인에서 결과를 찾는 것과 반대로 결과를 보고 어떤 원인인지 찾는것입니다 식을 간단히 설명하자면 사건 B가 발생했을 때 사건 A의 조건부 확률 = (사건 A가 발생했을 때 사건 B의 조건부 확률 X 사건 A의 확률) / 사건 B의 전체 확률로 구할 수 있습니다."},{"q":"1학년때 반장하고 2학년때 전교회장도 출마했던데 당연히 리더쉽 키웠겠지만 키운것에 대해 설명해주세요","a":"저는 처음 의견을 모으는 과정에서 어려움을 겪었습니다. 다양한 친구가 있다보니단순히 의견을 모아 알려주는것에 불만을 느낀 경험이 있어 저는 공감과 경청을 통해 모든 친구들의 의견을 듣고 공감해주며 모두가 만족할 수 있는 의견을 냈습니다. 또한 전교회장에 출마하며 전교생앞에서 저의 의견을 전달하며 리더십을 키울 수 있었습니다."},{"q":"학급을 이끌면서 이룬 사례가 있을까요?","a":"체육대회 1등했다고 설명"},{"q":"승부욕이 강하다고 적혀있는데 강한가요?","a":"네 이 점이 친구들의 사기를 복돋아주는 점이 있지만, 좋은 결과를 내지못했을 때 제 자신의 잘못이라 생각하는 경향이 있습니다. 그래서 저는 결과보다는 협력하는 과정을 중요시하며 단점을 극복하고있습니다.적절한 승부욕은 또 도움이되니까 강점으로 잘 이용해서 도움을 얻으면 되겠네요"},{"q":"다익스트라알고리즘에 대해 탐구했고 항공기 경로등에 사용될만큼 꼭 필요한건데 또 탐구에 편리함 느낀 사례가 있다고 하는데 설명해주세요.","a":"저는 네이버지도를 사용하며 편리함을 느꼈습니다. 같은 길이더라도 시간이 다르면 그때에 맞춰 최적의 경로를 제공하는 점에서 편리함을 느꼈습니다. 또한 제가 버스예약프로그램을 제작한적이 있는데 이를 이용해 최적의 버스 노선을 제작한다면 또 편리함을 느낄 수 있다고 생각합니다"},{"q":"관련 이슈나 관심있는분야?","a":"저는 챗지피티라고 생각합니다. 마이크로소프트의 경우 챗지피티를 이용하며 문서 작성 보조, 회의 내용 요약 등에 사용하고있습니다. 저도 챗지피티를 이용해본 경험이 있습니다. 인공지능 응용에 대한 연구하는 대학원이 있는 것으로 알고있는데 이에 들어가서 챗지피티api만 연결하는 것이아니라 이와같은 인공지능 모델을 직접 개발하고싶습니다."},{"q":"마지막 할말있으시면 해주세요","a":"저는 전국 단위의 해커톤 대회와 네 번의 공동교육과정을 통해 꿈에 다가가며, 스스로 탐구하는 능력을 키워왔습니다. 또한 3년동안 반장 부반장을 하며 리더십과 봉사정신을 키워왔습니다. 꼭 숭실대학교에 입학하여 산업사회를 이끌어나가는 능력을 배워 최초의 숭실, 최고의 산공의 이름에 걸맞는 인재가 되겠습니다. 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"평생교육학과","jeonhyeong":"학생부종합(SSU미래인재 전형)","method":"면접위원 2인, 지원자 1인의 서류 기반 블라인드 면접면접의 공정성을 위해 가번호를 부여하여 면접을 진행함블라인드 처리 정보: 지원자 성명, 수험번호, 출신 고등학교명, 부모 성명, 부모 직업 등 평가 시간: 지원자 1인당 15분 내외","notes":"생기부 관련 질문이 주로 나오기에 세세한 부분까지 정독을 하는 것을 추천, 면접을 보는 것이 아닌 내가 했던 활동이 사실인지 확인하고자 하는 시간이라고 생각하면 편할 듯하다.예상질문을 만들어 모의면접을 해보는 것을 추천함! 본인의 경우 예상 질문을 100개 정도로 준비했고 예상한 질문 중 4할 정도(수치로 따지면)가 면접에 나왔다. 예상질문에 답해볼 때 그 답변을 ‘암기’한다는 느낌이 아닌 다양한 질문에 답을 해보는 경험을 쌓는 데에 초점을 맞출 것!! 무작정 답변을 암기했을 경우 한 번 말이 꼬이면 전달하고자 하는 내용을 요점조차 정확히 전달할 수 없다.면접을 준비하고, 실제로 보기 전까진 마인드 컨트롤이 가장 중요한 것 같다. 편안한 마음을 먹고, 면접장에서 대기할 때도 초조하게 생기부만 들여다보는 것이 아닌 질문에 답하는 상황을 시뮬레이션 돌려보며 말을 잘 전달하는 데에 초점 맞추기.","qa":[{"q":"내셔널트러스트와 그로프트라는 동아리에 참여했네요. 어떤 동아리인지 소개해줄 수 있나요?","a":"동아리 이름의 뜻과, 각각 어떤 분야의 활동을 주로 하였는지 설명드림. 둘 다 3년간 쭉 참여한 동아리임을 언급하면서 그로프트의 경우 디베이트로 동아리명이 바뀌게 된 이야기를 같이 해드렸는데 ‘아, 여기 이름이 바뀌었네요. 내가 못 봤네.’ 라시면서 대꾸도 해주셨음."},{"q":"내셔널트러스트에서 일본의 오염수 방류에 관한 토론 활동을 했는데, 이때 본인이 주장한 내용과 견해를 설명해줄수 있나요?","a":"토론 활동 서 일본이 오염수 방류를 막 시행했을 무렵 언론에 보도된 내용과 사실이 달랐던 점(오염수 방류 필터가 문제 없다고 송출된 뉴스와 달리 3n개나 파손되어 있었던 점 언급함.)을 주장했던 기억을 설명드림."},{"q":"교권 침해에 관해서도 활동을 했네요? 학교 교권 보호 위원회와 고충심사위원회 같은 실제 기구들에 기능적인 한계가 있다고 하셨는데 설명 부탁드립니다.","a":"활동명(함께 만드는 비정부기구)을 언급하면서 간단히 소개, 각 기관들이 교권 보호를 위해 다양한 정책/복지를 제공하고 있지만 이것이 실질적으로 실제 현장서 시행되는 경우는 드물다는 점을 언급하여 설명하였음."},{"q":"일본의 가미카제 특공대와 한국의 입시 위주 공교육이 비슷하다고 언급하신 활동이 있는데, 어느 점을 비교했나요?","a":"가미카제 특공대는 일본이 ‘강요한’ 자살공격 전술이라는 점에서 다양성을 배제한 채 대학 입시에만 초점을 두는 한국의 주입식 공교육과 비슷하다고 언급, 이를 설명함."},{"q":"평생교육학과를 진학한 후 향후 진로가 있나요?","a":"저소득층이나, 노년층 등/사회라는 궤도에서 이탈하여 소외되어 있는 계층이 모두 동등한 교육의 기회를 누릴 수 있도록 평생교육 프로그램을 기획하는 개발자가 되고 싶다고 언급함. +향후 국내에서 프로그램을 개발 후 세계의 다양한 나라의 문화를 참고하여 전 세계로 꿈을 확장시켜 나가고 싶다는 포부."},{"q":"사회 격차 같은 문제에 관심이 많아 보이네요, 그렇다면 평생교육이 이런 격차를 어떻게 해결할 수 있을까요?","a":"사회 격차와 같은 문제는 국내에만 국한되지 않은 문제라고 생각함, 타 국가에서도 교육, 사회 격차와 같은 사회 문제가 발생하고 있으며 이미 한국처럼 이를 해결하기 위한 평생교육기관이 존재함. 이러한 기관들은 시행하는 프로그램이나, 정책들은 다를지 모르더라도 궁극적인 평생교육의 목적은 통일되어있다고 생각함을 주장하며 견해를 설명함."},{"q":"마지막으로 하고 싶은 말이 있다면 해주세요.","a":"향후 평생교육의 전망, 그리고 본인의 진로에 대한 포부 관련으로 잘 끝마치고 나옴. 이야기 꽤 경청해주셨고 퇴장할 때도 웃어주셨다.면접관님들이 가볍게 아이스브레이킹을 해주시며 분위기를 풀어주셔서 나름대로 분위기는 괜찮았다, 지원자가 학생 신분임을 감안하여 진행해주심. 하지만 풀어진 분위기 속 중간중간 눈을 안 마주치시고 쭉 무시(...)하시는 느낌이 들 때가 있는데 이때 갑자기 당황하지 않는 것이 중요함."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"불어불문학과","jeonhyeong":"학생부종합(기회균형전형)","method":"다수의 평가자가 면접응시자 1인을 면접학생부를 기초로 한 대면 면접","notes":"","qa":[{"q":"왜 우리 학과에 지원하게 되었나요?","a":"“오랫동안 언어에 관심을 가지며 여러 언어를 접하던 중 프랑스어를 듣게 되었는데, 독특하고 매력적인 발음에 사로잡혀 꼭 프랑스어를 유창하게 구사하고 싶다는 목표가 생겨 지원하게 되었습니다.”"},{"q":"왜 하필 숭실대학교에 와야 하나요?","a":"“불어불문학과임에도 문학에만 포커스된 것이 아니라, 제가 관심 있는 어학과 회화 관련 강의가 마련되어 있는 점이 인상 깊었습니다. 특히 학교에서 주최하는 프랑스어 말하기 대회가 있다는 것을 알게 되었는데, 저는 언어를 배울 때 말하기가 가장 중요하다고 생각합니다. 이 대회에 참가해보는 것이 제 어학 실력 향상에 큰 도움이 될 것이라 판단했습니다.”"},{"q":"프랑스 문학을 읽어본 경험이 있나요?","a":"“이방인과 적과 흑 등을 읽은 경험이 있습니다.”"},{"q":"이방인은 20세기 철학의 대표작인데, 철학 사조 중 알고 있는 것이 있나요?","a":"“제가 철학과 관련된 부분까지는 깊게 공부하지 않아서 그 부분은 잘 모르겠습니다.”"},{"q":"이방인에서 기억에 남는 장면은 무엇인가요?","a":"“뫼르소가 재판을 받을 때, 사람들이 살인 행위 자체보다 어머니가 죽었음에도 슬퍼하지 않았다는 점에 초점을 맞춰 비난하는 장면이 기억에 남습니다.”"},{"q":"디자인에 관심이 있었나요? 현재도 그런가요?","a":"“네, 프랑스가 건축과 패션 등 디자인과 관련된 분야로 유명하기도 하고, 제가 1학년 때는 진로를 구체적으로 정하지 못해 방황하며 디자인 분야로의 진출도 생각했습니다. 하지만 현재는 통번역사라는 진로를 희망하고 있습니다.”"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"독어독문학과","jeonhyeong":"학생부종합/기회균형","method":"서류 확인 면접","notes":"블라인드","qa":[{"q":"지원동기","a":"제 꿈은 독일과 한국의 문화와 문학을 이어주는 일을 하는 것입니다. 제 꿈을 이루기 위해선 국제적 소통 능력, 뛰어난 인문학적 소양이 필요하다고 생각합니다. 조병화 시인이 헤르만 헤세 작가가 사망하셨을 때 애도시를 신문에 실었다는 기사를 읽고 헤르만 헤세 작가의 영향력을 알게되었습니다. 그리고 헤르만 헤세의 낭만주의에 관심이 가서 낭만주의 소설들을 읽어 보니 일제강점기로 인해 사회상을 반영한 문학이 중심이었던 우리나라와 다르게 개인의 정서를 탐구하는 경향에서 차이점을 확인하고 낭만주의의 매력을 느꼈기 때문에 다양한 독일의 문학 장르에 대해 깊이 있는 탐구를 하고 싶습니다. 숭실대 독어독문학과의 교육 목표가 인간과 사회에 대하여 인문학적 소양을 갖춘 화합소통형 인재를 양성하는 것으로 알고 있습니다. 이 점에서 제 꿈을 이루기 위해 이뤄야 할 목표와 부합하다 생각하여 숭실대 독어독문학과에 지원하게 되었습니다."},{"q":"프란츠 카프카의 『변신』이라는 책을 읽었던데 어떤 점이 인상 깊었나요?","a":"『변신』의 주인공인 그레고르가 벌레가 된 것을 직장으로 인한 스트레스로 자존감을 잃은 사람, 후천적으로 장애를 얻은 사람 등 여러 가지로 해석할 수 있었고, 이 과정에서 한 인물을 여러 가지 상황으로 해석하는 것이 재미있었기 때문에 가장 인상 깊게 읽었습니다."},{"q":"독일의 통일에 대한 긍정적 측면과 부정적 측면에 대해 얘기해 보세요.","a":"독일의 통일에서는 전쟁처럼 큰 분쟁 없이 평화롭게 통일한 점이 긍정적이라 생각하고 갑작스럽게 통일되어 경제적 측면에서 큰 손실을 본 것이 부정적 측면이라 생각합니다."},{"q":"1,2학년 때 반장과 부반장 역할을 맡았는데 친구들에게 어떤 사람이었나요?","a":"저는 반장과 부반장 역할을 하는 데에서 친구들의 의견을 모으고 절충안을 내놓는 역할을 주로 맡았습니다. 이런 면에서 저는 친구들에게 바늘과 실같은 사람이었습니다."},{"q":"1,2학년 때 미디어를 희망하다가 독어독문학과로 전향했는데 특별한 이유가 있을까요?","a":"저는 1,2학년 때 특별한 진로가 없어 sns에서 쉽게 접할 수 있었던 미디어에 관심을 가졌습니다. 하지만 독일의 문학을 읽다 보니 독일과 한국의 문화와 문학을 이어보고 싶다는 생각을 하게 되었고 이를 통해 독어독문학과로 전향하게 되었습니다."},{"q":"그루밍 성범죄에 관한 영상을 찍었던데 그 영상에 관해 소개해 주세요.","a":"저는 그루밍 성범죄를 겪은 13세 소녀의 이야기에 관한 기사를 읽고 이 주제에 대한 영상을 스스로 제작해 보았습니다. 영상은 13세 소녀의 시점으로 아무런 의심 없이 그루밍 성범죄를 당하다가 점점 심리적으로 고통받고 갈등하는 소녀의 이야기입니다."},{"q":"온라인 공동교육 과정에서 낮은 성적을 보였던데 특별한 이유가 있나요?","a":"1학년 때의 저는 진로에 대한 확신과 목표가 없었기 때문에 영화감상과 비평이라는 수업에서 큰 관심을 가지지 못하고 성실하지 못한 모습을 보였습니다. 하지만 그 수업에서 낮은 성적을 받고 제가 관심이 없는 분야더라도 성실히 임해야겠다고 생각하여 지금까지 제가 속한 많은 분야에서 최선을 다하고 있습니다."},{"q":"언어와 매체 활동에서 신조어를 합성어와 파생어로 분류하는 조사를 하였던데 예시를 알려주세요.","a":"합성어에서는 ‘현금’과 ‘지르다’를 결합한 ‘현질’을 예로 들 수 있고 파생어에서는 카페 공부의 줄임말인 ‘카공’에 접미사 ‘–족’이 결합한 카공족을 예로 들 수 있습니다."},{"q":"마지막으로 하고 싶은 말이 있으면 해보세요.","a":"제가 오늘 이 자리에서 제가 탐구한 활동들을 면접관님들과 함께 얘기해 볼 수 있는 기회를 주셔서 감사합니다. 저는 제 꿈을 이루기 위해서 숭실대 독어독문학과에서 독어를 비롯한 문화, 문학 등 다양한 분야들을 공부하여 세계적으로 소통하는 숭실대의 인재가 되고 싶습니다. 감사합니다.특이점아이스브레이킹 없이 13분 동안 면접을 진행함. 면접 분위기는 온화한 분위기합/불 분석3차 충원 합격.아쉬운 점교과 관련 디테일한 질문에 대한 대응이 부족했던 것 같다."}],"naesin":"3.56","result":"충원합격","resultNote":"최초후 4 보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류종합평가 100% 【2단계】 1단계 성정 50% 면접 50%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"벤처중소기업학과","jeonhyeong":"학종/ssu 미래인재","method":"학생기부기반 면접","notes":"","qa":[{"q":"지원동기를 간단하게 말해주세요.","a":"안녕하십니까, 저는 숭실대학교 벤처중소기업 학과에 지원한 가번호 33번입니다. 저는 고등학교 3년 동안 저의 진로 계획을 실사구시 정신과 전 지구적인 코로나19의 환경문제의 세계화에 바탕을 두고 진로개척을 시작하였습니다. 또한 벤처중소기업학과의 기본이 되는 경영학이란 학문은 기업의 전반적인 가치를 이루는 중요한 학문일뿐더러 일상생활에서 가장 유용하게 사용되는 실용적인 학문이라고 생각합니다. 그래서 저는 숭실대학교만의 핵심가치인 실용주의와 세계화라는 두 단어를 보았을 때 가슴이 매우 뛰게 되어 숭실대학교의 벤처중소기업학과에 지원하게 되었습니다."},{"q":"고등학교 3학년때 시장조사를 하였다고 하는데 이때 가장 힘들었던 점에 대해서 말해보세요.","a":"저는 먼저 저의 창업 아이템의 시장 가치성을 파악하기 위하여 아파트 주민을 대상으로 하여 시장조사를 실시하였습니다. 이때 가장 힘들었던 점은 주민들의 참여를 유도하는 것이었습니다. 처음에는 전단지에 QR코드를 부착하여 엘리베이터 등에 전단을 돌렸습니다. 하지만 제 처음 생각과 다르게 주민들이 많이 참여해 주지 않아서 저는 아파트 입구에서 주민 한분 한분을 잡아가며 시장조사에 응해주실 것을 부탁하였습니다. 그 결과 많은 주민들을 대상으로 시장조사 데이터를 확보할 수 있었습니다."},{"q":"그럼 본인의 창업 아이템의 수익구조를 설명해보세요. 또 창업시작 비용에 대해 계산한 바가 있다면 설명해주세요.","a":"네, 저는 시장조사를 실시하였을 때 가격 적정선 또한 살펴본 바가 있습니다. 분리수거 대행서비스를 구독 서비스를 기반으로 하여 3회에 13,000원이 가장 적당하다고 설문 결과가 나왔는데 이때 13,000원을 3으로 나누게 된다면 사실 인건비조차 나오지 않는 것이 현실입니다. 그래서 저는 이것을 보완할 방법으로 가까운 동네 주민 할인 마케팅을 고안해 보았습니다. 위치기반 서비스를 바탕으로 하여 최단거리에서 최대 효용을 내기 위해 아파트 주민을 대상으로 서비스를 실시하고 같은 아파트에서 많이 서비스를 이용한다면 소비자에게 직접적으로 몇 퍼센트 할인이 되고 있음을 보여주는 마케팅 방식을 시작하겠습니다."},{"q":"그럼 정확한 창업비용은 계산해 보지 않은거죠?","a":"그 점 또한 계산해 보고 싶었지만 분리수거 대행 서비스라는 아이템을 가지고 창업을 진행하는 스타트업 회사들이 없어 정확한 데이터를 수집하지 못하였습니다. 이 부분은 숭실대학교 벤처중소기업학과에 들어와 교수님들의 수업을 이수하고 시너지라는 동아리에 들어가 동아리 부원들과 꼭 논의하겠습니다."},{"q":"환경에 기반한 경영에 대해서는 3학년 때부터 관심을 가지기 시작했는데 그 이유를 알 수 있을까요?","a":"저는 고등학교 2학년과 3학년 때 학생회 환경부 부원으로 활동하였습니다. 이때 학교의 분리수거가 정말 지켜지지 않고 학생들이 분리수거 방법에 대해 생각보다 무지하다는 사실을 알게 되었습니다. 이 이후부터 경영과 환경을 접목한 ESG경영에 많은 관심을 보이게 되었고 분리수거가 잘되지 않는다는 사실에 기반하여 이것을 창업아이템으로 만들 수 있지 않을까? 라는 생각을 하게 되었습니다. 이러한 생활 속에서의 활동을 바탕으로 하여 저는 창업아이템을 구상해내고 이를 실현시키기 위한 사업계획서를 3학년때부터 작성할 수 있었습니다."},{"q":"그럼 이 비즈니스 구조가 다른 사람들의 쓰레기를 대신 수거해서 버려준다는 건데 이게 현재 진행중인 쓰레기 분리수거 서비스와 차별점이 존재할까요?","a":"제가 생각하는 차별점은 타회사보다 환경을 더욱더 중점적으로 고려하는 점이 큰 차이점이라고 생각이 듭니다. 현재 사업 중인 많은 분리수거 대행 서비스는 고객들의 쓰레기를 수거해 각 아파트의 분리수거장에서 분리수거를 진행하는 것으로 알고 있습니다. 이 구조는 많은 문제를 자아내는데 쓰레기를 친환경으로 재처리하지 못하는 것이 가장 큰 문제점으로 꼽힙니다. 그래서 저의 창업 아이템인 분리수거 대행 서비스는 쓰레기를 친환경적으로 재처리하는 회사와 계약을 맺어 보다 환경을 우선순위에 두는 이념을 가지고 사업을 진행할 것입니다."},{"q":"우리 학과가 왜 본인을 뽑아야 하는지 설득시켜보세요.","a":"저는 저 자신을 무모한 도전을 즐겨하는 사람이라고 생각합니다. 모든일을 시작할 때 모든 사람은 작은 눈덩이에 불과합니다. 하지만 이 눈덩이가 내리막길, 즉 무모하게 시작한 하나의 도전의 과정을 거치며 긍적적인 혹은 부정적인 것을 얻고 그 부피는 커지게 됩니다. 눈덩이가 내려올 때 얻은 긍정적인 것은 제가 미래에 꿈으로 날아오를 수 있는 힘이 될것이고 부정적인 것은 제 삶의 이정표가 될것입니다. 무모하게 도전하고 무모하게 시작하겠습니다. 이 숭실대학교의 교정의 내리막길에서 비록 시작은 작은 눈덩이에 불과하겠지만 그 끝은 학교의, 학과의 자랑이 되는 멋진 눈사람이 되어있으리라 확신할 수 있습니다. 감사합니다. 면접 분위기가 매우 좋았고 교수님 두 분 중 한 분만 계속 질문하셨음. 질문하시는 분은 좀 특이점표정이 어두웠고 기록하시는 분은 표정이 매우 밝으셨음. 면접은 약 10분동안 진행함.3학년 진로활동에서 면접 질문이 모두 나왔고 꼬리질문 면접이였음.합/불 분석추가합격아쉬운 점"}],"naesin":"3.02","result":"충원합격","resultNote":"최초후 2 보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100% (3배수) 【2단계】 서류 70%+면접 30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"정치외교학과","jeonhyeong":"학생부종합/기회균형전형","method":"생기부 기반 면접 오전 08:30 입실완료 -> 08:30 – 09:00 대기 및 공지 / -> 09:00 – 09:30 대기 -> 09:30 – 09:40 면접 -> 09:40~ 종료 1. 기회균형전형임에도 불구하고 면접이 있으며, 비율도 50%로 높음","notes":"2. 명확하고 깔끔하게 답변하면 꼬리질문 하나 없이 넘어가지만, 자신의 생각을 말해야 하거나 모호하게 말한다면 꼬리질문을 자주 하시는 편","qa":[{"q":"숭실대학교 정치외교학과에 지원한 동기가 무엇인가요?","a":"진로가 중간에 바뀐 케이스였기에 교육계열에서 정치외교로 바뀌게 된 이유, 바뀐 후에 어떤 과정을 행해왔는지, 이후 이 학교에서 어떤 점을 배워나가고 싶은지 등을 이야기함. (이 과정에서 지리에 관심을 가졌다가 자연스레 국제정치, 외교 등으로 관심분야가 넓어져갔다는 내용도 포함시킴)"},{"q":"(2학년 자율활동 질문) AI가 한국정치가 이용될 경우 어떤 장단점이 있는지 설명하세요.","a":"장점은 다양한 시민들의 의견을 통계적으로 수용할 수 있다는 점, 단점은 가짜뉴스를 접한 AI가 확증 편향으로 인해서 잘못된 정보를 퍼뜨려 민주적 숙의과정이 망가질 수 있다는 점을 언급함."},{"q":"(2학년 국제관계와 국제기구 과목 질문) 해당 과목을 공동교육과정으로 들은 것 같은데, 이 과목에서 배웠던 내용 중 인상깊었던 부분과 그 이유를 이야기해주세요.","a":"세계무역기구(WTO)를 탐구한 내용에 관심을 가졌다고 답함. 그 이유를 물으시는 추가 질문에 WTO가 국제 무역의 흐름을 주도한다는 내용과 무역을 통한 수익 창출을 목표로 한다는 특징을 가졌지만 자국들의 이익만을 과도하게 추구한다는 단점이 있는 것을 배웠던게 인상깊었다고 답함."},{"q":"(3학년 세계지리 과목 질문) 이집트가 난민 수용 거부를 했다고 적혀있는 내용이 있는데, 이 내용이 무엇이었나요?","a":"이스라엘과 하마스의 분쟁으로 인해 이집트에 대규모의 팔레스타인 난민이 들어오고자 했으나, 난민을 수용할 여건이 마땅치 않다는 이유로 이집트가 거부했음을 설명하고 전쟁이 난 경우에는 난민을 수용해야 한다는 국제법 같은게 있는데 이걸 위배했다는 식으로내용 설명함."},{"q":"(세계지리 추가 질문 1) 본인은 난민 수용 문제에 대해 어떻게 생각하나요?","a":"긍정적으로 생각한다고 답함. 난민들을 수용함으로써 선진국에 부족한 노동력을 확보할수 있고 문화적 다양성을 증진시킬 수 있기 때문이라고 생각했다고 밝힘."},{"q":"(세계지리 추가 질문 2) 그런데 난민을 수용함으로써 발생할 수 있는 범죄 문제도 있지않나요?","a":"물론 문제가 일어날 수 있는 점은 명백하지만, 정부 기관 및 다양한 기관들의 참여로 올바른 교육 지원을 활성화하면 괜찮아질 것이라고 생각하기에 부정적인 측면이 있어도 극복할 수 있을 것이라고 답했던 것으로 기억함."},{"q":"숭실대학교에 오면 무엇을 하고 싶나요?","a":"국제교류 프로그램이라고 답하고 정치외교를 탐구해온 특성상 국제학술교류와 공공외교 등에 관심을 가졌기에 언어, 문화 등의 교류를 통해 관심사를 넓혀갈 수 있을 거 같다고 답변함."},{"q":"준비한 질문은 끝났는데 혹시 더 마지막으로 하고 싶은 말이 있나요?","a":"진로에 대한 일관성이 떨어진다는 점이 단점이었지만, 이 단점을 기회삼아 다양성을 바탕으로 관심사를 높이고(이때 숭실대 정치외교 인재상으로 들어있던 거 여러 개 말함) 숭실대라는 넓은 세상에서 큰 꿈을 키워나가고 싶다고 함. 이후 꿈을 위한 여정이 헛되지 않게 숭실대에서 발걸음을 시작할 수 있길 바란다는 말로 마무리함.1. 면접 시간이 15분 내외라고 했는데, 면접 시작 직전 시간과 종료 직후 시간을 특이점비교했을때 10분 밖에 지나있지 않았던 것으로 기억함.2. 면접 시작 직전까지도 면접 준비 자료를 열람할 수 있게 해주셨음.합/불 분석추가합격질문을 주셨을 때 세특에 적혀있는 내용을 답변하기보다는 나만의 새로운 답변과 아쉬운 점가미시켜서 답변하는 게 좋았을 것이라고 생각했지만, 외운 내용들을 그대로 답변한 느낌이 드는 것 같아 아쉬운 느낌이 있었음."}],"naesin":"2.75","result":"충원합격","resultNote":"최초후 3 보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100% 【2단계】 서류 50% + 면접 50%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"컴퓨터학부","jeonhyeong":"학생부종합/SSU미래인재","method":"학생부기반면접 / 학원 교실만한 방에서 15분동안 2:1 면접.","notes":"","qa":[{"q":"자기소개랑 지원동기 말해보세요.","a":"제가 가장하고 싶은 일은 사회에 공헌하는 게임이나 AI를 만드는 것입니다. 그걸 위해 학교생활에 ~~(학생부에 기재된 활동)를 했습니다. 이러한 꿈을 확장하고자 찾아본 곳이 숭실대입니다. 숭실대는 최초의 전산학부 ~~(숭실대 설명) 또한 커리큘럼에서 3학년 2학기부터 AI를 배우는데 이 수업에서 내가 고등학교 시절 간이 챗봇을 제작하며 막혔던 개념을 해소하고 싶다. (이후에도 건학이념이나 인재상 키워드 넣어서 좀 더 대답.)"},{"q":"수학과제탐구랑 프로그래밍이 어떤 과목인가.","a":"수학과제탐구는 일상 속에서 여러 문제를 발견하고 그 문제에 대해 다루는 과목이었습니다. 예시로 페르미 추정이라고 간단한 전제를 세워서 실제 답과 근사한 답을 도출해 내는 것이 있는데 이를 이용해 서울에 버려진 담배꽁초를 계산하는 과정을 거쳤습니다. 프로그래밍은 공동교육과정으로, 처음엔 인공지능수학을 선택하려 했으나 학교에 이미 개설되어 있어서 좀 더 기초를 다지고자 선택했습니다. 수업 마지막엔 스스로 프로그램을 만드는 시간이 있었고 난 여기서~(이후 프로그램 설명까지)"},{"q":"C언어를 배웠다고 하는데 포인터의 기본개념 간단하게 설명해봐라.","a":"...처음 배울 때도 어려운 개념이었다보니 잘 기억에 나지 않는다. 하지만 숭실대는 1학년 2학기 때 C언어와 관련된 수업이 열려있는 것으로 알고 있다. 그곳에서 다시 배워가고 싶다."},{"q":"프로젝트 중 어려웠거나 기억에 남는 활동 설명. 극복 과정이 있으면 그것도 설명.","a":"3학년 때 했던 간이 챗봇 활동이 가장 기억에 남았던 거 같습니다. (이후 생기부 기반으로 미리 준비한 내용. 책 보고 만들 때 직접 썼던 사이트 및 전체적인 제작 과정 설명)"},{"q":"진로에 영향을 미친 활동이 있나요? 만약 있다면 그 활동에선 어떤 역할을 했나요?","a":"3학년 동아리 시간에 했던 게임 제작 활동이 가장 기억에 남습니다. (이후 생기부 기반으로 미리 준비한 내용. 주요 코드나 생각했던 알고리즘 같은 거, 게임 제작하면서 막혔던 부분을 해결한 거 주로 설명)"},{"q":"게임제작 과정에서 난이도를 어떻게 조절했나요?","a":"우선, 발사되는 오브젝트의 개수랑 속도에 대해서 생각했습니다. 거기에 추가로 한 방향으로만 발사되면 친구들이 진부하다 느낄거라 생각해, 랜덤함수를 이용해 방향을 바꿔 난이도를 조절했던 기억이 있습니다."},{"q":"2학년 미적분 시간에 인공지능 관련 활동을 하셨는데 이 경사하강법이라는게 미적분과 연관 있을까요?","a":"미적분이라는 과목은 이름대로 미분과 적분을 다루는 과목인데요, 경사하강법이라는 게 기울기를 구해서 기울기가 양수면 X값을 줄이고 기울기가 음수면 X값을 늘려 최소값을 찾는 기법이라고 알고 있습니다. 그렇게 때문에 기울기를 구할 때 미분이 쓰이므로 미적분이라는 과목과는 많은 연관이 있다고 생각합니다."},{"q":"경사하강법은 사용하면 문제점이 발생하잖아요? 그런 문제는 어떻게 해결하나요?","a":"최솟값을 찾아내야 하지만 극솟값에 문제가 발생하는 것으로 알고 있습니다. 이를 해결하기 위해선 극솟값에 갇히지 않게 하기 위해 함수 전체의 폭을 조절하거나, 음... 선택적 경사하강법이라는 것을 사용한다고 들었습니다. 이 내용에 대해서는 자세히 알고 있지는 않기 때문에 대학에 가서 기회가 된다면 더 깊이 배우고 싶습니다."},{"q":"시간이 다 되어갑니다. 마지막으로 하고 싶은말 해주세요.","a":"숭실대에 진학해서 겜마루라는 동아리에 들어가 게임 제작을 해보고 싶습니다, 숭실대는 전국 64개국에 421개의 자매대학을 두고 있는 것으로 알고 있습니다. 이를 바탕으로 교환학생 프로그램도 적극 활용하여 세계적으로 견문을 넓히고 싶습니다. 등등 준비했던 것 중 남은 것들 빠르게 대답.Ÿ 면접 준비하면서 아침 뭐 먹었냐 같이 긴장풀이용 질문도 연습했었는데 그런 질문 없이 바로 지원동기로 시작했다.특이점Ÿ 비슷한 유형을 모아서 질문해줬다. 자기소개랑 동기를 따로 질문하는 대학도 있다고 하는데 여기는 모아서 해줬다. 다른 질문에서도 어려웠던거나 진로에 영향 미쳤던거, 기억에 남는걸 한 질문에 모아서 해줘서 하나의 핵심 활동에 대해 깊이 있게 설명할 수 있었다.합/불 분석Ÿ 생기부 내용 확인하는 질문에 지나치게 길게 답하면서 시간을 썼던게 아쉽다.Ÿ 프로그래밍 과목이랑 수학과제탐구에 대한 질문에서 그렇게 느꼈다.Ÿ 따로 어필해야할 활동이 많다면 간단한 생기부 확인 질문들은 그 자리에서 판단해 빠르게 아쉬운 점넘기는게 중요할거 같다.Ÿ 지원동기에 다 우겨넣다보니 많이 길어진거 같다. 2분 정도 말했다. 그래도 이 학교에 오고 싶단 걸 어필하려면 이때가 제일 나을 거 같아서 준비한 거 다 말했다.Ÿ 포인터의 기본개념 같은 질문은 모르는 부분이어서 말도 떨고 좀 횡설수설한 감이 있다."}],"naesin":"2.31","result":"충원합격","resultNote":"최초후 8 보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류형 100% 【2단계】 1단계 50%/ 면접 50%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"철학과","jeonhyeong":"학생부 종합 / ssu 미래 인재","method":"생기부 기반 면접 / 15분 면접","notes":"","qa":[{"q":"윤리 교육에 관심이 많았던 것 같은데 교사 그리고 수업 내용 중 어떤 부분에 관심이 있었던 건가요?","a":"사실 처음에는 선생님께 가장 큰 관심을 가지고 있었던 것 같습니다. 교과서의 내용뿐만 아니라 각 사상가의 저서의 내용을 인용하면서 저희의 이해를 돕고자 노력해 주셨습니다. 이런 선생님의 수업 방식에 큰 흥미가 생겼고 이는 곧 윤리 과목에 대한 관심으로 이어졌습니다. 그러면서 점점 사상가들에게 관심이 생기고, 나중에 들어선 스스로 사상가들의 저서까지 찾아보게 되었습니다. 처음엔 선생님에 대한 관심이 컸지만, 나중에 들어선 윤리 과목에 대한 관심이 더욱 커졌습니다."},{"q":"철학과로 오지 않아도 철학을 공부할 수단은 많다고 생각하는데, 굳이 왜 철학과로 진학하고자 했나요?","a":"제가 철학과에 진학하고자 한 이유는 철학을 배우고자 하는 열망이 매우 커졌기 때문입니다. 다양한 매체를 통해 철학을 공부할 순 있겠지만, 철학에 대한 제 열망과 흥미를 해결하고 심도있게 학습하기 위해선 철학과에 진학하는 것이 가장 좋은 방법이라고 생각했습니다."},{"q":"많은 학교 중 숭실대학교를 선택한 이유를 얘기해주세요.","a":"숭실대학교는 깊은 역사와 전통을 가진 기독교 학교입니다. 이런 숭실대학교에 제가 지원하게 된 이유는 제가 숭실대학교에서 가장 제 역량을 크게 발휘할 수 있을 것이라고 생각하였기 때문입니다. 숭실대학교는 과거 유교 국가이던 조선에 기독교적 가치를 접목하여 발전에 기여한 역사를 지니고 있습니다. 저는 조선의 발전에 기여한 숭실대학교처럼 현대 사회에 유교적 가치를 접목하여 세계의 발전에 앞장서고자 하는 목표를 가지고 있습니다. 동양 철학에 깊은 관심을 가지고 있는 제가 기독교적 가치를 중시하는 본교에 입학한다면 숭실대학교의 가치를 계승하고 동시에 발전시키는 인재로 거듭날 것입니다."},{"q":"철학 관련 활동이 상당히 많은데 학생들을 대상으로 시행한 루소와 장자 캠페인에 대해 알려주세요.","a":"루소와 장자 캠페인은 학생들의 자아존중감을 향상시키기 위한 목적으로 기획한 활동입니다. 루소와 장자는 외물에 집착하는 현실이 아닌 자연을 강조하고 있습니다. 저는 이러한 두 사상가의 모습에서 학생들이 외적 가치보다 내적 가치에 집중할 수 있는 계기를 찾게 되었고, 학생들의 자아존중감 실태에 대한 설문조사를 시행한 후 이에 대한 결과와 루소와 장자의 사상을 토대로 내적 가치를 존중해야 한다는 내용의 포스터를 게시하였습니다."},{"q":"숭실대학교의 수업 이외의 활동 중 해보고 싶은 활동이 있나요?","a":"중앙 도서관에서 시행하는 독서 세미나에 참여해보고 싶습니다. 철학은 다양한 관점을 접하고 이해하려는 노력이 필요한 학문입니다. 독서 세미나에서의 토론을 통해 다양한 사람들의 가치관, 관점을 접하며 시야를 넓히고 싶습니다."},{"q":"철학과에 진학할 시 좋은 직업, 수입을 갖기 힘들 수도 있습니다. 이 사실을 알고 학과에 지원하셨나요?","a":"네, 알고 있었습니다. 철학에 대해 흥미는 항상 가지고 있었으나 그 사실은 제가 이를 진로로 삼는 데에 있어 큰 망설임을 주었습니다. 하지만 3학년에 들어서며 제가 철학이 아닌 다른 진로를 가지게 된다면 저 자신이 행복할 수도, 그 일에 최선을 다할 수도 없다는 생각이 들었습니다. 지금의 저에겐 철학에 대한 열망이 가장 크고, 또 중요한 것 같습니다."},{"q":"철학의 다양한 분야 중 어떤 분야에 가장 관심이 있나요? 그리고 그 이유를 알려주세요.","a":"동양 철학에 가장 큰 관심이 있습니다. 본래 저는 한국사나 동아시아권의 역사에 대한 관심이 많은 편이었습니다. 이러한 역사를 공부하는 과정 중에서 자연스럽게 동양의 사상을 접할 기회가 많아졌고 이는 동양 철학에 대한 관심으로 이어지게 되었습니다."},{"q":"본 학교가 지원자를 뽑아야 하는 이유가 있나요?","a":"저는 기독교적 비전을 가진 숭실대학교에 동양 철학의 가치를 접목하여 보다 더 큰 발전을 이뤄낼 수 있는 인재로 숭실대학교 철학과에서 제 역량을 가장 많이 발휘할 수 있을 것입니다."},{"q":"마지막으로 하고 싶은 말이 있다면 해주세요.","a":"저는 현대에서 잊혀져 가고 있는 동양 철학에 대해 강점을 가지고 있습니다. 이런 제 강점은 숭실대학교에서 가장 빛을 내며, 발전의 도모에 크게 기여할 수 있을 것입니다. 숭실대학교의 가치를 계승하고, 발전시키는 인재가 되겠습니다.특이점2개의 면접방을 동시에 운영하였다. 면접 시간이 15분으로 꽤 길었다.합/불 분최초합석아쉬운 점"}],"naesin":"3.49","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계 50 + 면접 50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"국어국문학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"면접실 입실 → 대기 → 면접 → 귀가 / 면접시간 10분~15분 / 면접위원 2명","notes":"긴장을 풀어주기 위해 분위기가 매우 편함 · 첫 질문이 연습하면서 만들어 본 질문임","qa":[{"q":"혹시 면접 준비하면서 질문 만드신거 있으신가요? 무엇인가요? -> 그럼 그 질문에 대해 물어보겠습니다.","a":"저는 국어를 좋아하게 계기와 지원 계기를 준비하였습니다. 저는 어릴 적부터 국어에 관해 관심이 많았습니다. 저는 고등학교에 들어와서 중세 국어라는 개념을 배우면서, 현재 쓰고 있지 않는 단어나 의미가 변화한 단어 그리고 음의 높낮이 등을 배우게 되면서 저의 국어에 대한 관심도는 더욱 높아졌습니다. 저는 숭실대학교 국문학과에 지원을 해서 고전 소설론, 고전 시가론 등 고전 글쓰기 수업을 들으면서 저도 고전 문학을 토대로 소설을 써보고 싶습니다. Q1-1: 아 그러면, 역사적인 문학을 쓰고 싶다는 군요? 고전문학 중에서 본인이 관심이 있는 문학이 있을까요?저는 고전 문학 중에서 가전체 문학에 관심이 많았습니다. 공방전을 읽었을 때, 엽전이라는 돈을 의인화하여, 세대에서 돈으로 인한 부패 상황을 이야기하였습니다. 이 부분이 흥미로웠던 점은 현재도 돈으로 발생하는 문제점이 많았기에 흥미롭게 읽었습니다."},{"q":"어휘토론캠프를 활동하셨다 했는데 어떤 활동이었나요?","a":"어휘 토론 캠프에서 저는 여러 개의 단어를 한 개의 특징으로 묶어서 학생들에게 설명하고 학생들이 무슨 단어를 알아 맞춰보는 시간을 가졌습니다. 저는 이 과정에서 여러 개의 단어를 한 개의 특성으로 설명할 수 있게 되었습니다.Q2-1: 게임식으로 활동을 한건가요?게임식으로 오해를 받을 수 있지만, 학생들이 그것을 맞추는 과정에서 이것이 무엇인지를 토론을 하는 과정을 가지게 되었고, 또한 어떤 단어로 묶으면 좋을지 생각을 하는 계기가 되었습니다."},{"q":"자신의 장점은 무엇인가요?","a":"저의 장점은 긍정적인 모습이 많다고 생각합니다. + 예시 설명 저는 리더십이 많습니다. 저는 1학년때부터 3학년때까지 반장을 하면서, 아이들과의 회의가 필요한 상황에서 서로의 의견을 조율을 더 잘 할 수 있도록 이끌어 주었습니다."},{"q":"마지막으로 한마디 있으실까요?","a":"저는 국어국문에 관해서는 언제든지 달려갈 수 있는 열정이 있습니다. 저는 숭실대학교 국어국문학과에 지원을 해서, 숭실대학교 관한 국어국문학과에 관한 많은 수업을 듣고 싶을 정도로 열정이 많습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"물리학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"생기부 기반 면접 / 면접시간 10분 내외 / 면접위원 2명","notes":"관심분야에 대한 질문이 빈출됨. · 전공적합성을 50% 반영함.","qa":[{"q":"지원동기, 굳이 숭실대에 지원한 이유, 요즘 이슈","a":"물리학1 수업시간에 배운 ‘전류에 의한 자기장’의 크기를 ‘고급 물리학’ 수업시간에 배운 비오-사바르 법칙을 통해 자기장의 크기를 수학적으로 계산하는 것에서 흥미가 높아져서 물리학과에 지원하게 되었습니다.숭실대의 슬로건인 ‘창의적 융합을 선도하는 대학’이 마음에 들었습니다. 기초학문을 공부해 나의 관심 분야인 전자, 반도체 관련의 응용학문을 연계하여 공부하는데 적합한 학교인 것 같아 지원하게 되었습니다.이공계 관련 예산 삭감 --> 장래의 나의 진로(반도체 연구 및 개발)에 부정적인 영향을 미칠 것 같다."},{"q":"반도체 관련 기업에서 일하고 싶다고 했는데, 반도체의 개념과 도체, 반도체, 부도체의 차이를 설명해라","a":"반도체는 도체와 부도체의 중간의 성질을 가진 물질입니다. 대부분 14족 원소인 규소와 같은 물질을 사용해서 제작하고 13족, 15족 원소들을 이용해서 도핑을 해 실사용합니다.에너지 띠 이론으로 차이를 설명할 수 있습니다. 원자가띠와 전도띠의 사이의 띠틈의 크기가 거의 없으면 도체, 조금 있으면 반도체, 크면 부도체로 설명할 수 있습니다."},{"q":"교과과정의 ‘물리학2’의 학습을 다 한 것 같지 않은데, 어떠한 방식으로 학습했나","a":"학교의 교육과정 상 3학년 1학기까지 모든 과정을 마무리해야 했기에 선생님께서 트랜지스터까지의 내용까지만 가르쳐 주셨습니다. 그 이후의 내용은 자습을 통해 학습했습니다.Q+: 자습한 내용 중에서 가장 기억에 남는 내용물리학1 시간에 배웠던 ‘광전효과’를 다시 본 것이 기억에 남습니다. 조금 더 개념을 심화시켜 공부한 것 같아 기억에 남습니다."},{"q":"반도체를 공부하려면 공과대학에 지원하는 것이 더 유리하지 않았나. 왜 물리학과에 지원하게 되었는가","a":"자기장의 크기를 비오-사바르의 법칙을 통해 수학적으로 계산해 나가는 과정이 재밌다고 생각했습니다. 복잡한 증명 과정들을 통해 현상 하나하나를 설명하려는 것이 정말 재밌었습니다."},{"q":"공과대학은 수학을 사용하지 않냐","a":"저는 공과대학과는 다른 자연 그 자체를 설명하는 것에 흥미를 느꼈습니다. (뒷 말이 잘 기억이 나질 않습니다.)"},{"q":"마지막 할 말","a":"제가 고등학교 3년동안 물리학에 대한 흥미를 키우고 기초를 열심히 다졌다면, 이제는 심화된 학습과 실험을 통해 물리학에 대한 열의를 불태우고 싶습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"물리학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"신분 확인 → 대기실 입실 → 면접 → 설문조사 → 퇴실 / 면접시간 10분 / 면접위원 2명","notes":"학교생활기록부에는 없는 전공 관련 질문이 나올 수 있으므로, 물리학Ⅰ의 내용은 어느 정도 숙지해야 함. · 대기실에서는 학교생활기록부, 도서 정도는 볼 수 있으나, 전자기기는 사용하지 못함.","qa":[{"q":"자기소개와 지원동기를 말해보세요.","a":"저는 천체물리학에 관심이 많은 학생입니다. 우선, 물리학은 물리학적 지식과 궁금증을 가지고 펜과 종이만 있으면 우리 주변에 자연현상들을 규명하고 정리할 수 있다는 것에 큰 매력을 느끼게 되었습니다. 그리고 그중에서 저는 우주 자체나 우주에 있는 천체들의 운동을 규명하는 천체물리학이라는 분야에 관심을 가지게 되었습니다. 그리고 숭실대에 대해 찾아보니 같은 물리학과에 진학하게 되더라도 향후 어떤 직업을 갖느냐에 따라서 서로 다른 대학 커리큘럼을 따라갈 수 있다는 것을 알게 되었습니다. 천체물리학자의 길을 걷고 싶은 저는 학자가 되기 위한 공부를 더 깊고 체계적으로 공부할 수 있어서 숭실대에 지원하게 되었습니다."},{"q":"숭실대에 커리큘럼에 대해 말하는 것을 보니 숭실대 홈페이지를 잘 숙지해온 것 같아요. 그럼 숭실대 홈페이지를 보면서 숭실대에 대해 가장 기억에 남는 것을 말씀해주실 수 있나요?","a":"숭실대 물리학과에 천체물리학과 일반상대성 이론에 대해 연구하고 계시는 교수님이 있다는 것이 가장 기억에 남았습니다. 이를 보며 숭실대에 오면 물리학에 관해 깊고 체계적으로 공부를 할 수 있을 뿐만 아니라 천체물리에 관한 공부도 깊이 있게 할 수 있다고 생각이 들어서 숭실대에 꼭 오고 싶은 이유이기도 합니다."},{"q":"위쪽 방향으로 물체를 던질 때, 이 물체가 운동의 최고점에서 받는 가속도의 크기는 얼마입니까?","a":"물체가 연직방향으로 운동할 때, 역학적 에너지 보존에 의해 운동이 시작되며 얻은 운동에너지가 최고점에서 모두 위치에너지로 바뀌며 물체는 그 순간 속도가 0이여서 정지하게 됩니다. 그러나, 연직운동에서 물체에게 항상 연직 아랫방향으로 중력이 작용하게 됩니다. 그래서 최고점에서도 마찬가지로 중력이 작용하여 발생하는 가속도인 중력가속도 즉, 9.8m/s^2만큼 연직아래 방향의 가속도를 받고 있습니다."},{"q":"천체물리학을 좋아한다고 말했는데 자신이 했던 활동 중에서 천체물리학적으로 중요하다고 생각한 활동을 소개해보세요.","a":"2학년 물리1 시간에 했던 마이컬슨-몰리의 에테르 증명 실험과 중력파 관측의 연관성에 관한 탐구가 가장 중요하다고 생각합니다. 두 실험을 공부하다보니 ‘두 실험의 과정을 같지만 결과는 왜 다를까?’라는 생각을 하게 되어 이를 토대로 탐구를 직행하게 되었습니다. 탐구를 해보니 결국, 마이컬슨-몰리는 에테르라는 새로운 가상의 매질을 ‘발견’하기 위해 실험을 진행한 것이고 중력파는 시공간이 왜곡된 것을 ‘관측’하기 위해 간섭계를 사용하여 실험을 진행했습니다. 결국, 실험 목적이 다르니 실험 결과도 다를 수밖에 없다는 것을 알게 되었습니다."},{"q":"마이컬슨-몰리실험에서 간섭계가 어떤 식으로 작동하는지와 실험방법을 한 번 설명해줄 수 있으세요?","a":"간섭계라는 것은 광원에서부터 나온 빛이 반거울을 지나며 두 빛으로 갈라지게 되고 같은 거리에 각각 놓여있는 거울에 의해 반사되어 다시 반거울로 와서 두 빛이 합쳐지며 검출기에 도달하게 되는 작동 과정을 거칩니다. 이때, 에테르라는 매질이 존재하거나 시공간의 왜곡이 발생하면 두 빛 중, 한 빛의 이동거리가 더 길어지며 나중에 검출기에서 다른 빛과 합쳐지게 될 때 간섭무늬가 나타납니다. 이를 관측하여 발견한 것이 중력파입니다."},{"q":"좋습니다. 저희 숭실대에서는 정말로 물리를 좋아하는 학생을 뽑고 싶습니다. 여기 학생의 생기부에 정말 많은 물리학적 활동들이 적혀있는데요, 해본 활동 중에 ‘나는 이것까지 해봤다!’ 하는 활동이 있으면 소개해주세요.","a":"포물선운동에서 포물선운동의 초기 속도와 초기 각도 값을 알면 물체가 포물선운동을 할 때 이동 거리, 최고 높이, 각 순간에 운동량, 속도 운동 방향 등의 그 운동에 대한 모든 것을 알 수 있는 포물선운동 방정식이 있습니다. 이 방적식을 통해 저는 ‘실제로 이 운동과 관련한 모든 물리량을 알 수 있을까?’라는 근본적인 의문이 들어서 이를 실험적으로 증명하는 실험을 3학년 동아리 시간에 한 적이 있었습니다. 이때, 초기 각도를 정확하게 하여 물체를 운동시키는 부분에서 어려움을 느꼈는데요. 이를 정확한 각도로 물체를 포물선운동을 시키는 투석기를 고안하여 이 문제점을 해결하였습니다. 실제로 쇠구슬을 이용해 포물선운동을 만들어서 이를 동영상으로 찍은 뒤, 단위 길이마다 운동에 관한 모든 물리량을 관측하여 이를 다시 포물선 방정식에 대입하여 방정식이 맞는지 확인하는 과정을 거쳤습니다."},{"q":"마지막으로 하고 싶은 말 있으면 하세요.","a":"지원 동기 때, 말씀을 못 드렸지만 저는 시공간이 왜곡되는 현상들을 통해 시간의 본질을 규명하는 연구를 하고 싶습니다. 숭실대에서 물리학과 천체물리학 지식을 깊이 있게 쌓은 뒤, 숭실대에 있는 우주물질연구소에 들어가서 이에 대해 연구하고 싶습니다. 감사합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"사회복지학부","jeonhyeong":"학생부종합(SSU미래인재)","method":"대기실 입실 → 신분 확인 후 대기 → 면접 → 퇴실 / 면접시간 10분 내외 / 면접위원 2명","notes":"2:1 진행, 한 분은 교과활동중심, 한 분은 지원동기 및 느낀점, 생각 위주로 질문하심. · 학과에 지원한 동기뿐 아니라 이 학교에 지원한 이유 등 학교의 장점, 프로그램을 숙지하면 도움이 될 듯함. · 예상 질문이 들어온 건 기본질문(지원동기)밖에 없었음. 반복적으로 읽어 생기부 내용을 숙지하는 것이 현장에서 중요할 듯.","qa":[{"q":"청소년 일탈을 차별교제이론으로 설명한다면","a":"청소년이 가정 밖으로 나가게 되고 그 과정에서 일탈집단과 접촉하여 집단에 합류하게 된다고 설명함.Q1-2: 한국 사회를 차별교제이론으로 설명한다면 한국 사회의 빠른 성장으로 개인을 사회의 부속품처럼 여기는 분위기가 일탈집단과 접촉하는 과정과 유사하다고 생각했음을 밝힘."},{"q":"이 학교에 지원한 동기","a":"학교에서 운영하는 학술연구동아리,학술제 등 여러 교류활동들이 꿈을 실현하는 데 도움이 될 것이라 생각해 지원했음을 설명함."},{"q":"여성관련 책을 읽고 느낀점","a":"외적인 면을 추구하기보다는 개인의 내면이 중요하다고 답함. Q3-1: 그렇다면 이를 위해 어떻게 해야하는지?취미활동이나 자신이 하고 싶은 일을 배우는 등 외적인 면보다는 내적인 면을 중요시하는 활동을 위주로 걸명함.Q3-2: 자신도 그런 경험이 있는지?취미인 그림그리기를 토대로 그런 생각을 하게 되었다고 답함."},{"q":"보편복지와 선별복지의 대표적인 예시","a":"보편복지는 무상급식, 선별복지는 빈곤가정 기본지원금이라고 답함."},{"q":"사회복지사가 되기 위해 자신이 가진 역량이 있다면","a":"사회복지사에게 필요한 요소 중 하나가 객관성이라고 답함."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"","jeonhyeong":"학생부종합(SSU미래인재)","method":"대기실 입실 후 신분 확인(가번호 확인) → 대기 → 면접 → 퇴실 / 면접시간 10분 / 면접위원 2명","notes":"한 대기실에서 다른 과 친구들과 같이 대기 · 대기인원이 많으면 1~/21~ 동시 진행 · 대기시간동안 자소서나 생기부, 책 볼 수 있고 전자기기는 사용 못함. · 생기부 내용 확인 질문 많지 않았음.","qa":[{"q":"자기소개 간단히 해보세요","a":"저는 적극적인 자세로 반도체 엔지니어로서 첨단 산업의 선구자가 되고싶은 가번호 28번입니다."},{"q":"미적분이 물리에 사용되는게 뭐가 있어요? (대답 못 하니까) 예를 들면 속도나 뭐 그런 거","a":"(몰라서 위치, 속도, 미분 관련해서 얘기하고 넘어갔어요)"},{"q":"그럼 확통에서 독립시행이 뭐예요?","a":"..잘 모르겠습니다"},{"q":"하고 싶은 게 뭐냐는 식으로 물어보셔서","a":"시스템반도체 공부해서 우리나라의 반도체 점유율을 높이고 싶다고 대답"},{"q":"전자공학이 뭐라고 생각해요? 그러니까 자질 뭐 그런 거","a":"협업 능력이 중요하다고 생각합니다. 그룹으로 이루어지는 활동이 많다고 알고 있어서 팀원들과 협력하고 소통하는 능력이 필요할 것 같습니다."},{"q":"학교에서 반도체 꿈 가지는데 영향 준거 하나 얘기해보세요","a":"물리학에서 배운 축전기가 반도체에 흥미를 확실히 하는 데 도움을 준 것 같습니다."},{"q":"동아리 3학년 때 뭐했어요?","a":"동아리 시간이 많이 주어지지 않아서 각자 탐구를 진행하였습니다. 저는 euv와 플라스마의 관계에 관해 탐구했습니다."},{"q":"1, 2학년 땐 원더앤파인드네요? 궁금하고 찾자 뭐 그런 거?ㅎㅎ 가장 기억에 남는 활동 있어요?","a":"마그누스 효과 실험이 기억이 납니다. 마그누스 효과란 물체가 유체 속에서 특정 방향으로 이동할 때 이동 방향의 수직으로 힘을 받아 경로가 휘어지는 것을 말합니다. 저는 종이컵과 고무줄을 이용하여 물체의 운동을 구현하였습니다."},{"q":"종이컵이랑 고무줄로? 자세히 설명해줄 수 있어요?","a":"종이컵 두 개를 붙이고 고무줄을 사용하여 날림으로써 마그누스의 효과를 구현하였습니다."},{"q":"반도체를 못 하게 되면 뭘 하고 싶어요?","a":"반도체.. 산업 쪽을 더 공부하고 싶습니다. 세계적으로 기업과 기업이 서로 어떤 영향을 미치는지와 같은 것을 공부해보고 싶습니다."},{"q":"아 이거는 저도 궁금하네요. 웨이퍼가 원인 이유가 뭐예요?","a":"웨이퍼는 실리콘을 녹인 후에 돌리면서 들어 올려 잉곳을 만들고 이를 잘라 웨이퍼를 만들기 때문에 원이 됩니다. 만약 사각형으로 만들고자 한다면 다시 녹인 후에 굳혀야 해서 순도가 낮아져서 원으로 사용하게 됩니다."},{"q":"이건 수업 시간에 한 거에요 따로 한 거에요?","a":"따로 탐구하였습니다."},{"q":"여행지리에서 실리콘밸리~ 했다고 하는데 이건 직접 갔다 온 거에요?","a":"아니요. 계획만 구상한 겁니다."},{"q":"그럼 우리나라에 실리콘밸리와 같은 곳이 생긴다면 어디가 좋을 것 같아요? (망설이니까) 그냥 개인의 생각이니까~","a":"평택..이 좋을 것 같습니다. (하니까 두 분이 웃으셨어요)"},{"q":"마지막으로 하고 싶은 말 있으면 하세요","a":"우선 면접 볼 수 있게 기회 주시고 잘 들어주셔서 감사합니다. 최선을 넘어서 최고를 향하여! 꼭 숭실대학교에 입학해서 최고가 되기 위해 노력하고 싶습니다!예ㅎㅎ 추운데 수고하셨습니다생기부 기반으로 많이 나올 줄 알고 생기부 내용 숙지하고 갔는데 오히려 제 생각 묻는 질문이 많았어요. 또 꼬리질문 식으로 이어질 줄 알았는데 답변 내용이 구체적이지 않아도 그냥 넘어가고 다른 질문 하셨어요. 첫 질문으로 미적분, 확통 질문이 나왔는데 생기부에 언급되어있는 내용도 아니고 그냥 과목을 수강했다는 것만으로 나온 질문인 것 같아요."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"","jeonhyeong":"학생부종합(SSU미래인재)","method":"신분 확인 → 대기실 입실 후 대기 → 면접 → 퇴실 / 면접시간 10분 / 면접위원 2명","notes":"한 대기실에서 다른 과 친구들과 같이 대기 · 대기 시간 동안 자소서나 생기부, 책 볼 수 있고 전자기기는 사용 못 함. · 수험번호에 따라 미리 지정된 면접 번호가 있음. 가끔 번호를 잘못 알려주는 상황이 있을 수 있으니 자리 위의 번호표 뒷면의 수험번호와 자신의 수험번호를 잘 비교해 보시길.","qa":[{"q":"우리 학교 전자공학과에 왜 지원을 하였나요?","a":"항상 컴퓨터, 전자 등 분야에 관심을 가져왔었습니다. 2학년 RTL-SDR 활동을 자율적으로 계획함을 통해 전자과에 와야겠다고 다짐했습니다."},{"q":"3학년 말에 수학 성적 급감은 왜 그런것인가요?","a":"계산이 좀 느린 편이라 그랬습니다, 이를 극복하기 위해 계산 연습과 수학 과제 탐구 과목에서 나타나는 원리 이해 등을 통해 수학적 통찰력을 기르려고 노력했습니다."},{"q":"트랜지스터의 원리는 무엇인가요?","a":"(트랜지스터의 원리 설명)"},{"q":"내성적임에도 불구하고 반장, 부반장 활동을 했다고 되었는데. 내성적이면 활동하는 것이 힘들지 않았나요?","a":"저는 내성적이지만 사회성은 충분했습니다. 또한, 저의 리더십 역량을 기르는 것이 중요하다고 생각하여 지원하였고, 실제로도 활동 과정에서 리더십 역량이 많이 길러졌다고 생각합니다."},{"q":"지원자의 RTL-SDR 활동에서 동글을 개조하였다고 하는데, 이는 어떻게 개조한 건지 설명해주세요.","a":"RTL-SDR 에 들어가는 RTL2832U 칩의 데이터시트를 보면 ADC 입력이 2개가 있다. 이 중 하나만 튜너 칩에 연결되어 있기 때문에 나머지 입력단에 안테나를 연결하면 HF 대역의 전파를 수신 가능합니다."},{"q":"젠투 리눅스를 설치하였다고 하였는데, 이에 대해 설명을 좀 해보세요.","a":"젠투 리눅스는 BSD에서 영감을 받아 만들어진, 모든 프로그램을 소스 코드로부터 컴파일하여 설치하는 운영체제, 설치 시 운영체제의 모든 파일부터 설정을 다 수동으로 해야합니다. 이 작업을 직접 해봄으로써 리눅스 운영체제의 구조(커널, daemon등)를 익힐 수 있었습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"평생교육학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"대기실 입실 후 대기 → 면접 → 퇴실 / 면접시간 10분 / 면접위원 2명","notes":"오전에 보시는 분은 지하철 이동을 추천합니다. · 생기부의 자세한 내용보다 본인 지원동기 관련해서 꼬리 질문을 계속하는 느낌입니다.","qa":[{"q":"저희 평생교육학과에 지원해주셔서 감사해요. 지원자가 생각하는 평생교육이 뭐라고 생각해요? 마지막이라 기다리느라 힘들었죠 ㅎㅎ","a":"저는 교육이라는 큰 범주 안에 학교교육, 평생교육으로 나눌 수 있다고 생각합니다. 학교교육은 사회에 진출하기 전에 기본적인 지식과 역량을 갖추기 위한 여러 활동을 합니다. 평생교육은 사회에 진출한 이후에 추가적인 지식 혹은 배우지 못했던 지식을 갖출 수 있는 기회를 제공해주는 곳이라고 생각합니다."},{"q":"교육학 관련해서 많은 활동을 한 것 같은데 평생교육 관련해서 본인이 진행한 활동이 있을까요?","a":"저는 다문화 교육에 관심이 많아 2학년 때 집중 탐구해 보았습니다. 세계화가 이루어지고 있어 다문화 교육도 학교에서 많이 진행되고 있는 반면, 다문화 학생 자퇴율이 해마다 증가하고 있다는 사실을 기사를 통해 알게 되었습니다. 이에 문제 의식을 갖고 추가적인 탐구를 진행하였습니다. 아비투스 문화자본 개념을 사용해 보았습니다. 다문화 학생을 인터뷰하면서 서로 다른 공동체가 같이 지내면서 가치체계 즉, 에토스가 달라 갈등이 많이 발생한다는 것을 알게 되었습니다. 에토스가 다른 사람끼리 생활할 때 갈등을 줄일 수 있는 방법으로 교육이 진행되어야 한다고 생각했습니다. 이에 대한 해결방안으로 다문화 학생 중심, 우리나라 학생 중심, 부모님 중심 총 3가지로 다문화 교육이 진행되어야 한다고 주장해보았습니다."},{"q":"다문화 관련, 세계시민교육 활동을 많이 해 본 것 같은데, 다문화 교육과 세계시민 교육의 차이가 뭐라고 생각하세요?","a":"세계시민 교육이 다문화 교육을 포함하고 있는 개념이라고 생각합니다. 다문화 교육은 문화가 다른 사람끼리 생활하며 발생할 수 있는 갈등을 줄이기 위한 기본적인 교육입니다. 이러한 교육을 기반으로 하여 더 나아가 세계화 시대에 서로 도움을 주며 발전할 수 있는 방법을 배우는 것이 세계시민 교육이라고 생각합니다."},{"q":"생기부 대부분에 아동교육을 중심으로 준비를 한 것 같은데, 평생교육학과를 지원한 이유는 무엇인가요?","a":"저는 e러닝 컨텐츠를 개발하여 여러 가지 교육 분야에 도움을 줄 수 있는 전문가가 되고 싶습니다. 1, 2학년 때까지는 이러한 e러닝 컨텐츠를 아동교육에 적용하는 것이 효과가 높을 것이라고 생각하였는데요, 다문화, 노인, 성인 교육 등 아동교육 뿐만 아니라 e러닝 컨텐츠를 활용할 필요가 있는 분야가 많다는 것을 알게 되었습니다. 평생교육학과에 진학하면 e러닝 컨텐츠를 개발하여 좀 더 다방면의 교육 분야에 종사할 수 있을 것이라 생각하여 평생교육학과에 지원했습니다."},{"q":"e러닝 컨텐츠 중에서 어떤 기술을 주로 사용하고 싶은 것이죠?","a":"저는 메타버스와 생성형AI를 주로 활용하고 싶습니다."},{"q":"생성형 ai 종류가 어떤게 있죠?","a":"여러 가지가 있지만, chat gpt가 있습니다."},{"q":"chat gpt 말고 다른거도 있나요?","a":"어... 지금 바로 떠오르는 건 Chat gpt밖에 없는 것 같습니다."},{"q":"지금 시행되는 평생교육 관련 이슈가 무엇이고 이에 관한 해결방안이 뭐라고 생각하나요?","a":"저는 장애인 교육 관련 문제가 큰 이슈라고 생각합니다. 평균적으로 의무교육을 받은 장애인은 50퍼 센트 미만이라고 합니다. 평생교육 센터가 있지만, 센터에 들어가기 위한 진입장벽 또한 높다고 하죠. 이러한 문제는 디지털 교육으로 해결할 수 있다고 생각합니다. 현재 평생교육 사이트에 들어가보면 디지털 강의가 많이 제공되고 있지만, 이론만 습득할 수 있을 뿐이지 배운 것을 실천하기에는 한계가 있습니다. 이때 생성형ai를 활용한다면 학습자 수준에 맞게 실천적인 부분도 수월하게 진행될 수 있다고 생각합니다"},{"q":"마지막으로 하고 싶은 얘기 부탁드릴게요","a":"(준비했던 것 얘기하고 마무리)"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"화학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"대기실 입실 → 휴대폰 및 전자기기 수거 → 가번호 부여 → 면접 대기 → 면접 / 면접시간 약10:45분쯤 면접 진행 / 면접위원 2명","notes":"면접관 두분 씩 두 방에 나눠서 있었음(모두 남자였음) · 가번호가 적힌 이름표(목에 걸도록 되어있음) 받는데 앞번호들은 오른쪽방에서 순서대로, 중간번호 정도부터 왼쪽방에서 순서대로 대기실에서 부르면 짐을 아예 다 싸고 면접실 앞에 두고 들어감(내가 가번호 34번이었는데 20번대 정도부터 시작이었음) · 생기부를 전체적으로 아예 안 보고 즉석으로 보면서 질문하는 거 같았음 · 한 분은 거의 눈도 안 마주치고 질문도 별로 안 하심, 다른 분은 웃으면서 질문을 해주시긴 하는데 약간 귀찮아하는 느낌 · 오전조 오후조로 나뉘어 있는데 오전조는 3명정도 면접 안 옴 · 들어갈 때 휴대폰 및 전자기기는 스티커 붙여서 제출(걸리면 즉시 부정행위 처리) · 대기실 안은 조금 덥고 가져온 자료 맘대로 볼 수 있음(물은 개인이 챙겨와야함) · 중간 정도 번호였기 때문에 내 순서 바로 전에 5분 쉬었다가 한다고 하심","qa":[{"q":"차례가 좀 뒷차례인데 기다리는데 힘들지는 않았는지?","a":"그만큼 준비할 수 있었던 시간이 더 많았기 때문에 힘들지 않았습니다."},{"q":"화Ⅰ, 화Ⅱ 선생님이 같은 분이신지?","a":"다른 분이십니다.(이 말하기 전에 화학세특이 써있는 게 교과같지 않다며 불만족해하시는 거 같았음, 그래도 옆에 계신 교수님이 왜 학생 탓을 하냐고 해서 별로 엄청 영향 있을 거 같지는 않았음.. 하지만 화학 과목 Ⅰ,Ⅱ에서 질문을 안 하심..)"},{"q":"각각 여자 분이신지 남자 분이신지?","a":"화Ⅰ은 남자 선생님이시고 화Ⅱ는 여자 선생님이십니다."},{"q":"자기소개랑 지원동기 말해보세요.","a":"저는 화학을 너무 사랑하기 때문에 숭실대학교 화학과에 지원하게 되었습니다. 저는 이론화학연구회라는 동아리를 통해 화학에 대한 관심을 가지게 되었습니다. 많은 화학과 관련된 활동들을 하였으며 특히, 식초와 티눈약을 통해 아스피린 합성 실험을 오랫동안 진행하였던 경험이 있습니다. 그 과정에서 화학실에서 동료 친구들과 방과후나 휴일 아침부터 밤늦게까지 연구를 하는 등 수많은 실험을 하였고 또 수많은 실패를 경험하였습니다. 많이 힘들기는 했지만 친구들과 함께 원하는 결과를 얻었을 때의 그 감동은 이루어 말할 수 없을 정도로 너무 행복하였습니다. 여러 노력들이 모여 하나의 결과물을 만들어내는 화학이라는 것이 저에게는 너무나도 매력적으로 다가왔습니다. 그래서 저는 제가 사랑하는 화학을 더욱 깊게 공부하고 연구들을 진행해나가갈 수 있다고 생각되는 숭실대학교 화학과에 지원하게 되었습니다."},{"q":"[2학년 동아리] 시계반응 실험이 어려운 건데 진짜로 한 것이 맞나요(이때부터 계속 진짜 했는지 의심하면서 물어봄)","a":"네. 실제로 화학동아리 활동의 일환으로 화학실에서 직접 반응을 확인하는 실험을 진행하였습니다."},{"q":"[2학년 동아리] 시계반응이 뭔지 말해보세요.","a":"시계반응은 일정 시간이 지난 후 변색, 침전 등의 변화가 나타나는 반응인 것으로 알고 있습니다."},{"q":"[2학년 동아리] 시계반응 실험을 했던 과정이 어땠는지 말해보세요.","a":"저희는 녹말과 아이오딘용액을 사용하여 해당 실험을 진행하였습니다. 농도를 다르게 하여 우선적으로 제작한 녹말용액을 농도가 낮은 것부터 하여 순서대로 두었고 이것에 아이오딘용액을 동시에 넣었을 때 순차적으로 색이 변하는 모습을 관찰하였습니다."},{"q":"[2학년 동아리] 반응이 잘 나타났나요?","a":"네. 농도에 따라서 색의 진하기 차이가 확연하게 나타나는 것을 볼 수 있었습니다."},{"q":"[2학년 동아리] 시계반응이 나타났을 때 어떤 색이었나요?","a":"점점 더 진한 갈색?고동색?으로 나타났습니다."},{"q":"[2학년 동아리] 시간이 지나면 변했던 색이 다시 원래대로 돌아오는데 왜 그런 반응이 나타나는 거 같나요?","a":"음.. 가..역반응..?이기 때문인 것 같습니다."},{"q":"[2학년 창체] 합성의약품과 바이오의약품의 차이가 뭔지 말해보세요.","a":"화학의약품이란 합성의약품이라고 할 수 있고 역사가 가장 오래된 의약품입니다. 천연물에서 추출한 원료부터 시작하여 아스피린과 같이 서로다른 주성분을 합성하여 만든 의약품까지 매우 다양합니다. 반면에 바이오 의약품은 실제 세포를 이용한 면역 세포 치료제나 백신과 같은 종류가 바이오 의약품입니다."},{"q":"[1학년 통합과학] 나만의 주기율표 만들기에서 어떤 분류 기준으로 나눴는지 내용 말해보세요.","a":"저는 나만의 주기율표 만들기에서 제약회사별 통증에 따른 의약품을 조사하여 정리하였습니다. 주기에는 제약회사를, 족으로는 통증별 분류를 배치하였고 통증으로는 생리통/복통, 두통/해열, 근육통/관절통을 선정하였습니다. 이 활동을 하는 과정에서 제가 관심 있는 분야인 제약과 관련된 주제를 직접 선정하여 진행하다 보니 주기율표 각각에 들어가는 약들의 성상, 제형, 성분 등에 대해 자세히 알아갈 수 있었습니다."},{"q":"[1학년 통합과학] 주기율표에 대해 설명해보세요.","a":"주기율표는.. 원소들을 구분하기 위해 정리를 해 둔 표의 일종입니다."},{"q":"[1학년 통합과학] 주기율표의 족과 주기가 어떤 기준으로 나뉠 수 있죠?","a":"양성자 수에 따라 배열이 순서대로 되어 있는 것으로 알고 있습니다."},{"q":"오비탈이나 뭐 그런 거 관련해서도 알고 있죠?","a":"네. 전자가 채워지는 오비탈의 수가 달라지는 것으로 알고 있습니다."},{"q":"[2학년 진로] 미나마타병에 대해 설명해보세요","a":"네. 미나마타병은 한 기업의 공장에서 생산한 아세트알데이드를 대량생산하고 무단 방류하게 되며 시작된 화학물질로 인한 질병입니다. 그래서 인체에 중급속인 메틸수은이 쌓이게 되며 중추신경계에 문제를 발생시키게 되는 병입니다. 이를 치료할 수 있는 방안 중 하나로 알려진 것이 페니실 아민을 통한 체외 배출입니다."},{"q":"[2학년 진로] 페니실아민이 뭔지 설명해보세요.","a":"페니실아민은 페니실린을 가수분해하여 얻은 아미노산입니다. 대표적인 킬레이트제이기 때문에 중금속과의 결합능력을 가지고 있어 메틸수은의 체외 배출에 있어 도움이 됩니다."},{"q":"[2학년 진로] 킬레이트제가 뭔지 설명해보세요.","a":"킬레이트제는 전자쌍을 내주어 양이온과 결합할 수 있는 작용기가 있는 시약이라고 알고 있습니다."},{"q":"시간이 거의 다 됐는데, 마지막으로 하고 싶은 말 20초 정도 해보세요.","a":"우선적으로 면접 기회를 주신 것에 감사하다고 말씀드리고 싶습니다. 저는 고등학교에서 화학 동아리 활동을 하며 수준높은 화학실험들을 많이 진행하며 경험을 쌓아왔기 때문에 숭실대학교 화학과에 적합한 인재라고 생각합니다. 감사합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"숭실대학교","dept":"법학과","jeonhyeong":"학생부종합(SSU미래인재전형)","method":"지원동기 → 본교 관련 지식질문 → 생기부 확인용 질문 → 마지막 하고 싶은 말-한 사람당 10~15분 정도 봄.","notes":"-차량 진입이 어려움.-부모님 대기실이 따로 준비되어 있음.","qa":[{"q":"페르마의 정리가 무엇인가요?","a":"페르마의 정리에 대해 간단하게 아는 지식과 실생활에 활용된 예시"},{"q":"난민 수용에 대해서 찬성하나요?","a":"찬성한다. 국제 사회의 측면에서 서로 도와야 하는 것이 이치이기 때문. 우리나라 국민도 언제 난민이 될지 모르기에 도와야 한다."},{"q":"통일과 같이 난민이 한꺼번에 많이 들어오게 된다면 어떡할 것인가?","a":"일정 기준을 정한 뒤 그 기준에 맞추어 순차적으로 수용하면 사회적 혼란은 발생하지 않을 것."},{"q":"뭐가 되고 싶은 것인가?","a":"사회적 약자를 대변하는 변호사가 되고 싶음."},{"q":"‘독고솜에게 반하면’이라는 책의 내용 설명","a":"책 내용 설명 후 깨달은 점 이야기함."},{"q":"숭실대학교 법학과여야만 하는 이유는?","a":"로우링 프로그램과 캡스톤 디자인 활동을 통해 법적 지식을 쌓는 것만이 아닌 법을 바라보는 시각을 넓히고 법정에서 적용할 수 있는 방법을 배우기 위하여"},{"q":"생태복원사업이 무엇인가?","a":"생태복원사업의 사례 제시"},{"q":"일회용품을 줄일 수 있는 방안이 뭐가 있는가?","a":"여행 시 사용되는 일회용품을 줄여야 한다. 특히 페트병 대신 텀블러를 쓰는 것을 권장. 여러 텀블러를 소지하고 있는 것보다 인당 하나씩만 소지하는 것이 옳음."},{"q":"일회용품 줄이기 방안을 카드 뉴스로 제작했다고 했는데 카드 뉴스를 한 개만 만든 건가?","a":"카드 뉴스는 하나만 제작했지만, 그 안에 다양한 방안을 제시했음."},{"q":"마지막으로 하고 싶은 말","a":"리더 활동으로 쌓은 의사소통 능력과 숭실대학교 법학과에서 배운 지식을 활용하여 의뢰인의 상황을 파악하고 법정에서 유리할 수 있는 변호를 하는 변호사가 되고 싶다.후배들을 위한 조언 -생기부 내용을 내가 다 안다 싶으면 진짜 문제없이 할 수 있는 게 숭실대학교 면접이라고 생각해요! 특히 숭실대 법학과 지원하는 친구들이라면 법학 내용 말고 잠시 스쳐 간 활동도 꼭 확인해보세요. 물론 모든 내용을 다 알기는 힘들겠지만 생기부 몇 번 읽다 보면 그때 했던 활동도 어렴풋이 기억나고 저절로 외워지더라고요.-그리고 숭실대는 학교에 대한 관심을 중요하게 여겨요. 그러니 학교 홈페이지와 다양한 사이트를 통해서 숭실대학교만의 활동과 특징을 잘 알고 가는게 좋을 것 같아요! 조금만 더 힘내서 파이팅 해봐요:)"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"평생교육학과","jeonhyeong":"학생부종합(기회균형전형오전 7시 50분부터 8시 30분까지 대기실 입실)","method":"→ 가번호, 면접 유의 사항 안내 후 면접 진행→ 복도 가서 대기 (ex. 3번 면접 시, 4번 복도 대기)→ 모든 짐을 복도에 다 두고 면접 진행→ 면접 끝난 후, 짐을 갖고 퇴실 (대기실 재입실×)-지원동기와 마지막으로 하고 싶은 말 질문 ×-생활기록부에서 교과 세부 능력 및 특기사항 부분보다 창의적 체험활","notes":"동 상황과 행동 특성 및 종합의견 부분 질문-무서운 분위기의 면접이 아닌 편안하고 대화하는 듯한 분위기의 면접으로 면접관님들이 농담을 많이 함.-다른 대학교보다 면접 질문을 많이 함.","qa":[{"q":"언제 왔나요?","a":"오전 7시에 미리 도착해 캠퍼스를 둘러보며, 마음을 다잡았습니다."},{"q":"숭실대학교 캠퍼스를 직접 보니 어때요?","a":"교통편도 좋고, 특히 눈이 와서 그런지 학교 캠퍼스가 더욱 아름다워 보였습니다."},{"q":"생활기록부를 보니 1, 2학년 때 학과에 대한 정확한 진로가 명확하게 적혀 있진 않네요. 선생님들이 빠뜨리셨나 보네요. (혼자 조용히 궁금해하듯 말씀하심)","a":"혹시 그 부분에 대해 설명드려도 될까요? (면접관 모두 허락함) 과거 저는 교육에 있어 진로는 교사밖에 없다는 고정관념을 가지고 있었습니다. 하지만 1, 2학년 때 교육 동아리에서 활동을 진행하며 교육에도 기업교육, 노인 교육, 문화 교육 등 다양한 분야가 존재함을 깨달았습니다. 또한 제가 스스로 배운 교육학 이론을 활용해 학생자치회 활동을 진행함에 따라, 저의 교육적 역량이 학생자치회 조직 업무에 긍정적 효과를 줄 수 있음을 느꼈습니다. 이에 2학년 2학기 후반에 조직과 개인의 미래에 기여하는 평생교육사인 HRD 전문가로 성장하고 싶다는 확고한 목표가 생겼습니다. 이러한 고민의 과정이 있었기에 3학년보다 1, 2학년 때 생활기록부에 정확한 진로가 드러나지 않았습니다."},{"q":"1, 2학년 때 T-world 동아리를 했네요. SKTworld 뭐 이런 건가요?","a":"대부분 T-world 동아리명을 듣고 그 기업을 떠올리시기도 합니다. 하지만 T-world 동아리는 교육 동아리로 교사와 같은 교육 계열 진로를 원하는 학생들이 함께 다양한 교육적 활동을 기획하고 진행하는 동아리입니다. 저는 T-world 동아리에서 활동하며 교육적 역량을 키울 뿐만 아니라 저의 확고한 진로를 찾고 성장해 나갔습니다."},{"q":"학교에서 이벤트 매니저 활동을 했네요. 이건 원래 있는 활동인가요?","a":"이벤트 매니저는 학급 친구들의 생일을 축하해주고 학급 단합을 위해 직접 기획하여 진행한 활동입니다. 생일파티 등의 이벤트를 진행해 학급의 분위기를 더욱 밝고 돈독하게 하고 싶다는 생각이 들어 선생님께 직접 말씀드렸으며, 같은 이벤트 매니저인 친구들과 상의하며 매달 이벤트를 준비해 운영했습니다."},{"q":"그럼, 방학 중에 생일인 친구는 어떤 방식으로 챙겼나요? 그리고 본인의 생일 때는 어떻게 진행했나요?","a":"만약 방학 중에 생일이 있는 친구를 챙기기 위해, 그 전 달에 진행되는 생일파티에 함께 축하해주었습니다. 예를 들어, 7월이 방학이면 7월 생일인 친구들을 축하해주기 어려우니 6월 생일파티와 함께 진행했습니다. 그리고 제가 생일인 달에는 다른 이벤트 매니저 친구들이 챙겨주었습니다. 이처럼 이벤트 매니저로 활동하면서 서로의 생일을 축하해주고 친밀도 높은 학급 분위기를 형성해 나갔습니다."},{"q":"2, 3학년 때 학생자치회 활동을 했다고 적혀 있네요. 학생자치회 시스템 변화에 노력했다고 하는데, 구체적으로 어떻게 진행했나요?","a":"1학년 때는 1학년장을, 2학년 때는 전교 부회장, 그리고 3학년은 전교 회장을 맡으며 학생자치회 임원으로서 활동했습니다. 활동을 하며 학생자치회 내부 시스템의 문제점을 발견할 수 있었고 이를 해결하고 싶다는 생각을 했습니다. 대표적인 문제로는 학생자치회 부서의 특색이 담긴 업무가 부족하다는 점이었고, 부서 간의 업무가 유사하다는 점이었습니다. 이러한 문제를 해결하기 위해 전교 회장으로 활동하며 부서를 통합하고 역할을 확립해서 체계적인 학생회를 운영하고자 노력했습니다."},{"q":"그 시스템 변화를 위한 해결 과정에서 혼자 하기는 힘들었을 텐데, 어떤 어려움이 있었나요?","a":"학생자치회 활동을 하면서 많은 어려움을 겪었습니다. 학생자치회 시스템 변화 중에서도 부서를 통합하는 것에 대한 학생들의 불만이 많았습니다. 저는 이를 해결하기 위해 먼저, 학생자치회 임원 내 단합을 중시하여 그들에게 부서를 통합하는 이유를 설명했습니다. 이후 학생자치회 임원들의 생각을 듣고 부서 통합에 대한 계획을 마련해 갔습니다. 이후 전교 학생들을 대상으로 부서 통합의 필요성과 계획을 이야기하며 그들을 설득했습니다. 그 결과, 부서 통합에 대한 학생들의 인식이 긍정적으로 변화했고 이에 대한 학생자치회 시스템 체계에 변화를 주었습니다."},{"q":"디지털 관련 교육에 관해서도 탐구를 많이 했네요. 요즘 대전환 시대에 필요한 교육은 뭐라고 생각하나요?","a":"디지털 대전환 시대에는 에듀테크 기반의 교육이 필요하다고 생각합니다. 인공지능 기술을 활용한 교육은 학습자 개별 맞춤형 교육을 실현할 수 있도록 도와줍니다. 학습자를 분석하고 그에 맞는 교육을 제공해 주기에 학습자의 역량 개발에 있어 긍정적 도움을 줍니다. 그렇기에 대전환 시대에는 인공지능을 기반으로 한 맞춤형 교육이 필요합니다."},{"q":"생활기록부를 보니 지원자가 맞춤형 교육에 대해서도 많이 탐구했네요. 혹시 2025학년도부터 디지털 교과서가 도입된다는 사실을 알고 있나요? 지원자는 디지털 교과서 도입이 맞춤형 교육에 있어 도움이 된다고 생각하나요?","a":"네. 저는 디지털 교과서 도입 맞춤형 교육에 있어 도움이 된다고 생각합니다. 하지만 디지털 교과서 도입에 대해 반대하며 서책형 교과서를 더욱 원하는 입장도 있습니다. 이에 대해 저는 어떤 교과서가 학습자에게 더욱 긍정적인 영향을 줄 수 있을지 의문이 생겨 생명과학 교과 시간에 탐구를 진행해 보았습니다. 그 결과, 디지털 교과서 활용에 있어 다양한 자극을 주어 학습자의 집중도를 높여야 한다는 사실을 알 수 있었습니다. 이처럼 저는 디지털 교과서에 대해 맞춤형 교육을 실현할 수 있는 하나의 방안이며, 학습자의 집중도와 흥미 향상을 위한 다양한 자극의 요소가 더욱 추가되어 더욱 발전해야 한다고 생각합니다."},{"q":"그럼 디지털 기술을 기반으로 한 맞춤형 교육에서 교사의 역할은 무엇이라고 생각하나요?","a":"맞춤형 교육에서 교사의 역할은 학습자가 디지털 기술을 올바르게 사용할 수 있는 도와주는 것입니다. 또한 인공지능이 교육에 도입됨에 따라, 교사의 기존 행정 업무와 학생 관리 업무에서 인공지능이 단순 반복적인 행정 업무를 처리하고 교사는 학생의 정서 관리와 사회성 함양을 중시하는 역할 변화가 생깁니다. 그렇기에 교사는 디지털 기술을 기반으로 한 맞춤형 교육에서 학습자의 인성 교육과 가치관 형성을 위해 노력해야 합니다."},{"q":"지원자의 답변을 듣고 아침에 본 인공지능이 독도를 분쟁지역으로 인식한 기사 내용이 생각이 납니다. 또한 이건 주변 지인의 사례인데, 초등학생을 대상으로 인공지능이 어려운 단어를 사용해 질문에 대한 결론을 알려줘서 아이들이 인공지능 사용을 어려워하기도 했습니다. 이러한 사례 등을 통해 지원자는 인공지능 활용에 대해 어떻게 생각하나요?","a":"면접관님의 이야기를 들으며, 인공지능이 제공하는 모든 정보가 옳지 않을 수 있다고 생각했습니다. 인공지능은 학습자에게 맞춤형 교육을 제공하지만, 기존의 데이터를 기반으로 결론을 도출해 잘못된 정보를 제공하기도 합니다. 그렇기에 편향적일 수 있고 잘못된 정보를 알려줄 수 있습니다. 이러한 점은 인공지능을 활용한 교육 현장에서 심각한 문제가 됩니다. 이에 저는 교육 현장 속 인공지능 활용에 있어 교육자는 학습자가 인공지능 활용에 대한 올바른 가치관을 형성할 수 있도록 해야 하며, 비판적 사고력 증진을 위해 독서 교육을 진행해야 한다고 생각합니다."},{"q":"마지막으로 숭실대학교 홈페이지를 살펴봤을 텐데, 왜 숭실대학교가 자신과 적합하고, 자신을 뽑아야 한다고 생각하나요?","a":"저는 처음 숭실대학교 홈페이지를 보며 저와 같은 인재를 뽑아야 한다고 생각했습니다. 그중에서도 숭실대학교 평생교육학과 교육과정에 있는 인적자원개발론 교과목을 통해 저의 HRD 전문가로서의 꿈을 펼칠 수 있다는 생각이 들었습니다. 또한 인적 자원 개발에 있어 저는 관심과 열정을 갖고 있는 학생이기에 평생교육학과에 적합한 인재라 판단했습니다. 이에 저는 숭실대학교 평생교육학과에 진학해 평생교육사인 HRD 전문가로서 대한민국을 빛내는 인재가 되고 싶습니다. 후배들을 위한 조언 · ‘동기 → 과정 → 결과’ 부분으로 생활기록부 활동 정리하고 계속 보기· 대학교 선행 학습 영향평가 보고서, 면접 후기 등을 통해 학교 면접 특징 분석하기· 대학교 학과 홈페이지에 방문해 학교와 학과에 대한 이해도 높이기· 선생님들과 모의 면접 많이 해보고 예상 질문 만들기생활기록부만 계속 읽는 것이 아닌, 모의 면접을 통해 말해보는 연습을 하면서 다양한 피드백을 받고 자신의 면접 태도를 수정해 나가는 과정 필요학교 선생님들과 친구들에게 부탁해 다양한 모의 면접 진행하기모의 면접을 하면서 울기도 하지만, 이를 통해 점차 발전하는 자신을 마주할 수 있음예상 질문에 대한 답변은 키워드로 간단히 정리하기, 오랜 시간 질문 만들기는 추천 ×· 교육계열 학생은 교육학 교과서를 전체적으로 읽어보는 것을 추천· 면접 전, 대기실에 일찍 들어가서 면접 자료를 읽으며 면접 준비하기디지털 기기는 모두 제출하므로, 종이 자료로 인쇄해서 챙겨가기많은 자료를 챙겨가는 것보다는 필요한 자료만 챙겨가서 생각 정리하는 것이 더 좋음생각이 복잡할수록 긴장할 수 있으니, 대기실에서 간단한 자료를 읽으며 이 학과에서 내가 어떤 사람이 되고 싶은지 생각하기· 대기실이 춥고 건조할 수 있으니 따뜻한 물과 핫팩 챙겨가기· 자신감 중요★ 들어가는 모습부터 나오는 뒷모습까지 자신감 있는 모습 유지하기소심하고 불안한 태도 ×, 자신의 답변에 대한 자신감이 필요함 · 면접관의 말에 경청하고 차분하게 논리적으로 말하기자연스러운 웃음, 밝은 모습 필요질문이 이해되지 않으면 주저하지 말고 다시 물어보기답변을 생각할 시간이 필요하다면 면접관님께 말씀드리고, 정리한 후 논리적으로 답변하는 것이 좋음"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"건축학부(건축학·건축공학전공)","jeonhyeong":"학생부종합(SSU미래인재전형)","method":"학과 선택 질문 → 지원동기 → 진로 활동 내용/개념 질문 → 자율 활동 내용 질문 → 건축방법 질문 → 꼬리질문으로 개념 질문 → (진로 바꾼 이유) → 건축학과와 건축공학과 차이 → 힘들었던 경험과 해결 방법 → 마지막으로 하고 싶은 말-질문을 길게 하시니까 당황하지 말고 귀 기울여 듣고 답변하면서도","notes":"어떤 질문을 하셨는지 잘 기억하는 것이 중요합니다.-꼬리 질문을 하실 수 있으니 평소에 관련 뉴스나 논문을 틈틈이 살펴보고, 여기서 얻은 지식을 준비한 내용과 접목시키는 것이 좋습니다.","qa":[{"q":"숭실대학교는 건축학부이고, 1학년을 마치고 건축학과와 건축공학과 중 하나를 선택해야 하는데 어느 곳을 희망하나요?","a":"건축학과를 희망합니다."},{"q":"지원동기 말씀해주세요.","a":"사람들의 삶을 안전하고 편안하게 하는게 목표이고 환경 문제가 심각해지는 현 상황에서는 친환경 건축이 그 방법이라 생각해 친환경 건축을 목표로 하고있다고 밝힘. 숭실대학교의 친환경에 관한 커리큘럼을 언급하며 진학 포부를 확실히 밝힘."},{"q":"스마트 시티를 주제로 진로 활동을 진행했는데 여기서 본인이 주목한 cpted의 개념과 본인이 했던 활동 설명해보세요.","a":"셉테드는 환경 설계를 통한 범죄 예방 사업을 말합니다. cctv, 가로등 설치, 벽화그리기 등 활동으로 지역의 환경을 바꾸어 범죄율을 낮추는 것을 목적으로 합니다. (+국내와 해외의 cpted 사업에 대한 간단한 설명) 노후화된 주변 지역의 환경을 바꾸는 것을 목표로 cctv와 가로등 설치에 주목하여 활동하였습니다. (+관련 논문 활용한 cctv최적 위치 설정 알고리즘의 원리에 대한 설명)"},{"q":"하우스 보트를 주제로 자율 활동을 진행했는데 활동 설명해보세요.","a":"뉴스에서 독일의 땅값 상승으로 인한 하우스 보트의 증가를 보고 하우스 보트가 홈리스 문제를 해결하는 좋은 거주 형태가 될 수 있으리라 생각하여 하우스 보트를 개선하는 사업을 진행하였습니다. 하우스보트 거주자들이 주변 시설을 더럽힌 후 보트의 위치를 옮기는 일이 많아 환경오염 문제가 생기고 있다는 것을 알게 되었고 올바른 형태의 하우스 보트를 만들어야겠다고 느껴 네덜란드와 같은 하우스보트의 임대주택시스템 정책을 도입하고, 폐보트 개조 사업으로 일자리를 창출하는 아이디어를 냈습니다. 또 학술제 활동에서 배운 깨진 유리창 이론을 활용해 관리된 보트의 거주자들은 환경을 덜 파괴할 것이라 생각하였습니다."},{"q":"미래를 위한/친환경적인 건축방법은 무엇이 있죠?","a":"제가 생각하는 친환경적 건축은 패시브 하우스가 있습니다. 패시브 하우스란 내부 열이 밖으로 새어 나가는 것을 막음으로써 에너지 사용량을 절감하는 집을 말합니다. 패시브 하우스의 핵심은 열회수형 환기장치입니다. (+열교환소자의 원리에 대한 설명)"},{"q":"열회수형 환기장치 말고 다른 특징은 없나요? (예상하지 못한 질문이지만 나무가 단열성이 높다는 점을 알고 있고 뉴스에서 나무 패시브 하우스를 본 적이 있어 대답)","a":"목재는 타 재료들보다 단열성이 높으므로 목재 건축은 열을 보존해야 하는 패시브 하우스의 특징이라 할 수 있습니다."},{"q":"진로를 바꾼 것 같은데 이유가 무엇인가요? 계기가 된 활동이 있었나요?","a":"(의료→건축) 1학년 때 했던 독서프로젝트 활동 토론에서 동물보호소 설계 사업 진행하며 건축에 대한 흥미가 생겼습니다. (+ 동물보호소 사례. 설계 사업에서 냈던 설계 방안 구체적으로 언급)"},{"q":"건축학과와 건축공학과의 차이를 알고있나요?","a":"건축학과는 건축설계를 위주로 배우고 건축공학과는 구조역학, 시공 등을 위주로 배운다고 알고 있습니다."},{"q":"살면서, 혹은 학교생활 하면서 어려웠던 경험이 있었나요? 그렇다면 해결 방법은?","a":"학교생활 중 갈등의 경험이 2번 있었습니다. 1학년 수업량 유연화 활동에서 조원들의 갈등이 발생해 고민하고 당황했었습니다. 이때 퍼실리테이션 기법에 대해 알게 되었습니다. (퍼실리테이션 개념 설명) 3학년 학술제 활동에서 비슷한 갈등이 발생했을 때 이전의 경험을 바탕으로 퍼실리테이션 기법을 사용하며 의견을 조정해 조장으로서의 역할을 다할 수 있었습니다. (+어떤 상황이었고 퍼실리테이션이 어떻게 활용되었는지 설명)"},{"q":"마지막으로 말 못했던 강점이나 진학 포부 말해주세요.","a":"(수학 멘토링 경험, 수학 성적을 언급) 수학적 강점을 가졌습니다. (+건축에서 곡면의 미분이 많이 활용된다는 점 설명) 숭실대학교를 빛낼 혁신적인 인재가 되겠습니다.후배들을 위한 조언 -동기를 말할 때 건축학과에 진학하고 싶은 이유를 말하는 것도 중요하지만 왜 이 학교인지 명확히 나타내야 합니다. 학교 홈페이지에 자주 들어가서 커리큘럼이나 인재상 보기!-준비하지 않은 질문 나와도 어떻게든 말하려고 노력해 보세요.-모의면접 자주 하면서 자신의 문제점 파악하기. -마지막으로 하고싶은 말 물어보시면 진짜 하고싶은 말 다 뽐내고 오기."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"건축학부(실내건축전공)","jeonhyeong":"학생부종합(SSU미래인재전형)","method":"지원동기->진로활동 질문->생기부 기반 전공 질문-> 인성 역량 질문->마지막 할말","notes":"숭실대는 인성영역을 많이 보는 것 같습니다.","qa":[{"q":"진로활동에서 세대별 추구하는 주거 공간에 대한 탐구를 진행하셨는데 각 각x, y, z세대가 추구하는 주거 공간은 무엇인가요?","a":"먼저 X세대는 다 같이 모여서 사는 그러한 주거 공간을 추구한다고 생각합니다. 하지만 y, Z세대는 시대가 변하면서 개인주의적 사상이(여기서 좀 절음) 장악하고 있기 때문에 혼자서, 이웃과 단절된 주거 양식을 추구한다고 생각합니다."},{"q":"위 탐구를 진행하면서 논문을 탐독했다고 하셨는데 그 논문은 무슨 내용인가요?","a":"이 탐구를 진행하는 데 있어 탐독한 논문의 내용은 먼저 x, y, Z세대의 특징을 잘 설명해 주고, 그에 따른 세대별 주거방식에 대한 고찰을 보여주는 형식을 띠었습니다."},{"q":"본인이 들은 수업 중 실내건축학과에서 가장 어울리는 과목은 무엇인가요?","a":"제가 들은 수업 중 가장 연관이 있는 수업은 건축 일반이라는 수업인 것 같습니다."},{"q":"건축 일반 수업에서 배운 수업의 내용은 어떤 것이 있나요?","a":"건축 일반 수업에서는 다양한 건축가들의 건축적 특징이나 건축 철학 등을 배웠습니다. 이후에는 그 건축가들의 건축물을 직접 설계하고 우드락으로 표현하는 활동을 했습니다."},{"q":"들어보니까 실내 건축보다는 건축학과와 더 어울리는 것 같은데 이 둘의 차이를 보여주기 위해 이 수업에서 어떤 활동을 했나요?","a":"보통 우드락으로 모형 건축물을 만들 때 는 건축물의 외형에만 집중하는 경향이 있지만 저는 보통 건축학과와 차이점을 두기 위해서 건물 내부의 계단을 표현한다든가 아니면 내부 공간을 종이 위에다 꾸민 후 우드락 위에다가 붙이는 등 실내건축적인 활동을 하였습니다."},{"q":"2년 내내 수학동아리에 있다가 3학년에 건축동아리로 바꾸었는데 이 과정에서 힘든 점은 없었나요?","a":"평소에도 수학이라는 학문을 좋아해서 동아리를 바꾸는 데 힘든 점은 없었습니다. 하지만 힘든 점보다는 제가 또 다른 관심 분야로 동아리를 바꾼다는 것에 설렘을 느꼈습니다."},{"q":"우리도시 공공건축 프로젝트 활동은 어떤 활동인가요?","a":"공공건축 프로젝트 활동에서는 재건축된 지역의 건축물들이 어떤 이유로 바뀌었는지, 또 어떤 차이를 뒀는지 등에 관한 내용과 한 도시를 재건축 하기 위해서는 어떠한 과정이 필요한지에 대한 강의를 들었습니다."},{"q":"이 융합수업에서 제출한 프로젝트에 대해서 설명해주세요.","a":"저는 이 프로젝트를 진행하기 위해 청주시의 내덕1동이라는 뉴딜사업을 진행한 도시를 중점적으로 탐구를 하였습니다. 내덕1동은 뉴딜사업 전에 엄청나게 노후화된 모습을 띄었는데요, 저는 뉴딜사업을 통해 바뀐 청주시 내덕1동의 모습과 주민들의 바뀐 생활양식을 보여주는 탐구보고서를 썼습니다."},{"q":"정보과제연구 과목에서 만든 가구 배치 프로그램에 대해서 설명해 주세요","a":"정보과제연구라는 수업에서 저는 직접 공간을 설계할 수 있는 프로그램을 파이썬을 통해 만들었습니다. 이 프로그램은 자신이 직접 공간의 크기를 설정할 수 있고, 또한 가구의 수와 종류를 정한 후, 가구의 위치를 조정할 수 있게 만들었습니다. 이 프로그램을 만듦으로서 저는 실내 건축학과에 필요한 역량을 기를 수 있을 것 같다고 생각하여 이 프로그램을 만들게 되었습니다."},{"q":"마지막으로 한 마디 해보세요.","a":"저는 고등학교 생활을 하면서 비록 짧은 시간이지만 건축에 대한 기초를 다지며 뿌리를 내렸다고 생각합니다. 저는 숭실대학교가 일제강점기 시절부터 한 자리에서 깊은 뿌리를 내리고 큰 싹을 틔웠다고 생각합니다. 저도 저의 싹을 틔우기 위해서는 숭실대학교뿐만이 저를 길러줄 수 있다고 생각합니다. 지금까지 저의 답변을 들어주셔서 감사합니다. 후배들을 위한 조언 일단 큰 틀에서 질문 나온 것은 이 정도이지만 기억 안 하는 것이 2개 정도 더 있습니다. 거의 다 꼬리 질문이 있다고 보면 됩니다. 면접번호가 앞번호였지만 면접 시간이 15분이기 때문에 약 한 시간 반 정도 걸렸어요. 들어가자마자 앉고 바로 “저희 학과에 지원한 이유가 뭐예요?”라고 허례허식 없이 물어보시니까 지원 동기는 입에 붙도록 외우는 것이 좋습니다. 분위기가 약간 딱딱한 느낌이었어요.숭실대는 인성 역량을 정말 많이 보는 것 같습니다. 그러니 학교에서 탐구활동이나 프로젝트를 진행할 때 리더의 역할을 많이 하면 할수록 좋을 것 같아요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"기계공학부","jeonhyeong":"학생부종합(SSU미래인재)","method":"입실시간 30분전부터 대기실 입장가능. 대기실에서 대기하며 가져온 자료확인가능. 자기차례에 입실 후 바로 질의응답시작. 10~15분동안 면접관 2명이 돌아가며 질문하는 형태.","notes":"교복 착용 및 자기 신분을 밝히는 발언 금지(이름, 지역, 부모님성명 등), 전자기기 사용x","qa":[{"q":": 간단히 자기소개 및 지원동기 얘기해주세요.","a":": 안녕하십니까 숭실대학교 기계공학부에 지원한 가번호00입니다. 저는 여러 분야에 두루 관심을 가지고 공부하고 탐구하는 특성이 있습니다. 여러 학문과 융합하여 새로운 가치를 창출해내는 기계공학에 관심을 가지게 되었고 1학년 때 타 대학교 지능로봇학과에 가서 자율주행자동차를 체험해보고 3학년 때 전기자동차를 조립 및 제작활동을 하며 진로를 확고히 하였습니다. 이를 바탕으로 인간과 환경을 연결하는 기술을 개발해 사회에 긍정적인 영향을 끼치고 싶다는 목표가 생겨 이 과에 지원하게 되었습니다."},{"q":": 네 알겠습니다. 환경에 관심이 많은 것 같은데 미세플라스틱에 대해 설명해주세요.(진로활동에 적혀있긴 했지만 면접준비할 때 찾아보진 않은내용)","a":": 미세플라스틱은 플라스틱에서 나오는 물질로 환경을 오염시키는 물질로 알고있습니다."},{"q":": 그럼 미세플라스틱으로 해양이 오염되는 과정을 설명해줄 수 있어요?","a":": 미세플라스틱이 바다에 쌓여 생물들의 생장을 방해하고 해양동물들이 먹게되어 몸에 쌓여 죽게되고 광합성하는 생물의 빛 흡수를 막는 것으로 알고있습니다."},{"q":": 미세플라스틱을 없애는 방안이 있을까요?","a":": 플라스틱을 완전히 연소하기는 어렵고 플라스틱을 대체할 친환경 소재를 만들어야 할 것 같습니다."},{"q":": 좀 구체적으로 얘기해줄 수 있을까요?","a":": (몇초동안 고민후) 잘 모르겠습니다."},{"q":": 아무래도 전공분야가 아니다 보니까 잘 모를 수 있어요. (웃으시며)","a":": 네 그렇습니다."},{"q":": 여기 동아리활동을 보면 오토파일럿 활동을 했다고 하는데 설명해줄 수 있을까요?","a":": 오토파일럿의 기능을 설명하고 풍향 장치를 통해 기능을 구현했던 활동에 대해 설명함."},{"q":": 학교에 풍향장치가 있어요?","a":": 네. 학교에 있습니다. 과학고에 가서 사용방법들을 배워보고 학교에 있는 장치로 구현해보았습니다."},{"q":": 일반고 학생이에요? (머뭇거리며 물어보심. 물어봐도 되는건지 잠깐 고민하신 듯)","a":": 네 일반고 학생입니다."},{"q":": 좋은 과학선생님을 두었네. (두분이 웃으며)","a":": 네. 저희 학교에 첨단과학실이 있는데 선생님께서 저희가 다양한 탐구활동과 실험활동을 하시도록 많은 투자를 하셨습니다."},{"q":": 성적을 보니까 물리나 수학보다 인문학 성적이 높은 것 같은데 구지 기계공학에 지원한 이유가 무엇일까요?","a":": 저는 인문학적 소양이 뛰어나다고 생각하지 않습니다. 저는 부품의 작동원리에 어렸을 때부터 관심이 많았습니다. 특히 저는 자동차에 관심이 많았는데요, 고등학교에 진학하여 단순히 모델이나 외형으로 자동차를 좋아하는 것 보다 교과목을 배우면서 자동차에 적용시켜보고 싶어 이과로 지원하게 되었습니다. (예상치 못한 인문학성적을 언급하며 물어봐서 좀 당황해 말을 늘어놓음)."},{"q":": 다른 학교도 지원했을 것 같은데 꼭 숭실대학교여야 하는 이유가 있을까요?","a":": 네. 저의 부족한 물리, 수학 역량을 채우고 훌룡한 기계공학자가 되기 위한 커리큘럼이 잘 짜여있다고 생각하고 다양한 연수 프로그램이나, 실험 프로그램을 실행하는 것 으로 알고있습니다. 또 4학년 교과목 자동차공학을 듣고싶었기 때문에 이 학교를 지원하게 되었습니다."},{"q":": 자동차 공학은 다른학교도 다 개설되어 있는데 좀 더 구체적으로 가능할까요?","a":": 숭실대가 공과대학으로도 유명하고 저의 목표나 이런것들을 이룰 수 있는 역량을 기르기에 적합한 대학교라고 생각했고 학교의 이념이 진리와 봉사라고 알고있는데 봉사역량이 뛰어나고(수학여행에서 봉사한 사례를 들며) 그러한 이념에 적합한 것 같아 지원하게 되었습니다. (이런 질문 나왔을 때 대답잘하면 좋겠다고 생각)"},{"q":": 수능 때 과학탐구 과목 뭐 선택했어요?","a":": 물리1, 지구1 선택했습니다."},{"q":": 물리에 자신감이 있었나 보네.","a":": 저는 수능물리와 교과서에서의 물리는 다르다고 생각합니다. 단순히 공식과 수식대입으로 푸는 수능물리와 달리 탐구를 중시하는 교과서 내용을 저는 더 중요시 여깁니다."},{"q":": 수학은 뭐 선택했어요.","a":": 수능수학 말씀하시는 걸까요?"},{"q":": 그럼 내신에서는 뭐했어요.","a":": 확률과 통계와 미적분 선택했습니다."},{"q":": 등급제?","a":": 네."},{"q":": 수능에서는요.","a":": 미적분 선택했습니다."},{"q":": 30초 정도 남았는데 짧게 마지막으로 하고싶은말 해주세요.","a":": 네. 제가 면접을 처음보는 학교라 많이 떨려서 명확하게 답하지 못한 것 같습니다. 하지만 고등학교 3년동안 많은 활동을 하며 다양한 역량을 길렀고 많은 노력을 하였습니다. 이 숭실대학교에 합격해 부족한 역량을 기르며 대학생활을 하고 싶고 호우회라는 동아리에 가입하여 장애인들과 활동하는 동아리도 해보고 싶고 풀무제라는 축제도 즐겨보고 싶습니다. 꼭 숭실대학교에 합격해 이 학교에 걸맞는 학생이 되고 싶습니다. 후배들을 위한 조언 면접관님들에 따라 압박면접일 수도 편한 분위기 일수도 있으니 둘 다 연습하는게 좋아보임.입장가능한 시간에 바로 들어가 대기실에서 최대한 많은 것을 살펴볼 수 있으면 좋다.생기부에 있는 것만을 물어보시기 때문에 생기부를 꼼꼼히 보면 좋을 것 같다.긴장하면 아는 것도 생각이 안날 수 있지만 최대한 많은 것을 말하려고 의식적으로 생각하면 도움이 될 것 같다. 세특 말고 학생의 생각을 묻기위한 질문도 언제든지 할 수 있으니 너무 세특에 치우치지 말기."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"기계공학부","jeonhyeong":"학생부종합(SSU미래인재)","method":"지원동기->생기부 기반 탐구 질문->전공 관련 질문->생기부외 견해 질문->입학의지 확인->마지막 할말","notes":"생기부 내용을 잘 숙지해야함. 면접시간은 13분정도로 길며 본인은 15분 이상 진행함","qa":[{"q":"안녕하세요. 아침에 여기까지 오시느라 수고했어요","a":"넵 안녕하십니까.성실히 답변드리겠습니다."},{"q":"넵 지원동기 한 번 말해 보세요.","a":"사회를 발전시키는 공학자가 되고자 지원한 가번호 xx입니다. 저는 관찰하는 것을 좋아합니다. 수학과 물리에 대한 관심을 바탕으로 숭실대 기계공학과의 체계적 학습 속에서 성장하고자 지원하였습니다."},{"q":"물리학을 좋아한다하셨는데 그럼 물리에서 뭐가 젤 어렵나요?","a":"역학이라 생각합니다. 계산이 까다롭다보니 실수를 많이하는 것 같습니다. 하지만 저같은 경우 이중슬릿같은 현대물리에서도 실험을 하며 어려움을 많이 느꼈습니다."},{"q":"이중슬릿 실험이 뭐죠?","a":"해당 실험은 토마스 영이 진행한 것으로 빛의 이중성을 확인하는 실험이였습니다. 영의 방식대로 저 역시 검정색 스프레이를 이용하여 커터칼로 슬릿을 긋고 원초적 방식으로 설계, 진행하였지만 정밀한 측정에 어려움을 느껴 지역대학 교수님의 장비를 이용. 파장에 따른 간섭무늬를 관찰했습니다."},{"q":"이게 다 혼자한건가요?","a":"넵 직접 설계하고 진행했습니다."},{"q":"그러면 같이 한 활동은 없는건가요?","a":"아닙니다. 프로펠러 실험의 경우 항공우주역학, 수학과, 컴퓨터 공학의 진로를 희망하는 친구들과 함께 진행하였습니다 3D프린팅을 통한 2,3,4엽 15,30,45,60도의 프로펠러를 설계하여 분석하였습니다."},{"q":"그 실험에서 어떤 역할을 했나요?","a":"저같은 경우 종속변인, 통제변인을 확고히 하고 팀장으로써 실험 결과를 직접 분석, 수치를 기록하는 역할을 맡았습니다."},{"q":"종속변인, 통제변인이라 하셨는데 그럼 그건 뭐고 어떻게 통제했어요?","a":"프로펠러 실험은 유체를 다루는 실험이라 생각합니다. 유체는 흔히 공기, 물처럼 비닐봉지안에 담았을 때 형태가 바뀌는 걸 모두 칭합니다. 따라서 창문같은 것이 열려있어도 실험 결과가 바뀔 수 있기에 이러한 디테일을 놓치지 않았습니다."},{"q":"그럼 우리 학교에서 뭘 배우고 싶나?","a":"저같은 경우 숭실대가 4대 역학을 굉장히 잘 가르치는 명문학교라 알고 있습니다. 저는 유체역학을 잘한다고 생각해서 해당 부분을 전공으로 살리고 싶습니다."},{"q":"유체역학에 관해 아는 공식이 있나?","a":"베르누이의 법칙을 알고 있습니다"},{"q":"그럼 그거 설명하지 말고 다른 공식도 혹시 몇 개 더 아나?","a":"로켓방정식에 대해 알고 있습니다. 고급 물리학 수업에서 배운 로켓방정식은 질량에 따른 속도 변화량과 연료 배출에 따른 질량 변화률 간 관계를 서술합니다."},{"q":"이중슬릿을 하면서 양자역학의 확률적 개념을 이해한다고 되어있는데 설명해줄래요?","a":"저는 현대물리학도 굉장히 좋아해서 설명드리기 쉬울 것 같습니다. 하이젠베르크의 불확정성의 원리를 말씀드리자면 운동량을 알면 위치를 알 수 없고 위치를 알면 운동량을 알 수 없습니다. 이처럼 모든 건 불확정이기에 확률로 표현해야한다는 것이 양자역학의 기본 원리입니다."},{"q":"생기부 질문은 이미 잘 준비하셔서 더 의미가 없을 것 같고 다른 질문을 할게요. chat GPT 써본 적이 있나요?","a":"쳇 지피티도 자주 활용합니다 평소에 탐구에 사용하곤 했습니다."},{"q":"그럼 그걸 자료조사에 썼나요?","a":"아닙니다. 저같은 경우 논문을 이용하여 탐구를 진행하며 이후 쳇 지피티로 재검증하는 탐구 방식을 선호했습니다."},{"q":"논문이요? 학생들이 논문도 볼 줄 아나?","a":"숭실대학교에 입학하려면 그 정도 노력은 필요하다고 생각합니다."},{"q":"논문을 주로 어디서 보죠?","a":"DBPIA나 RISS에서 기계공학 저널을 자주 찾아보곤 합니다."},{"q":"그러면 어떤 논문을 고르는지?..","a":"KCI인증 논문을 이용하는 것이 더 공신력이 좋다고 알고 있습니다. 저도 숭실대학교에서 이런 논문을 쓰는 학생으로 발전하고 싶습니다."},{"q":"면접 시간이 다 되서 빠르게 몇 개만 더하겠습니다. 학생회장으로 역임하면서 어려웠던 점이 있나요?","a":"전 고등학생 중에서도 가장 바쁘게 학교생활을 보냈다고 생각합니다. 학업 스케쥴과 교내 일정을 맡주어서 학교를 대표하는 것이 어려웠습니다."},{"q":"그러면 시간 관리는 어떻게 했나?","a":"다른 학생들이 놀 때 공부를 하고 평소엔 교내 행사나 일정에 전념했던 것 같습니다. 조금 아쉬운 점이 있다면 독학으로 사교육없이 3년간 공부하여 수학 성적이 노력에 비해 잘 나오지 않은 것 같습니다. 그저 내신 문제의 풀이과정을 외워서 접근하는 것은 저와는 잘 맞지 않았습니다."},{"q":"우리 학교에 올건가요? 숭실대에서 미래 학업 계획이 어떻게 되죠?","a":"전 숭실대학교에서 제 꿈을 키우고 싶습니다. 우리나라의 경우 공학자들이 해외로 자주 나가곤 합니다. 트럼프 대선에서 일론머스크를 통해 국력을 자랑하듯 우리나라도 과학기술로 국력을 보여줘야한다 생각합니다. 저는 숭실대학교 대학원을 진학하여 박사까지 딴 후 한국과학기술연구원에서 조국을 위해 힘쓰고자 합니다."},{"q":"수고하셨습니다","a":"넵 면접 봐주셔서 감사합니다후배들을 위한 조언 전공 질문을 많이 하시고 생기부 기반이니 생기부는 완벽히 숙지할 것가능하다면 전공 관련 이슈나 배경지식도 쌓아놓는 것이 좋음기계공학 지망이라면 유체역학이나 양자역학 같은거 얕게라도 공부하고 면접보면 좋음"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"의생명시스템학부","jeonhyeong":"학생부종합(SSU미래인재전형)","method":"자기소개 및 지원동기 → 생명 개념 질문 → 면역학(소인수 수업) 질문 → 면역학(소인수 수업) 질문 → 생명과학실험 질문 → 정보 질문 → 공동체 역량 질문","notes":"면접 위원 수 : 2명(교수님, 입학사정관)","qa":[{"q":"자기소개 및 지원동기 말해주세요.","a":"안녕하십니까? 저는 끊임없는 탐구력과 호기심을 지닌 지원자입니다. 고등학교 재학 중에 ‘내 몸 속의 우주’라는 책을 읽은 적이 있습니다. 책에서 장내 유해균과 유익균의 관계를 읽으며, 장내 유해균을 제거하기 위해 사용한 항생제에 내성이 생길 수 있다는 점을 알게 되었습니다. 이후 2학년 둥지 캠프에서 형질 전환 대장균에 대해 항생제 내성 실험을 실시했으며, 또한 천연항생제 제작을 통해 인체에 끼치는 악영향을 줄일 수 있도록 탐구한 경험이 있습니다. 책의 내용을 바탕으로 실험 주제를 제시하고 지식을 확장해나가며 한 분야에 대해 깊이 있는 탐구를 진행했기에, 저는 호기심과 탐구력을 지녔다고 자신할 수 있습니다. 이런 역량을 바탕으로 생물 정보의 데이터를 분석하는 맞춤형 치료제 개발에 대한 공부와 연구를 해나가고 싶기에 지원하게 되었습니다."},{"q":"생명과학을 이수하였는데 생명과학 관련 이론에 대해서 물어볼게요 DNA ~~과정 설명해주세요.","a":"DNA 전사 번역 단백질 합성 과정을 설명함."},{"q":"면역학의 세계에서 sds-page를 하였다고 했는데 단백질 전기영동 과정을 설명해주세요.","a":"먼저 붕어 기관을 파쇄해서 상등액을 얻습니다. 이후 sds-page에 필요한 gel을 만듭니다. seperating gel과 stacking gel의 차이는 pH입니다. stacking gel의 pH는 6.8이기 때문에 염화이온과 글라이신 사이에 단백질이 위치하며 같은 출발선에서 출발하게 합니다. seperating gel의 pH는 8.8이기 때문에 염화이온, 글라이신 뒤에 단백질이 존재하여 온전히 단백질 분자량만 영향을 주면서 내려옵니다. 이후 단백질 마커를 통해 분자량을 확인해보니 단백질이 36 분자량인 것을 확인하였습니다."},{"q":"단백질 분자량을 어떻게 확인했나요?","a":"혹시 다시 한번만 말씀해주실 수 있나요?"},{"q":"단백질 분자량을 어떻게 보았나요?","a":"단백질 마커를 통해 알아보았습니다. 단백질 마커는 10개의 단백질 사이즈가 들어있어..."},{"q":"단백질 마커가 무엇인지는 압니다. 염색을 통해 확인하였나요?","a":"아 네..!"},{"q":"이중 면역 확산법에 대한 과정을 설명해주세요.","a":"아가로스겔을 만들어서 가운데에 항체를 두고 나머지에 항원을 넣어 확인하였습니다. 저는 실험을 통해 완전융합을 확인하였습니다. 완전 융합이란 두 항원이 항체와 반응하여 생긴 침강선을 의미합니다."},{"q":"이중 면역 확산법에 대해 꼬리 질문하심.","a":"완전 융합 말고도 부분적 융합이랑 완전교차가 있습니다. (이 두 개의 정의를 설명하려다가 중간에 까먹어서 다시 처음부터 말해도 되냐고 물어보고 다시 처음부터 답변함.)"},{"q":"16S rRNA에 대해 말해주세요.","a":"실험 과정 쭉 설명함."},{"q":"전자기기에 황색포도상구균이 있을 것이다 라고 했는데 왜 그렇게 가설을 세웠나요?","a":"2학년 둥지캠프에서 항생제 감수성에 대해 실험을 하였습니다. 이를 통해 항생제 내성균이 위험한 것임을 인지하고 일상생활에도 이런 균이 존재하는지 확인해보고 싶어 이런 가설을 세웠습니다."},{"q":"저희 학교가 생명정보학도 배우는데 그와 관련된 프로그래밍 활동 있나요?(이때 떨려서 입이 안 떨어져서 교수님이 다시 한번 질문해주심.)","a":"1학년 정보시간에 문제해결 프로젝트 하던 것이 인상깊었습니다. 1학년 정보시간에 의료기기 배터리 잔여량을 알아보기 위해 프로그래밍하였습니다. 배터리가 70% 이상일 때 if문 사용해서 배터리 잔여량과 초록색을 출력하였고 배터리가 40% 이상일 때 else if문을 사용해서 배터리 잔여량과 노란색을 출력하였습니다. 배터리가 40% 이하일 때 배터리 잔여량과 빨간색을 출력하는 프로그래밍 하였습니다."},{"q":"공동체 역량이 드러나는 활동에 대해 구체적인 예시를 들어 설명해주세요.","a":"2학년 실험나눔축체가 인상깊었습니다. 실험나눔축제란 2학년이 1학년에게 실험과 관련된 이론을 설명한 뒤 실험을 진행하는 축제입니다. 실험나눔축제에서 역할 분담이 제대로 되지 않은 것을 보고 쉬는 시간에 친구들을 모아 역할 분담에 관련된 얘기를 하여 저는 이론을 설명하는 역할을 맡았고 친구는 준비물을 준비하는 역할을 맡았습니다. (면접관) 시간이 넘었네요.(이때 마지막으로 하고 싶은 말 안 시키셔서 당황했고 먼저 마지막으로 하고 싶은 말 해도 되냐고 물어볼 수 있었는데 못 물어보고 끝냄.)후배들을 위한 조언 -면접 발표날이 월요일이었고 면접은 그 주 금요일이었습니다. 면접이 수능 2주 뒤라서 발표가 나기 전부터 면접 연습을 할 수 있었지만 상향으로 쓴 대학이 다 광탈되면서 의욕이 사라져서 본격적으로 면접공부를 한 건 발표날부터 시작했습니다. 이 부분이 가장 후회되는 부분입니다. 꼭 멘탈 부여잡고 종합이지만 붙을 가능성이 높은 학교가 있다면 외부적인 요인을 다 무시하고 꿋꿋하게 면접공부 하세요.-그리고 생기부 공부도 중요하지만 모의면접을 많이 해보는 것이 도움이 된다고 생각합니다. 왜냐하면 그냥 생기부를 읽는 것과 말하는 것을 정말 달라요. 저도 면접 보는 그 주 수요일에 처음 모의면접을 했는데 바로 망했다는 생각이 들었습니다. 하지만 면접이 망했다고 생각이 들어도 혹시 면접 질문이 쉬울 수도 있다는 마인드로 포기하지 말고 연습하세요. 저도 목요일 날 모의면접이 너무 어려워서 다 포기하고 싶었는데 막상 가니까 모의면접 질문보다 쉬웠습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"컴퓨터학부","jeonhyeong":"학생부종합(SSU미래인재전형)","method":"자기소개 → 전공 관련 질문 → 마지막 할 말-블라인드 면접인 관계로 교복 착용 불가.","notes":"-수험표와 신분증 반드시 지참.-전자기기 사용 불가.","qa":[{"q":"자기소개 간단히 해주세요.","a":"창의적, 자기주도적 문제해결 역량 중심으로 준비한 자기소개."},{"q":"정보 수업에서 C언어 시작한건가요?","a":"정보, 정보과학에서 C언어, 데이터과학과 머신러닝에서 파이썬 학습했다고 답변."},{"q":"공동 교육과정에서 프로그래밍도 들었네요?","a":"재귀함수, 구조체 등 배웠던 개념들 설명함."},{"q":"정보과학에서는 1학년이랑 다른 내용을 배운 건가요?","a":"정렬 알고리즘, 이차원 배열 관련 내용 설명함."},{"q":"퀵 정렬 탐구했다고 하는데 자세히 설명해주세요.","a":"분할 정복 방법으로 정렬하는 알고리즘, 피벗으로 비균등하게 분할하며 교환하는 과정 설명."},{"q":"최악의 경우는 어떻게 되나요?","a":"O(n^2)의 시간복잡도를 가집니다. (최악의 경우에 어느 정도로 비효율적인지를 묻는 줄 알고 시간복잡도로 대답함.)"},{"q":"그게 아니라 최악의 경우는 리스트가 어떤 상태일 경우인가요?","a":"이미 정렬되어 있거나 역순으로 정렬되어 있는 경우입니다."},{"q":"테일러 급수에 관해서 탐구했던 내용 설명해주세요.","a":"테일러 급수는 정의역의 특정 점에서의 미분계수들을 계수로 하는 다항식 극한이라는 정의 설명. 컴퓨터에서 sin, cos과 같은 초월함수를 어떻게 계산하는지 궁금하여 이를 탐구하고 매클로린 급수로 근사식의 최고차항에 따라 비교하며 오차가 줄어가는 과정을 확인했다고 답변."},{"q":"양자암호와 양자내성암호의 차이점이 무엇인가요?","a":"양자 암호는 양자역학적 특성을 활용하여 복제 불가능성, 측정 후 붕괴라는 특징을 가짐. 양자 내성 암호는 양자역학적 특성을 사용한 것은 아니며 인수분해, 이산로그 등 기존 암호체계가 양자컴퓨터를 이용한 공격에 무력화되기에 다항 시간 내에 무력화되지 않는 내성을 가진 암호를 말한다고 답변. 다변수 기반 암호를 예를 들어 설명함."},{"q":"인공신경망이 뉴런의 어떤 특징을 모델링 한 것인지?","a":"퍼셉트론의 동작 원리, 활성화 함수의 임계치에 따른 출력 과정 중심으로 답변."},{"q":"경사하강법은 무엇인지?","a":"신경망의 학습 과정에서 손실함수의 기울기로 최소값에 도달할 때까지 가중치를 수정해나가는 최적화 방식입니다."},{"q":"1학년에 방화벽을 주제로 한 활동이 있는데 탐구했던 내용 설명해주세요.","a":"(1학년 음악 시간에 진로 관련 주제 잡아서 라디오 영상 제작하는 활동. 음악 쪽에서 나올 줄은 예상 못 했음.) 보안의 중요성 강조하기 위해 주제로 선정했다는 활동 동기 설명. 외부 네트워크에서 들어오는 접근 시도에 대해 설정된 일련의 보안 규칙에 따라 단계적으로 허용하는 방식이라고 답변."},{"q":"1분 정도 남았는데 더 말하고 싶은 내용이 있으면 자유롭게 해주세요.","a":"질문 없었던 핵심 활동들 언급하며 마무리함.후배들을 위한 조언 -면접관 두 분 다 친절하게 질문해주셨습니다. 답변에 핀트가 어긋나면 다시 설명해주시기도 하니 준비한대로 대답하시면 될 것 같습니다.-전공과 관련된 개념이라면 관련성 없는 교과목 세특에서도 질문이 나올 수 있으니 꼼꼼하게 준비하시는 것이 좋을 것 같습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"컴퓨터학부","jeonhyeong":"학생부종합(SSU미래인재전형)","method":"학과 지원동기 → 수강과목설명 → 생기부 → 마지막말","notes":"1대2 면접인데 한분은 컴퓨터 한분은 수학쪽 질문을 함","qa":[{"q":"컴퓨터공학과 지원 동기는 무엇인지 구체적으로 말해주세요.","a":"저는 소프트웨어뿐 아니라 하드웨어와 컴퓨터 작동원리를 익히기위해 지원습니다. 미세먼지 측정기 제작활동을 통해 (중략) 소프트웨어 개발을 위해선 하드웨어를 우선적으로 익혀야함을 알게되었습니다. 그래서 컴퓨터공학과에서 (중략) 배우기 위해 지원하게 되었습니다."},{"q":"C언어를 배운 수업이 있나요?","a":"프로그래밍과 정보과학 수업에서 들었습니다."},{"q":"두 과목에서 각각 어떤 수업을 했나요","a":"프로그래밍은 문법과 개념 정보과학은 게임선택 프로그램 제작 처럼 프로잭트형식의 수업을 했습니다."},{"q":"게임선택 프로그램을 코드위주로 설명해보세요","a":"게임 종류, 게임 설명, 게임 선택 3개의 함수를 만든 후 while 문과 if문 scanf를 통해 사용자의 선택에 따라 함수가 작동되도록 제작했습니다."},{"q":"경사하강법에서 쓰이는 미분을 설명하세요","a":"딥러닝모델에서 ~ 손실함수를 구합니다. 이때 손실함수의 값이 적으면 성능이 좋다는 의미인데 손실함수의 최솟값이 나오는 파라미터값을 찾기위해 미분이 쓰입니다."},{"q":"편미분을 더 탐구했다고 하는데 편미분은 어떻게 쓰이죠?","a":"편미분은 특정 파라미터가 미치는 영향을 알기 위해 쓰입니다."},{"q":"편미분과 미분의 차이는 무엇인가요","a":"편미분은 여러 미지수가 있을때 특정미지수를 기준으로 미분하고 나머지는 상수처리를 하여 계산합니다."},{"q":"이진탐색에 관해서 탐구했다고 하는데 코드위주로 설명해보세요.","a":"재귀함수를 통해 타갯값이 중간값보다 작으면 재귀함수의 범위를 절반씩 줄여가며 계산 (중략) 이를 반복했습니다. (좀 어버버함)"},{"q":"RSA암호화에 대해 설명해주세요.","a":"수신자가 공개키와 개인키 생성 후 송신자에게 공개키 전달. 송신자가 공개키로 정보 암호화 후 전달하는 방식입니다. 수신자가 개인키로 암호 해독을 하는 알고리즘입니다."},{"q":"마지막으로 하고싶은말","a":"숭실대학교에 겜마루와 SCCC같은 동아리와 소모임 활동이 있는거 알게되었고... (뭐라했는지 기억이 안남)후배들을 위한 조언 예상질문 보다 생기부에 나오는 개념이나 한 활동들 다시 다 공부해서 그냥 바로 대답하는게 더 좋을 듯 합니다. 그리고 활동하나 깊게 파는거보다 모든활동에서 다 조금씩 심화적인거 알아두는게 좋을 듯 합니다. 생각보다 내가 중요하다고 생각하는게 잘 안 나옵니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"화학공학과","jeonhyeong":"학생부종합(SSU미래인재전형)","method":"아이스브레이킹용 질문 → 본교 관련 질문 → 화학 개념 질문 → 활동 관련 질문 → 취미 질문","notes":"생기부에 있는 화학 교과 개념 많이 물어보심, 자기소개, 지원동기 안 물어봄. 면접 분위기 좋음. 면접관 두 분 계셨고 두 분 다 교수님이었음.","qa":[{"q":"진로를 언제부터 화학공학과로 정했어요? 왜?","a":"고등학교 1학년 때 진로를 선택하는 과정에서 화학 선생님인 담임 선생님의 영향을 받아서 화학 과목을 좋아하게 되었습니다. 또, 환경 관련 활동을 하면서 환경 오염 문제를 인식하고 자연스럽게 화학공학과를 진로로 정하게 되었습니다."},{"q":"화학공학과는 많은데 왜 숭실대학교 화학공학과를 지원했을까요?","a":"숭실대학교에 에너지 융합 대학원이 있는 것으로 알고 있습니다. 거기에 진학하기 위해서 숭실대학교에 지원했습니다! (면접 보기 전에 학교 산책하다가 현수막 걸려있는 거 보고 ‘이런 질문 나오면 이렇게 대답해야겠다’ 생각했던 건데 물어보셔서 신나게 대답함.)"},{"q":"오~. 벌써부터 대학원까지 생각하고 있어요?","a":"미래를 장담할 순 없겠지만, 지금의 저의 생각과 계획으로는 그렇습니다!"},{"q":"그럼 이제 면접 시작해볼게요. 화학 관련해서 물어볼게요. 산화 환원 설명해주세요. (생기부에 있는 개념)","a":"산화는 산소를 얻거나 전자를 잃는 반응이고, 환원은 산소를 주거나 전자를 얻는 반응. 그리고 산화 환원은 항상 동시에 일어난다고 알고 있습니다."},{"q":"(흐뭇한 표정으로) 엔탈피는 뭔가요? (생기부에 있는 개념)","a":"엔탈피는 발열반응이나 흡열반응이 일어날 때, 열에너지의 물리량으로 알고 있습니다! 흡열반응일 때는 엔탈피가 증가하고 발열반응일 때는 엔탈피가 감소하는 거로 알고 있습니다!"},{"q":"산을 정의해볼래요? 브뢴스테드의 정의로요. (생기부에 아주 조금 있는 개념임.)","a":"(당황하며. 브뢴스테드 처음 들어봄.) 산의 정의를 정확하게 숙지하고 있지 않습니다. 산과 염기할 때의 산성이 있다는 거 정도만 알고 있습니다."},{"q":"그럼 수소이온 관련해서 얘기해보세요. 산은 수소이온을 받는 거예요? 주는 거예요?","a":"받는 거로 알고 있습니다! (몰라서 찍음. 근데 맞힘.)"},{"q":"맞아요. 생기부에 우리나라의 수소생산현황을 알아보았다고 적혀있던데, 우리나라 수소생산현황을 설명해주세요.","a":"우리나라는 화석연료를 기반으로 생산한 수소인 그레이 수소의 생산량이 가장 많아서 수소연료를 생산하는 데에서 환경 오염이 생길 수 있다는 딜레마가 있는 것으로 알고 있습니다."},{"q":"음? 그럼 화석연료를 기반으로 한 수소? 화석연료가 수소로 변하는 거예요?","a":"아니요. 화석연료를 기반으로 생산한 전력으로 수전해해서 얻은 수소가 그레이 수소라고 알고 있습니다."},{"q":"P2X 기술은 뭐예요?","a":"먼저 신재생 에너지는 간헐성을 해결해야 하는 문제가 있습니다. 이걸 해결하려면 신재생 에너지로 얻은 남은 전력을 보관해야 하는데, 그 기술이 P2X 기술입니다. P2X 기술로는 P2G, P2H 기술이 있습니다."},{"q":"P2G 설명해주세요.","a":"P2G는 전력을 G, 가스로 저장하는 건데, 메탄 기체나 수소 기체로 바꾸어서 저장하는 거로 알고 있습니다."},{"q":"3학년 활동을 보니까 Fick’s 법칙을 탐구했던데.. 이건 대학교 3학년 때 배우는 거거든요. 이걸 탐구하고 3차원 모델링을 해봤다니. 기특하네요. 제1법칙, 2법칙 설명해볼래요?","a":"아. 탐구할 때도 어려웠던 것 같아요. 기억이 잘 안납니다."},{"q":"그럼 기체 분자는 왜 운동할까요? 바람은 왜 불까요?","a":"(매우 당황하며) 분자가 항상 운동한다고 배우긴 했는데. 잘은 모르지만 제가 추측하건데 원자가 움직이기 때문인 것 같습니다."},{"q":"그럼 그 물에 잉크를 떨어뜨리면 잉크가 확산하죠? 이건 왜 그럴까요?","a":"엔트로피가 항상 증가하기 때문으로 알고 있습니다."},{"q":"네 그렇죠. 농도 이런 거로 한번 Fick’s 법칙 한번 설명해볼래요?","a":"네. 1법칙은 농도기울기가 높은 곳에서 낮은 곳으로 확산되는 거로 알고 있고 2법칙은 기억이 안 납니다."},{"q":"그래요. 이런 건 사실 화학공학과에서 배워도 되는 거예요. 2학년 행특을 보니까 연못 정화 봉사 이런 걸 했다고 나오네요. 여기서 원래 연못의 수질이 pH 3.0 이었다고 나오는데, 이건 산성인가요 염기성인가요？ 상당히 낮은 수치인데 왜 이렇게 낮다고 생각해요?","a":"산성입니다. 이끼가 많이 꼈는데, 관리하는 사람이 없어서 녹조현상이 점점 심해져서 그런 것 같습니다."},{"q":"(한 면접관이 다른 면접관에게) 이 정도면 손 넣으면 녹겠는데요? (다른 면접관이) 그러게요.","a":"아. 그런데 그렇게 낮게 나왔다는 것은 저희 학교 pH 측정 기기에 문제가 있거나, 저희 측정방식에 문제가 있었던 것 같습니다."},{"q":"그쵸? 그런 것 같아요~^^ 행특에 보니까 밝다는 얘기가 많은데, 비결이 뭐예요?","a":"저는 부정적인 상황을 긍정적으로 보는 힘이 있는 것 같습니다. 그래서 밝게 봐주신 것 같습니다! 이후 취미 관련 질문 후 마무리후배들을 위한 조언 -다른 학교에 비해 활동 내용보단 기본 개념을 많이 물어보십니다. 생기부에 있는 화학 교과 개념을 물어보시는 것 같으니 모르는 개념이라면, 보고 외워가면 좋을 것입니다. 화학 관련 내용이 있다면 행특이라도 물어보실 수 있으니 중요도가 떨어진다고 생각되는 활동이라도 한번 읽어보는 것을 권장합니다. -면접관님들은 딱딱한 분위기보다 대화하는 분위기를 좋아하십니다. 생각보다 별거 아니니, 긴장하지 말고 학교 선생님들이랑 얘기한다고 생각하고 자연스럽게 답변하는 게 좋을 것 같습니다.-면접장에 들어가서 유의사항을 알려주시고, 휴대폰 등 전자기기를 걷고, 가번호를 알려주시는 데에 30분 정도 시간이 걸립니다. 면접 시간은 한 사람당 10~15분 정도기 때문에 가번호 5번 이내가 아닌 이상 기본으로 1시간 30분 이상 기다려야 하니 기다리면서 먹을 간식이랑 물은 필수입니다!!! 긴장을 녹여줄 핫팩도 추천합니다!!! 면접 들어가기 직전에 긴장이 안 풀린다면 심호흡을 크게 한 번 크게 하고 들어가세요!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"숭실대학교","dept":"IT융합학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"미적분질문 → 창체 → 인상깊었던 활동 → 전공질문 → 프로그래밍질문 → 문제점 극복 → 마지막 멘트","notes":"","qa":[{"q":"미적분 시간에 학습한 테일러 급수에 대해 설명해주세요.","a":"대답함."},{"q":"고등학교 3학년 때 했던 전자공학 전문가 활동에 대해 알려주세요.","a":"대답함."},{"q":"가장 인상 깊었던 활동은 무엇인가요?","a":"미적분회로입니다. 이에 미적분 시간에 미분과 적분을 어떻게 아두이노에 적용할 수 있을까궁굼증을 가지게 되었고 또한, 극한이라는 개념을 어떻게 구현할 수 있을까 궁금하여이에 대한 회로를 만들어보게 되었습니다."},{"q":"이에 대해 구체적으로 알려주세요.","a":"대답함."},{"q":"Rc비행기를 만들었는데 이에 대해 알려주세요.","a":"대답함."},{"q":"프로그램잉 시간에 배운 내용은 어떤 것들이 있나요?","a":"파이썬 배웠습니다."},{"q":"파이썬으로 1부터 10까지 더하는 코드를 만들어보세요.","a":"..... for문으로 1부터 10까지 반복한 이후 이를 리스트에 저장하고 sum이라는 함수를 통해 모두 더한 이후 print라는 함수를 통해 이를 확인할 수 있습니다."},{"q":"문제점을 극복했던 사례를 알려주세요.","a":"우선 제가 고등학교 1학년때 섬광방패에 대해서 만들었던 적이 있습니다. 이에 시프트레지스터까지는 괜찮았지만 LED가 켜지지 않았고 트랜지스터에 문제가 있다고 생각해Base와 Emmiter에 전압을 측정해보면서 0.7v가 찍히는지 확인해보며 고장난 트랜지스터를 찾았고 이에 이를 모두 제거하고 다시 납땜하며 원하는 결과물을 얻을 수 있었습니다."},{"q":"c++도 했어요?","a":"네"},{"q":"c++을 어디까지 배웠나요?","a":"반복문, 조건문, 자료형 정도 배웠습니다."},{"q":"그럼 기초만 배운거네요?","a":"네, 하지만, 제가 혼자서 c++을 모두 배우기에는 한계가 있고, 각종 센서를 조종하기 위해서는 단순히 이에 대한 자료를 통해서 해결할 수 있다고 생각했기 때문에 이 정도면 충분하다고 생각했습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"글로벌미디어학부","jeonhyeong":"학생부종합(SSU미래인재)","method":"대기실 (마스크 착용) → 수험번호 호명 후 입장 → 퇴실","notes":"마스크 준비, 휴대폰 제출","qa":[{"q":"지원 동기를 말씀해 주세요.","a":"저는 게임 프로그래머가 되고 싶은 학생입니다. 이 꿈을 이루기 위해 ~ 한 활동을 하였고 이처럼 저는 노력을 통해 발전하는 학생이라고 생각합니다."},{"q":"게임에 관심이 있으시다고 하셨는데 다른 학교에는 게임학과가 있지 않나요?","a":"네 그렇지만 저는 게임 프로그래밍 뿐만 아니라, 글로벌 미디어 학부에서 그와 관련된 3D그래픽이나 스토리텔링 등의 과목을 통해 융합적 인재로 성장하고 싶어 이 학부를 지원하게 되었습니다."},{"q":"시그모이드함수와 렐루 함수에 대해 조사하셨는데 이 둘의 차이점은 무엇인가요?","a":"시그모이드 함수에서 기울기 소실 문제를 해결한 것이 렐루함수라고 알고 있습니다."},{"q":"우리 학과의 단점은 무엇이라고 생각하나요?","a":"다양한 과목과 그에 따른 다양한 방향들이 있어, 만약 진로를 확실히 정하지 않는다면 방황하게 될 수도 있다고 생각합니다."},{"q":"방금 얘기한 우리 학과의 단점을 본인은 어떻게 극복할 계획인가요?","a":"저는 게임프로그래머가 되겠다는 목표를 가지고 있기 때문에, 제 진로와 관련한 과목을 중심으로 수강하겠습니다."},{"q":"입학하게 된다면 해보고 싶은 활동이 있나요?","a":"게임 프로그래밍을 하는 친구나, 그림을 그리는 친구, 스토리를 짜는 친구들을 모아 완성된 게임을 만들어보고 싶습니다."},{"q":"우리 학교에 대해 질문 있나요?","a":"숭실대학교 특강에 관한 질문"},{"q":"마지막으로 하실 말씀 있으시면 해 주세요.","a":"저는 게임이란 기술과 예술의 융합이라 생각합니다.후배들을 위한 조언 대기하는 시간이 길 수 있으니 면접 대기실에서 읽을 것들을 준비하세요.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"법학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"생기부 교과 관련 질문 → 교과 성적에 대한 능력 질문 → 지원동기 → 진학이후 계획 질문 → 마지막으로 하고 싶은 말","notes":"","qa":[{"q":"‘수학 과제 탐구’는 무슨 과목인가요?","a":"학교에서 정식으로 개설된 진로 과목입니다. 저는 그 과목에서 일상생활에서 쉽게 접할 수 있는 장난감인 ‘하노이의 탑’을 소재로 하여 일반항의 규칙을 유도해내는 공식을 증명한 활동을 한 적이 있습니다."},{"q":"법학과에서는 수학적 논리력이 중요한데 수학 성적이 좀 부족하네요?","a":"스스로 잘 알고 있습니다. 하지만 절대로 수학 공부를 포기한 적은 없습니다. 수학 성적이 부족한 것은 사실이지만, 국어나 영어 같은 과목에서 상대적으로 좋은 성적을 받았기에 보완할 수 있었습니다."},{"q":"국어를 잘했다고 했죠, 법학과에서는 읽기 능력이 중요한데 능력에 자신이 있나요?","a":"네. 실제로 저는 고등학교 생활 내내 다양한 장르의 글들을 자주 읽었습니다. 그리고 저는 다양한 진로 관련 탐구 활동을 할 때 실제 판례와 법조문 등을 자주 보는 연습을 했습니다. 처음에는 낯선 문장과 단어에 어려움을 겪었지만, 현직 변호사가 투고한 칼럼 등을 참고하며 읽는 연습을 하니 이제는 그런 판례와 법조문 등을 읽는 것이 익숙해졌습니다. 따라서 저는 읽기 능력에 자신이 있습니다."},{"q":"‘국제법’ 교과목이 공동이라 적혀있는데 뭔가요?","a":"(자세한 질문과 답변이 기억나지 않음) 학교에 개설되지 않은 교과목이어서 공동 교육과정으로 수강하였습니다."},{"q":"언제부터 법학에 관심을 가지게 되었나요?","a":"어렸을 때 어머니의 곁에서 수사 드라마나 사건 보도 프로그램 등을 즐겨보며 사법에 대한 호기심을 키워갔습니다. 중학생이 되어 ‘부산 여중생 폭행 사건’을 접하게 되며 소년법과 촉법소년에 대해 알게 되었습니다. 그리고 고등학생이 되어 그것들을 탐구하였습니다. 3학년이 되어 ‘어떤 호소의 말들’이라는 책을 읽고 사회적 약자를 돕는 변호사가 되기로 결심했습니다."},{"q":"촉법소년의 나이가 어떻게 되죠?","a":"소년법상 보호처분을 받을 수 있는 나이는 10세에서 19세 미만, 18세까지라고 알고 있습니다. 그리고 촉법소년은 14세 미만입니다. (면접관: 그러니까 10세에서 14세 미만까지라는 거죠?) 네. 맞습니다."},{"q":"변호사가 되겠다고 했는데 되는 과정은 알고 있나요?","a":"대학교를 졸업한 뒤 로스쿨에 진학하여 변호사 자격을 얻는 것으로 알고 있습니다."},{"q":"제2외국어 과목은 뭘 선택했나요?","a":"‘일본어 I’을 수강했습니다."},{"q":"마지막으로 하고 싶은 말이 있나요?","a":"긴장이 많이 됐었는데 생각할 거리가 많은 질문을 주셔서 좋았습니다. 내년에는 학생으로 다시 뵈었으면 좋겠습니다. 감사합니다.후배들을 위한 조언 숭실대학교가 특정 과목의 성적이 눈에 띄게 낮은 것이 아닌데도 교과 성적, 수학(修學) 능력에 관한 질문을 자주 하는 듯합니다. 학생부 종합 전형이라는 이유로 전반적으로 교과, 진로, 자율, 동아리 등에서 진로와 연관 있는(적어도 비슷한 계열의) 활동을 중점으로 면접 준비를 했으나, 전혀 예상하지 못한 질문을 몇 개 받아 당황하여 원하는 답변(키워드)을 하지 못해 성에 차지 않았습니다. 따라서 적어도 부족한 교과 성적에 대한 대비 답변, 전공 능력(사고력, 논리력)과 연관 있는 과목에 대해 숙지해 가면 좋겠습니다.학교생활을 하며 진행한 심화 탐구 활동에 대한 사실 확인(과정, 느낀 점 등)이나 전문적인 개념 질문 자체가 오지 않아 준비한 대답을 보여주지 못해 큰 아쉬움이 남는 면접이었습니다. 그 대신 자신의 학업 계획과 향후 진로, 비전에 대한 계획을 간략하게나마 세운 뒤 면접에 임하고, 그 진로에 대해 적어도 1번 이상 조사해보는 것은 추천합니다. 왜 많은 학교의 학과 중에 ‘숭실대’를 선택했는지 어필하는 것이 큰 도움이 될 것입니다.또한 답변을 너무 길게 하면 안 된다는 긴장감에 간략하게 답변하였는데, 만약 본인이 질문이 요구하는 바가 얕아 아쉬움을 느낀다면 질문의 논지에서 벗어나지 않는 한에서 자신의 역량을 어필하는 추가 답변을 해도 좋겠습니다. 저는 준비하지 못한 질문에 너무 간략하게 답변한 나머지 면접 시간이 1분 정도 남는다는 말을 실제로 면접관에게 듣게 되었습니다.마지막으로 하고 싶은 말을 위에서 작성한 바와 같이 준비했는데, 예상한 질문을 받지 못할 수도 있다는 것을 알았다면 질문받지 못한 것 중 더 어필하고 싶은 활동과 그 느낀 점, 이 학교에 합격해야만 하는 이유, 커리큘럼을 참고하여 배우고 싶은 세부 과목 등을 준비했을텐데 그러지 못해 아쉬웠습니다.요약하자면 비교과 활동을 전부 숙지하는 것은 물론이고, 교과 성적과 과목 수강 이유 등을 한 번씩 정리할 것, 지원한 학교의 학과의 커리큘럼과 자신의 진로 계획을 검토할 것, 그리고 마지막 하고 싶은 말에 꼭 어필하고 싶은 자신의 활동이나 장점 하나 준비할 것을 갖춘 채 면접을 준비했으면 좋겠습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"벤처중소기업학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"간단한 긴장풀이용 질문 → 지원동기 → 지원동기 꼬리질문→ 진로관련질문 → 성적질문","notes":"면접관님께서 친근하게 반겨주시고, 무서운 분위기도 아니라서 긴장 많이 안해도 됨!","qa":[{"q":"우리 학교 둘러보셨나요?","a":"둘러보지 못했다고 말씀드림.(잘 호응 해주심.)"},{"q":"지원동기 말해주세요.","a":"진로와 학교생활을 관련지어 말씀드림."},{"q":"지원동기에서 다양한 재능이 있다고 하는데 그걸 저희가 어떻게 알죠?","a":"생기부에 기재된 내용을 중심으로, 나에 대한 재능 말씀드리고 자세히 설명함."},{"q":"그 재능들을 어떻게 창업이랑 연관지어 볼 예정인가요?","a":"춤+카페로 말씀드림. 숭실대 벤처중소기업학과 졸업하신 선배님의 예를 들며 선배님의 사업아이템에 영감을 받아 이 아이템을 생각해냈다고 말함."},{"q":"3학년 성적이 급격히 하락한 이유는 무엇인가요?","a":"선택과목과 관련하여 솔직하게 말씀드린 후에 이러한 점을 다양한 활동으로 보완했다고 말씀드림."},{"q":"사회에서 중소기업이 갖는 역할은 무엇인가요?","a":"(조금 어렵다고 느껴져서 멈칫하니까 면접관님께서 정답이 없으니 편하게 말하라고 하심) 환경과 관련지어 말씀드린 후 중소기업의 어려움을 말하고 이에 대한 해결방안으로 전략적 파트너십에 대해서 설명함."},{"q":"고등학교 생활 중 창업과 관련된 활동은 어떤 것이 있었나요?","a":"수업량유연화 시간에 했던 창업계획서 말씀 드림. 주변의 입지 특성, 메뉴 등을 어떻게 선정했는지 상세하게 설명함."},{"q":"컨설팅에도 다양한 분야가 있는데 동아리 때 했던 컨설팅은 어떤 분야에 대해 컨설팅인가요?","a":"마케팅과 관련하여 컨설팅했다고 말씀드린 후, swot기법을 이용해서 분석했다는 것 말하고 분석한 내용에서 단점을 알아내고 그 단점을 해결하기 위해 노력한 과정까지 말씀드림.후배들을 위한 조언 생각보다 자유로운 분위기에서 면접이 진행되서 긴장이 심하게 되지 않음.지원한 학과가 원하는 인재상에 맞게 답변 준비하는 것이 좋음.학교에 대해서 관심이 많다는 것을 최대한 어필하는 것이 필요해보임.(졸업하신 선배님, 학과에 있는 동아리, 활동 등을 대학 sns에서 정보를 최대한 얻고 면접을 보는 것이 좋은 것 같음.)2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"소프트웨어학부","jeonhyeong":"학생부종합(SSU미래인재)","method":"긴장 풀어주는 질문 → 생기부 기반 전공 질문 → 마지막 할 말","notes":"","qa":[{"q":"소프트웨어 학부에 관심을 가지게 된 계기가 무엇인가요?","a":"C언어와 파이썬을 고교 과정 동안 배우면서 관심을 가지게 되었고 이런 프로그래밍 언어를 이용해 접근성이 좋은 앱을 개발하면서 사람들에게 도움을 줄 수 있다는 것을 알게 되었기 때문에 관심을 가지게 되었습니다."},{"q":"C언어, 파이썬에 대해 학습했다고 기재되어 있는데, 어떤 식으로 학습했나요?","a":"정수 두 개를 입력받아 합을 구하는 것과 같은 문제를 해결하는 경험을 쌓으며 배울 수 있었습니다."},{"q":"그러면 방금 언급한 문제 말고, 다른 문제도 해결해 본 경험이 있나요?","a":"파이썬을 이용해 모자이크 처리 프로그램을 구현하면서 얼굴을 부정적으로 사용할 때 생기는 문제점을 해결해본 경험이 있습니다."},{"q":"모자이크 처리 프로그램을 구현한 이유가 무엇인가요?","a":"딥페이크를 사용할 때 얼굴을 부적절하게 사용할 수 있다는 것을 알게 되었고 이러한 점을 해결하기 위해 얼굴인식을 통한 모자이크 처리 프로그램이 도움이 될 것이라 생각했기 때문에 모자이크 처리 프로그램을 구현하게 되었습니다."},{"q":"그러면 모자이크 처리 프로그램 구현은 동아리나 비교과에서 한 활동이 아니라 개별적으로 진행한 것인가요?","a":"동아리에서 활동하며 모자이크 처리 프로그램을 구현했지만, 문제를 실제로 해결해보는데까지 추가로 탐구해보고 싶었기 때문에 실제 프로그래밍과 적용단계는 개별적으로 진행했습니다."},{"q":"웹 개발, 앱 개발에 관심이 있다고 하셨는데 그렇게 생각하게 된 이유가 있나요?","a":"현재 가장 관심 있는 것은 앱 개발입니다. 앱 개발에 관심을 갖게 된 이유는 사람들이가장 쉽게 접근할 수 있다고 생각한 프로그램이 앱이라고 생각했기 때문입니다. 접근성이좋은 앱을 개발하고 사람들에게 도움을 제공하는 앱 개발자가 되고 싶다는 다짐을 갖게되었습니다."},{"q":"수업 시간에 선생님께서 설명하신 치환 적분법말고도 부분 적분법으로도 해결했다고 했는데 치환적분법과 부분적분법이란 무엇인가요?","a":"(개념 그대로 설명)"},{"q":"성적이나 이런 걸 보면 수학에 많은 관심이 있다고 유추해 볼 수 있는데 맞나요?","a":"수학에 많은 관심이 있습니다. 소프트웨어에 수학이 많이 사용된다고 생각했기 때문입니다. 워핑과 모핑과 같은 분야에서 연속함수의 개념이 사용되고 알고리즘과 같은 곳에서수학의 개념이 사용되기 때문에 수학에 대해 많은 관심을 갖게 되었다."},{"q":"그러면 수학적 귀납법에 대해 아는 것을 말해보세요. 개념이나, 실제 활용(적용)해본 경험에대해서도 함께 설명해 보세요.","a":"(수학적 귀납법 개념 설명), 수학적 귀납법을 재귀 함수를 사용해서 증명하는 과정을파이썬으로 구현해 본 경험이 있었습니다."},{"q":"보통 수학적 귀납법을 탐구하고 프로그래밍을 사용해서 증명하는데 반대로 한 이유가있나요?","a":"(뭐라고 답변했는지 잘 기억이 안 남)"},{"q":"마지막으로 숭실대학교에서 본인을 뽑아야 하는 이유를 얘기해주세요.","a":"(뭐라고 답변했는지 잘 기억이 안 남)후배들을 위한 조언 2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"신소재공학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"들어와서 인사","notes":"","qa":[{"q":"초전도체에 관해 아는가","a":"초전도체의 정의 설명"},{"q":"인디고와 같은 섬유 실험 많이 했는데 인디고가 무엇인가","a":"식물에서 추출되는 천연염료이다. 하지만 요즘엔 베이어 드류손에 의해 합성염료로서 더욱 많이 추출된다."},{"q":"레이온은 뭡니까","a":"레이온의 정의 설명"},{"q":"수소연료전지 원리","a":"원리 설명"},{"q":"1학년 성적이 안좋은데 이러한 이유","a":"중학교와 비슷하게 공부함, 이후 이해를 위주로 공부하여 학습법 터득"},{"q":"갈등을 극복한 경험","a":"수학 시간에 조장을 했었는데 거기서 친구들이 문제갖고 싸우는거 말려봤다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"신소재공학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"감사인사 → 지원동기 → 전공관련질문, 인성질문 → 마지막 멘트","notes":"대기실에서는 전자기기 휴대금지","qa":[{"q":"지원동기 한번 말씀해주세요.","a":"새로운 기기의 활용, 새로운 물질의 발견과 같은 새로움은 언제나 저의 과학적 호기심을 자극합니다. 고등학교 생활 동안 끊임없이 새로움을 추구했고, 이는 성장의 원동력이 되었습니다. 화학 반응과 화합물의 분석에 관심이 있던 저에게 신소재라는 방향을 잡게해 준 결정적 사건이 있습니다. 착화합물이라는 물질을 처음 배우며 직접 합성해 보고 싶다는 생각을 실현시켜 본 경험은 새로운 물질에 대한 호기심을 자극 시켰습니다. 이러한 호기심은 곧 새로운 소재라는 생각에 닿게 되어 신소재 공학이라는 꿈을 갖게 만들어 주었습니다. 문명 발전의 획기적인 순간은 신소재에 의해서 이루어졌습니다. 혁신을 이루기 위한 기술과 이론들이 생겨도 이를 실현할 도구가 없으면 발전은 이루어지지 않기 때문입니다. 따라서 저는 신소재공학과에 진학하여 세상에 획기적인 순간을 가져오는 개척자가 되고 싶습니다."},{"q":"신소재공학에 맞다고 생각하는 가장 기억에 남는 활동 1가지 이야기해주세요.","a":"착화합물 합성 실험이 가장 기억에 남습니다."},{"q":"무슨 실험이었죠?","a":"2가지 다른 착화합물을 합성해서 분광광도계를 사용해서 고급화학때 배웠던 결정장이론을 확인하는 실험이었습니다."},{"q":"반장이나 리더를 많이 하셨는데 특별한 이유가 있나요?","a":"친구들의 다양한 의견들을 듣고 이들을 통합하여 하나의 결론을 이끌어내는 과정이 매우 재밌었기 때문입니다."},{"q":"pem 수전해기술에 대해 발표를하고 높은 이해도를 보여주었다고 하는데, 설명해주세요.","a":"수전해기술은 물을 전기분해하여 수소가스를 얻는 것을 말합니다."},{"q":"영어 컨테스트 창작 발표회에서 a key solution to ~~에 대해서 설명했다고 쓰여있는데, 이게 뭔가요?","a":"탄소포집기술에 대해서 발표했습니다. 공기에 있는 이산화탄소를 포집하고 응용하는 기술은 신소재공학과 밀접한 관련이 있다고 생각했기 때문에, 이러한 내용들을 친구들에게 영어로 발표하는 시간을 가져보았습니다."},{"q":"리더로서 갈등을 해결한 적이 있나요?","a":"전 3학년때 ‘토론토’라는 학교자치활동을 직접 설계하고 운영한 경험이 있습니다. 이는 친구들에게 진로에 맞는 책을 읽게 하고, 소모둠으로 나누어 제가 직접 조장들을 선별해 토론을 진행하게 하는 활동이었습니다. 이때 몇몇 친구들이 이 활동에 성실히 나오지않았고, 이들이 원하는 바가 무엇인지를 파악하고, 개인 사정을 듣고, 이를 절충하는 방향으로 진행하거나 이들이 참여를 원하지 않으면 제외하는 방법으로 공공의 이익, 즉 토론을 위해 갈등을 해결한 적이 있습니다."},{"q":"리더의 자질은 무엇인가요?","a":"끊임없는 소통을 통해서 원하는 결론을 다같이 도출하는 것이라고 생각합니다."},{"q":"갈등이 생기면 어떻게 해결할것인가요?","a":"충분한 의사소통을 통해서 이 갈등을 절충하는 방안을 내놓은 뒤 이 방안을 밀고 갈 것 같습니다."},{"q":"NMR, GC mass같은 다양한 기자재를 이용해서 실험을 진행하셨는데, 어떻게 접하게 되었나요?","a":"첨단기기를 이용한 정성분석 실험이라는 활동을 통해서 이들을 알게 되었습니다."},{"q":"신소재공학을 졸업한뒤에 무엇을 하고싶나요?[딥변] 고등학교 3년 동안 해온 것들이 있기에 대학원에 남아서 이들에 대해 집중적으로 탐구하고 싶습니다.","a":""},{"q":"마지막으로 하고 싶은 말이 있나요?","a":"제 3학년 담임선생님은 절 미친 과학자 같다고 하셨습니다."},{"q":"선생님이요?","a":"네네, 제 열정적인 모습을 보시고 하신 말씀이었습니다. 동아리에서 진행한 기기분석실험에서는, 관련된 내용들을 모두 찾아보고, 도출한 결론에 대해서 이해가 될때까지 실험과 탐구를 진행해 열정적인 모습을 보였습니다. 전 미친 과학자에 만족하지 않았습니다. 스스로 이해하고 알게된 내용들을 학교 학술제에 참여하여 주위 학우들에게 적극적으로 알리면서 소통하는 과학자의 면모도 갖추도록 노력했습니다. 신소재공학은 개개인만 잘해서는 성공하기 어려운, 협조와 협동이 필요한 공학분야라고 생각합니다. 따라서 제가 고등학교에서 발전시켜온 저의 모습은 신소재공학에 적합하다고 생각합니다.후배들을 위한 조언 숭실대도 압박면접이 쉽지않다.리더쉽 이런거 중요하게 생각하니까 잘 준비하기씩씩하게 말하고, 담임선생님이랑 면접 준비해보기2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"영어영문학과","jeonhyeong":"학생부종합(기회균형)","method":"꿈이 바뀐 이유 → 진로를 위해 한 것이 있다면 → 대학 입학 후 학업 계획 → 독서 관련 질문 → 전공 질문 → 마지막 할 말","notes":"","qa":[{"q":"생기부를 보니까 꿈이 국어 교사에서 영어 교사, 그리고 최종적으로는 영어영문학과에 진학하는 것으로 바뀌었는데 이 과정들을 좀 자세히 얘기해줄 수 있을까요?","a":"네! 제가 중학교 1학년 때 저희 반을 가르쳐주셨던 국어선생님께서 너무 멋져보였습니다. 그래서 그때부터 저 역시 막연히 국어 교사를 꿈꾸게 되었는데요. 고등학교 1학년 때까지는 이런 마음의 변화 없이 국어 교사가 되기를 꿈꿔왔습니다. 그리고, 고등학교 2학년이 되고 나서도 저는 분명 변함없이 정말 열심히 국어 공부를 했는데도 성적이 생각보다 잘 나오지 않았습니다. 그래도 영어 과목은 열심히 공부하면 성적이 괜찮게 나와서 그럼 영어 교사를 해야겠다고 마음먹으며 잠깐 영어 교사를 꿈꾸게 되었습니다. 근데 제가 고등학교 2학년 때 ‘평화의 빛 프로젝트로 만나는 한-프 청소년 활동’이라는 교외활동을 학교선생님들께서 추천해주셔서 학교 대표로 참여하게 되었는데요. 저는 여기서 통역단의 역할을 맡으며 한국 학생과 프랑스 학생 사이의 말을 통역해주는 역할을 했습니다. 이 활동을 하던 당시에 문맥에 맞는 단어들을 바로바로 떠올리며 전달해주는게 생각보다 무척 어려운 일이구나 라는 깨달음을 얻으며 평소에는 관심을 가지지도 않았던 통역사라는 직업을 가진 분들에 대한 엄청난 존경심을 느끼게 되었습니다. 그래서 이 활동 이후 여러 매체에 통역사에 대해 찾아보다가 우연히 기생충이라는 아주 유명한 영화를 만든 봉준호 감독님의 통역사 활동을 했던 ‘샤론 최’라는 통역사의 통역 활동이 담겨 있는 영상들을 보게 되었습니다. 샤론 최는 문맥에 맞는 단어들을 바로바로 떠올려서 전달해주는 것은 물론이고, 봉준호 감독이 해외에서 우리말로 수상소감을 할 때, 아주 사소한 농담들도 섞어서 했는데 이런 농담들까지 다 통역을 해주어야 하는 사람들의 문화적 배경에 맞추어 통역을 잘 해주었습니다. 저는 이런 샤론 최의 통역 활동을 보며 ‘아! 진정한 통역사는 문맥에 맞는 단어들을 바로바로 떠올려서 전달해주는 것도 무척 중요하지만 문화적 특수성까지 잘 이해를하고 이런 이해를 바탕으로 문화와 문화 간의 간격을 좁혀주는 다리같은 역할을 해야하는구나’라는 깨달음을 얻었습니다. 그래서 저 역시 영어영문학과에 진학하여 옛 소설부터요즘 미드까지 정말 다양하게 공부하며 영어권 국가들의 문화적 특수성에 대한 깊은 이해를터득하고 이를 바탕으로 문화까지 통역해줄 수 있는 그런 통역사가 되고 싶어 영어영문학과에 진학해야겠다고 결심했습니다."},{"q":"네 잘 들었습니다. 방금 본인의 목표를 잘 설명해주셨는데, 그렇다면 학교생활 중에 본인이목표를 이루기 위해 노력을 했겠죠? 어떤 노력들을 했는지 편하게 설명해주세요.","a":"넵! 저는 다양한 활동들을 어떻게든 영어와 관련지어 수행하고자 노력했습니다. 예를들자면, ‘독서’ 과목 시간에는 한국어 문학과 영어권 문학의 전개 방식을 비교·대조하며탐구한 내용을 바탕으로 탐구보고서를 작성했습니다. 그리고 ‘영어 독해와 작문’ 시간에는언어 습득 방식인 ‘읽기 배우기’와 ‘읽으며 배우기’ 방식에 대한 탐구보고서를 작성해제출했습니다. 또 미적분 시간에는 언어 관련 분야에서도 미적분이 활용될 수 있음을알고 이에 대해 탐구한 내용을 바탕으로 탐구 보고서를 작성했는데요. 이와 같이 거의모든 분야에서 어떻게든 영어와 관련지어 유의미한 탐구 활동을 하는 등의 노력을 했습니다."},{"q":"네 정말 열심히 했네요. 고등학생 때 이렇게 열심히 활동했는데 만약 우리 대학에 온다면또 대학에서는 어떻게 공부할지 학업계획이 있나요?","a":"네! 제가 숭실대학교 영어영문학과의 교육과정과 교과목들에 대해 찾아봤는데요. 입학후 비교적 저학년인 1,2학년 때까지는 ‘영국문학의 이해’, ‘미국문학의 이해’, ‘영어의 이해’,‘영어학의 기초와 응용’, ‘낭만주의 영시’ 등과 같은 과목들을 수강하며 영문학이나 영어학과같이 ‘영어’라는 언어와 관련하여 다양한 측면에서 저의 배경지식들을 차츰 쌓아나갈 계획입니다. 그리고 대학 들어가서 비교적 고학년인 3,4학년 때는 ‘영어 발음법’, ‘해석과 번역’,‘english debate and interview skills’ 등의 과목들을 수강하며 통역사가 되기위해 필요한역량들을 쌓아나갈 생각입니다. 또 중간중간에 스스로 시간을 내서 ‘itt 통번역자격증’과같이 통역사가 되기 위해 따놓으면 좋을 자격증들도 취득하며 졸업 후에 바로 훌륭한통역사로서 사회에 나아가고자 합니다."},{"q":"통역사가 되고자 하는 목표가 분명하네요. 그렇다면 이와 관련한 책도 읽어본 적이 있나요?","a":"네! 지금 당장 기억에 남는 책은 ‘샘 노리스’ 작가의 ‘영어 감정 표현 사전’이라는 책입니다.저는 이 책을 읽으면서 현지인이 아니라면 스스로는 파악할 수 없을 영단어 사이의 사소한뉘앙스 차이까지 이해할 수 있어서 정말 많은 도움을 받았습니다. 예를 들자면‘sorrow’, ‘grief’, ‘sadness’라는 이 세 단어는 사전에서는 모두 ‘슬픔’이라고만 의미가나와있는데요. 이중에서도 특히 ‘grief’라는 단어는 누군가의 죽음과 같이 상실과 결부된의미로서의 ‘슬픔’의 의미를 지니고 있어서 사색적 측면에서는 덜하지만 감정적 측면에서 더욱 격렬한 의미로의 슬픔을 나타낸다는 것을 알게 되었습니다. 이와 같이 제 스스로는 절대로 알지 못했을 단어 사이의 사소한 뉘앙스 차이까지도 이 책에서는 자세히 소개해주어서 읽으면서 많은 도움을 받았습니다."},{"q":"생기부를 보니까 노엄 촘스키라는 학자의 변형생성문법에 대해서 탐구했네요? 그리고 그의 학자로서의 신념으로부터 본인도 많은 영향을 받았다고 하는데요. 이런 말들을 보면 단순히 노엄 촘스키의 이론에 대해서만 탐구한 것이 아니라 인간으로서도 큰 영향을 받은 것 같아요. 이와 관련한 일화들이 궁금한데 말해줄래요?","a":"네! 우선 제가 노엄 촘스키의 변형생성문법에 대해서 정말 열심히 탐구를 했는데요. 사실 제 스스로 이해하기에는 내용이 좀 많이 어렵더라고요. 그래서 되게 막 깊이 있는 이해까지는 못한 것 같습니다! 그래도 제가 탐구한 부분에 대해서 설명을 드리자면, 노엄 촘스키의 변형생성문법은 문장구조의 복잡성을 이해하기 위한 장치로서의 역할을 한다고 합니다. 노엄 촘스키의 변형생성문법에서는 문장구조를 표면구조와 심층구조로 구분하는데요. 표면구조에서 같은 구조로 분류되는 문장조차도 심층구조에서 다르게 분류될 수 있음을 보이며 문장 구조의 복잡성에 대해 이해할 수 있도록 하는 이론이라고 합니다. 또 제가 노엄 촘스키로부터 저의 사고관 역시 많은 영향을 받았는데요. 노엄 촘스키가 처음 변형생성문법을 포함하여 자신만의 여러 이론들을 내세웠을 때는 학계로부터 엄청난 지지를 받았지만 시간이 지남에 따라 여러 비판들을 직면했다고 합니다. 이때 노엄 촘스키는 주눅들거나 학계에서 잊혀지는 그런 학자가 아니라 자신이 받은 비판을 철회시킬 수 있을 정도로 훨씬 더 뛰어난 논리를 보여주면서도 자신만의 입장은 고수하는 모습을 보여주었습니다. 저는 이런 모습을 보며 저 역시 때로는 신념을 지킬 줄 아는 것도 필요하다는 그런 깨달음을 얻게 되어서 학자로서 그가 보여준 모습에서 많은 영향을 받았습니다. 아까도 말씀드렸다시피 노엄 촘스키와 그의 변형생성문법에 대해서 정말 열심히 탐구했는데 제 스스로 이해하는 데에는 한계가 있었습니다. 그래서 제가 확실히 이해한 부분은 여기까지입니다!"},{"q":"네 정말 잘 들었습니다. 본인만 원한다면 대학 들어와서 노엄 촘스키의 변형 생성 문법에 대해서 자세히 공부할 수 있을 거니까 지금 이해 완전히 못했다고 너무 낙담하지 말아요. 이제 시간관계상 슬슬 끝내야 할 것 같은데 ‘진짜 나는 이 말을 이 면접에서 꼭 해야겠다’ 같이 마지막으로 정말 꼭 하고 싶은 말이 있나요?","a":"네 있습니다! 제가 숭실대학교 영어영문학과의 교육 목표에 대해서 찾아봤는데요. 우선 숭실대학교 영어영문학과는 어학 학습을 통해 학생들의 소통능력을 기르는 동시에 문학에 관한 깊이있는 연구를 통해 학생들로 하여금 문화적·비평적 사고를 가능하게 하여 우리 사회의 전문가를 양성하는 것을 교육 목표로 하고 있습니다. 또 숭실대학교 영어영문학과는 실용적인 영어학습의 기회를 제공하여 보다 전문적이고 실용적 인재를 양성하는 것을 교육 목표로 하고 있고요. 마지막으로 숭실대학교 영어영문학과는 영미문화권을 중심으로 하여 여러 영어권 사회의 역사 및 문화에 대한 깊이 있는 학습을 통해 세계를 바라보는 통찰력과 글로벌 마인드를 가진 인재를 양성하는 것을 목표로 한다는 것을 알게 되었습니다. 저는 이 숭실대학교 영어영문학과의 교육 목표를 찾아보며 영어영문학과가 설치되어 있는 학교들은 다양하지만 그중에서도 반드시 이 숭실대학교의 영어영문학과에 진학해야 한다는 생각을 더욱 굳히게 되었는데요. 왜냐하면 제가 영어영문학과를 진학한 이유가 통역사가 되고 싶어서, 그중에서도 영어권국가들의 문화적 특수성까지 잘 이해를 하고 이를 바탕으로 문화까지 통역해줄 수 있는 그런 통역사가 되고 싶어서 지원했다고 말씀드렸는데요. 숭실대학교 영어영문학과 같은 경우에는 교육목표에서부터 영미문화권을 중심으로 여러 영어권 사회의 역사 및 ‘문화’에 대한 깊이 있는 학습을 한다고 명시해두어서 제가 정말 배우고 싶은 것을 배울 수 있는 학교라고 느꼈기 때문입니다! 감사합니다.후배들을 위한 조언 1차 합격하고 나서 면접을 준비할 생각이라면 좋지 않은 것 같아요. 원서 쓰고 몇 달 후에 1차 발표났을 때 붙을 거라고 확신을 가지고 미리 몇 달 전부터 꾸준히 준비하는게 실제 면접 당일 날에 안 떨고 또 가장 완성도 있는 면접을 할 수 있는 것 같아요.즉 미리 준비하자!!또 너무나 당연하지만 생기부 진짜 계속 돌려보기! 그리고 생기부 내용에 나와있는 내용들을 바탕으로 추가 질문이 나올 수 있으니 본인 스스로도 어떤 추가질문이 나올 수 있을지 생각해보며 생기부에 나와있는 활동들에 대해 추가로 다양한 조사와 느낀 점 등에 대해서 깊이 생각해보면 좋아요. 그리고 대답은 이왕이면 사례 중심으로 만들어보는게 좋은 것 같아요. 자신의 직접적인 사례를 바탕으로 대답을 이끌어나가면 훨씬 더 호소력 있고 신뢰감도 증가하며 답변의 수준 자체가 엄청 향상되는 것 같아요! 파이팅 !!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"정보보호학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"","notes":"","qa":[{"q":"자기소개랑 숭실대학교 지원한 동기 말씀해주세요.","a":"저는 수학과 캄퓨터를 좋아하고, 정보보호학과의 인재상에 부합한다고 생각하여 지원한 면접번호 22번입니다."},{"q":"정보보안에 관심을 가지게 된 계기가 있나요?","a":"1학년 1학기 까지는 법조계 진로를 꿈꿨지만, 인공지능 캠프를 계기로 컴퓨터 분야에 새로 흥미를 느끼게 되었습니다."},{"q":"컴퓨터 분야에 흥미를 느끼고 어떻게 정보보안까지 관심을 가지게 되었죠?","a":"저의 수학과 컴퓨터에 대한 흥미와 능력을 잘 발휘할 수 있는 것이 정보보안이라고 생각했습니다."},{"q":"미분이 뭐고 활용사례로는 무엇이 있는지 설명해주세요.","a":"미분은 함수의 기울기를 구할 수 있는 것이고, 활용 사례로는 제 수학 탐구 내용에 있는 경사하강법이 있습니다. 데이터의 최적값을 찾을 때 주로 사용됩니다."},{"q":"세특을 보니 인공지능을 활용한 이미지 분석법이 있는데, 설명해주세요.","a":"인공지능과 피지컬 컴퓨팅이란 수업을 계기로 인공지능 이미지 분석법에 대해 관심을 가지게 되어 하게 된 활동이고, 스트라이드를 설정한 후 움직이며 이미지의 특징을 추출하는 방법으로 진행됩니다. 추출하는 법으로는 여러 가지가 있는데, 대표적으로 최댓값을 추출하는 방법이 있습니다. 그리고 나서는 제로 패딩이라는 과정을 거치는데, 이미지 특징 추출 중 손실 값을 최소화 하기 위해 수행하는 과정입니다."},{"q":"개발 경험에서 주로 어떤 언어를 사용했나요?","a":"수학 문제를 풀 때는 주로 파이썬을 사용했고, 유니티라는 프로그램을 활용할 땐 C#이라는 언어를 사용했습니다."},{"q":"수학에 흥미가 있다고 했는데, 정보보안에선 주로 무슨 분야의 수학이 쓰일까요?","a":"제가 학교에서 정보보안을 접할 기회가 별로 없다보니 정확하게 무슨 분야의 수학이 쓰이는지는 잘 모르겠습니다. 하지만 컴퓨터로는 주로 데이터를 분석하고 다루는 일을 하니 확률과 통계이지 않을까 싶습니다."},{"q":"정보보안에서 어떤 분야의 공부를 하고 싶나요?","a":"앞에서도 말씀드렸듯 아직 저는 정보보안에 대해 잘 모르지만, 제 적성을 고려한다면 연구 분야도 잘 맞지 않을까 싶습니다."},{"q":"마지막으로 하실 말씀 있으시면 해 주세요.","a":"재미있게 공부할 자신 있습니다. 감사합니다. 후배들을 위한 조언 서울은 차가 정말 많이 막힙니다. 네이버 지도로 봤을 땐 자가용으로 약 25분이 걸리는 것으로 나왔는데, 택시를 타보니 50분정도로 나왔습니다. (실시간 교통 정보도 고려하여 예상시간을 계산하는 어플을 사용해보세요. 예를 들면 티맵?) 하마터면 지각할 뻔했는데, 3분 남기고 간신히 입실했습니다. 1시간 정도 남기는 것을 목표로 여유롭게 도착하시는 걸 추천합니다. 그리고 올해는 학부모 대기실이 없었고 교내로 차량 진입이 어려워서 학부모님들 기다리시기에 좀 곤란했습니다. 이 점도 참고해주세요! 2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"컴퓨터학부","jeonhyeong":"학생부종합(SW 우수자)","method":"지원동기 → 수학(성적 & 탐구활동) → 동아리 활동→ 수학 세특활동 → 생명 세특활동 → 3학년 자율활동 → 미래계획-","notes":"","qa":[{"q":"컴퓨터 학부에 지원한 동기가 무엇인가요?","a":"컴퓨터와 IT분야에 관심이 생기고 나서부터, 인터넷 조사와 관련 독서를 통해 끊임없이 배우려고 노력하였습니다. 하지만 스스로 탐구하고 공부하면서 제가 갖고 있는 배경지식으로는 더 구체적이고 심화적인 전공지식을 얻는데 한계가 있다는 것을 알게 되었습니다. 그래서 컴퓨터공학부에 와서 저의 부족한 부분을 보완하고 다양한 컴퓨터 분야를 배우며 저를 성장시키고 싶었습니다. 숭실대를 선택한 이유는 숭실대가 전국에서 처음으로 컴퓨터학부를 받아들여서 관심이 생겼기 때문에 지원하게 되었습니다."},{"q":"수학이 중요한데 3학년 올라오면서 좀 힘들었던 것 같기도 하고, 확통이 중요한데 미이수에요. 이는 어떻게 할 계획인가요?","a":"전공 공부만 잘하면 된다는 안일한 오해를 했었습니다. 그래서 학업 성적이 좀 아쉬움으로 남아있습니다. 제가 확통을 이수하지 않았는데 이 부분을 보완하기 위해서 대학교 입학 전에 제가 부족한 과목들을 공부하고 또 대학교에 입학해서도 공부를 이어나가겠습니다. 만약 제가 어려운 것이 생기면 교수님들이나 선배님, 친구분들께 물어보고 협업하여 해결해 나가겠습니다."},{"q":"수학을 활용한 탐구활동이 있을까요?","a":"최적화 기법을 공부하면서 뉴턴 방법에 대해 공부하게 되었습니다. 뉴턴방법은 2차 미분을 이용한 것이고 1차 미분을 이용한 것이 경사하강법이라는 것을 알게 되었습니다. 1차 미분을 이용한 경사하강법은 감마라는 변수를 사용해서 step size를 정하는데 방향은 정확하지만 속도는 느립니다. 이를 속도를 더 빠르게 증가시킨 2차 미분과 같이 사용하면 해당 문제를 해결할 수 있습니다. 이를 공부하면서 R언어로 L-BFGS와 SLSQP를 구현하는것에 기반을 마련할 수 있었습니다."},{"q":"오 R언어를 활용했네요. R언어로 최적화 기법 구현할 때 따로 쓴 OOO?(무슨 공식같은 거 물어본듯) 있어요?","a":"R언어에 있는 rosenbrock 함수를 이용해서 최적화 공식을 대입하고 원하는 결과값을출력하는 방식으로 구현했습니다."},{"q":"2학년 동아리 때 빅데이터 탐구했다고 했는데 무엇을 중점으로 탐구한 건가요?","a":"빅데이터의 개념과 속도, 크기, 다양성의 특징, 머신러닝에 사용된다는 것을 탐구하였습니다. 빅데이터를 이용하여 머신러닝을 학습시킨다는 것을 알고 후에 회귀분석을 하는활동을 하게 되었습니다."},{"q":"DFS를 활용해서 한 활동에 대해 설명해주세요.","a":"탐색기법을 공부하면서 DFS라는 깊이 우선 탐색을 공부하게 되었습니다. DFS는 그래프 상에서 해당 분기를 전부 탐색하고 다음 분기로 넘어가서 탐색하는 방법을 사용합니다.저는 이러한 DFS를 사용해서 N-queen문제를 풀어봤습니다. 인접행렬을 사용해서 구현하였으며 재귀를 사용하면 스택을 쓰기 때문에 메모리적인 낭비(소비)가 있을 수 있고,시간적으로 오래걸릴 수 있다는 문제점이 있습니다. 이를 인접행렬과 스택을 통해 좀더 효율적이게 구현하였습니다."},{"q":"유전 알고리즘을 주제로 진행한 활동에 대해 간단하게 설명해보세요.","a":"최단 경로 알고리즘을 공부하면서 TSP 문제를 알게 되었습니다. TSP 문제는 모든 정점을순회하여 돌아오는 최단 경로를 구하는 문제기 때문에 재귀함수를 이용하면 O(n!)만큼의시간복잡도가 걸려 효율적이지 못하다는 것을 알게 되었습니다. 그래서 이를 학습의 메커니즘을사용하는 유전 알고리즘을 사용하면 좋을 것 같다는 생각이 들어 유전 알고리즘으로풀게 되었습니다. 처음에 정적변이를 사용했었습니다. 유전 알고리즘에서 지역 최적점에빠지지 않기 위해 변이를 사용하는데 변이 확률이 높으면 후반에 갈수록 정답에 맞게가고 있어도 오히려 더 시간이 걸린다는 것을 알게 되었습니다. 그래서 동적변이를 0.3정도의 확률로 놓고 다시 구현을 해봤습니다. 그 결과 정적변이는 2000세대를 생성했는데동적변이는 평균 200세대 정도로 생성한다는 것을 구할 수 있었습니다."},{"q":"메타버스로 양질의 교육 탐구한 경험이 있는데 이에 대한 후속 계획이 있을까요?","a":"주제가 메타버스로 양질의 교육을 하는 것이다 보니 저소득층이나 사회적으로 교육을받기 어려운 환경에 있는 사람들, 또한 항공기 조종같은 실제로 하기 어려운 상황을일반 사람들이 할 수 있도록 원격으로 집에서 사용하게 할 것입니다. 실재감을 통해실제 하는 것처럼 체험함으로써 도움을 줄 수 있을 것입니다."},{"q":"마지막으로 20초 정도 하고 싶은 말이나 앞으로의 계획 말해보세요.","a":"고등학교 생활을 하면서 다양한 분야를 공부했고 탐구하였습니다. 그 과정에서 느껴졌던저의 부족한 부분이 있는데 이를 숭실대학교에서 보완하고 ICPC같은 대회도 나가면서저를 성장시켜 훌륭한 아키텍터급 개발자가 되고 싶습니다. 지금까지 귀한 시간 내어제 말을 들어주셔서 감사합니다.후배들을 위한 조언 성적이 좀 안 좋더라도 생기부를 잘 채우면 충분히 좋은 학교 갈 수 있으니까 끝까지 포기하지말고 열심히 하세요!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"화학공학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"지원동기 → 지원동기에서 전공 관련 꼬리 질문 → 동아리 실험 질문 → 과학과제연구(진로과목), 고급화학 질문→ 수2 질문 → 생2 질문 → 마지막 할 말꼬리 질문이 많았고, 면접관 두 분 다 교수님이셨다. 어려운 개념이","notes":"생기부에 기술되어 있어 걱정했으나 이와 관련된 기초적인 지식들에 관해 질문해주셨다.","qa":[{"q":"효소와 촉매의 차이점은 무엇인가요?","a":"효소는 생명체 내에서 활성화에너지를 높이거나 낮추는 역할로 생명체 내의 온도, 압력에서 반응하나 촉매는 이보다 넓은 온도, 압력 조건에서 사용할 수 있습니다."},{"q":"슈뢰딩거, 나비에 스토크스 방정식에 미분 방정식이 쓰여있다고 나와있는데, 미분 방정식은 무엇인가요?","a":"미분방정식은 미분을 식으로 표현한 것입니다. 이 때 미분은 함수 혹은 상태의 순간적인 변화율의 값을 담은 개념입니다."},{"q":"플라스틱을 어떻게 만드나요?","a":"석유화학 공정을 통해 만듭니다."},{"q":"(과학과제연구 교과 관련 질문)질산포타슘 실험을 진행했는데, 깁스에너지, 엔트로피, 엔탈피의 정의에 대해 설명해보세요.","a":"깁스에너지는 특정 공정에서 반응이 자발적으로 일어날 지를 판단하는 척도로 쓰입니다. 깁스에너지는 엔탈피에서 절대온도와 엔트로피를 뺀 값으로, 이 때 엔탈피는 고유의 에너지이고 엔트로피는 무질서도를 나타냅니다."},{"q":"고급화학(공동교육과정) - 이성질체에 대해 설명해보세요.","a":"이성질체는 분자량은 같지만 다른 물리 혹은 화학적 성질을 띠는 것을 말합니다. 이성질체는 크게 구조 이성질체와 입체 이성질체로 나뉩니다. 구조 이성질체는 연결 상태에서 차이를 보이는 화합물이고, 입체 이성질체는 연결 배열에서 차이를 보이는 화합물입니다.후배들을 위한 조언 지원동기에서 플라스틱 관련 언급을 하였는데 ‘플라스틱에 관심이 많다고 생각되네요-> 플라스틱이 현재 어떻게 만들어지나요’와 같이 꼬리 질문이 나왔습니다. 지원동기로 준비한 내용들 중 꼬리 질문이 나올 수 있는 것들에 대해서는 기본적인 내용은 숙지하고 가는 것이 좋아보입니다. 또한 제 생기부에 고교 수준에서는 어려운 내용들(양자역학, 슈뢰딩거, 나비에-스토크스, 깁스에너지 등)이 있었는데 이에 대해서는 어려운 전공적인 질문보다 기초적인 개념을 이해했는지를 중점적으로 물어보시는 것 같아요. 기본적인 개념들에 대해 막히지 않고 답변할 수 있도록 연습해 보는 것이 좋을 것 같다고 생각합니다. 더불어 면접관들이 느끼시기에 충분하지 않은 답변을 했을 경우(답변이 너무 짧았거나 핵심적인 내용을 말하지 않은 경우) 꼬리 질문을 한다고 느꼈습니다. 꼬리 질문이 나온다면, 당황하지 않고 최대한 아는 것을 말하는 것이 중요하다고 생각합니다.면접실 외부에서 대기를 하다 들어가는데, 바깥과 안의 온도 차이가 심해서 저의 경우에는 안에서 목이 건조해 말이 잘 안나왔던 때가 있었습니다. 면접실 입실 전에 물 한 모금 마시고 가면 좋을 것 같아요.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"화학공학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"생기부 심화 내용 → 학과 인지 질문 → 물리 기초 질문 → 화학2 질문 → 성적 질문 → 영어 자기소개 → 마지막 멘트면접관은 2명이며 한 분은 친절하셨고 한 분은 날카로운 질문을 많이","notes":"하셨습니다. 큰 교실에서 대기하다가 면접실 바로 앞 책상으로 옮겨서대기한 뒤 바로 입실합니다.","qa":[{"q":"누구랑 오셨나요?","a":"어머니랑 왔습니다."},{"q":"뭐 타고 오셨어요?","a":"차 타고 왔습니다."},{"q":"NMR과 GC에 대해 공부하셨다는데, GC의 원리가 뭔가요?","a":"GC에는 고정상과 이동상이 있습니다. 미지시료가 이동상과 함께 이동하면서 고정상과반응하여 시료를 분석합니다. 고정상이 극성이고 미지 시료가 극성일 경우 속도가 상대적으로 느려지며 고정상이 극성이고 미지시료가 무극성일 경우 속도가 상대적으로 빨라집니다."},{"q":"화학공학과가 무엇을 하는 학과인지 아시나요?","a":"화학공학과에서는 물질의 생산을 촉진하며 효율적인 화학 공정과 이에 발생하는 화학반응을탐구하고 이에 대한 수득량을 높이는 데에 있다고 생각합니다."},{"q":"뉴턴의 물리법칙 3개를 설명해주세요.","a":"뉴턴의 물리법칙 중 관성의 법칙은 질량에 따라 본래 가지고 있는 힘을 유지하려는 성질이며 두 번째로는 보편적으로 잘 알려진 F=ma의 공식으로 가속도에 관련된 식입니다.마지막으로 작용반작용으로 대상이 가한 힘은 힘을 받는 쪽에서도 힘을 가한다는 것을 의미합니다."},{"q":"화학에서 몰농도와 몰랄농도의 차이가 무엇인가요?","a":"몰농도는 부피와 몰수에 관한 것이고 몰랄농도는 몰수에 관한 것이라고 생각합니다."},{"q":"몰랄농도의 단위가 무엇인지 아시나요?","a":"몰랄농도는 g을 사용하는 것으로 알고 있습니다."},{"q":"그렇다면 차이는 뭘까요?","a":"몰농도는 수용액에서만 쓰일 수 있지만 몰랄농도의 경우 질량을 알면 측정이 가능하므로 수용액 외에서도 사용이 가능하다고 생각합니다."},{"q":"2학년 2학기와 3학년 성적이 떨어진 이유가 무엇인가요?","a":"수강자 수가 과목별로 감소하여 생긴 것으로 생각합니다. 하지만 3학년 2학기 때 다시 성적을 향상시킨 경험이 있습니다."},{"q":"영어 성적이 괜찮은데 혹시 영어로 자기소개 할 수 있나요?","a":"My name is... 다시하겠습니다. My hobby is singing a song and playing a piano. My favorite song is 임창정’s 내가 저지른 사랑."},{"q":"마지막으로 하고싶은 말을 해주세요.","a":"학급회장을 통해 기른 리더십과 동아리 실험 진행을 하며 기를 협력, 의사소통 능력, 문제해결 능력을 토대로 숭실대학교 화학공학과에 입학하여 저의 꿈을 이뤄나가고 싶습니다. 감사합니다.후배들을 위한 조언 학과가 화학공학과인 만큼, 화학과 물리에 대한 기초지식을 중요하게 여기는 것 같았고 인재상에 기재되어있는 역량들도 물어봅니다. 특히, 글로벌 역량의 경우 영어로 자기소개를 시키는 등 인재상도 한 번씩은 꼭 물어보는 것 같았습니다. 몰농도와 몰랄농도에서 관한 대답을 하는데에 살짝 힘든 점도 있었지만 대답을 못한다고 해서 넘어가는 것이 아니라 그것에 대한 힌트로 단위를 물어보는 등 몇 번의 기회를 더 주셨습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"회계학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"지원동기 → 생기부 관련 활동 질문전공 관련질문 → 합격했을 때의 학습 계획 → 마지막 할 말","notes":"신분증 수험표 미리 준비하기","qa":[{"q":"자기소개와 지원동기를 말씀해 주시겠습니까?","a":"1학년 때 진로와 직업 팀 프로젝트를 하다가 처음 회계사라는 직업을 알게 되었다. 이후 3학년 대우조선 분식회계 사례 탐구에서 나라면 경영인과 투자자의 이해관계를 모두 고려할 수 있는 유능한 회계사가 되고 싶어서 이 전공을 선택하게 되었다."},{"q":"재무제표 분석 관련 활동이 많은데 어떤 식으로 진행했는지 설명해주세요.","a":"다트라는 사이트로 했다. 재무제표의 여러 재무 요소 정보가 드러난 사이트인데 들어가서 기업의 재무 상태를 확인하고, 이해할 수 있었다."},{"q":"그렇다면 대우조선의 사례의 경우 총 제조원가가 부풀려졌다고 했는데, 그 사이트(다트)를 통해 그 단서를 도출할 수 있었나요?","a":"네 그렇습니다."},{"q":"합격하게 된다면 숭실대학교에서의 학업계획에 대해 설명해주세요.","a":"숭실대 회계사 고시반인 현의제에서 공부하고 싶다. 숭실대는 회계학과가 독립적으로 회계 양성 트랙이 있어 회계사의 꿈을 함양할 수 있다고 들었다. 그곳에 들어가 전문적으로 학습하고 싶다."},{"q":"회계학은 무슨 교과와 연관되어 있다고 생각하나요?","a":"사람을 상대해야 하는 직업이니까 심리학과 관련있지 않을까 생각합니다. 결국 회계사도 인식하고 판단하여 그것을 고객과 소통하는 직업이기에 심리학과 연관이 있지 않나 생각합니다."},{"q":"회계 관련 활동에서 비재무지표를 회계로 산정했는데, 어떻게 산정했나요?","a":"탄소로 예를 들면 그거를 수치로 산정해서 지표로 만든다."},{"q":"마지막으로 하고싶은 말이 있나요?","a":"고등학교 시절이 떠오릅니다. 그 결실이 숭실대 회계학과라면 좋겠습니다.후배들을 위한 조언 일단 지금 이 후기집을 보고있는 고3이라면 면접 준비로 인해 많이 불안할텐데 힘내라고 말하고 싶다.학교마다 면접 진행과 질문들이 다르겠지만, 일반적으로 생기부 내용을 큰 틀로 여쭤보는 경우가많으니, 큰 틀에서 답변을 준비한다면 괜찮을 듯 합니다!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"숭실대학교","dept":"국어국문학과","jeonhyeong":"학생부종합(고른기회)","method":"대기실 입실 → 신분증 확인 → 대기 → 면접장 앞에서 대기 → 면접 → 퇴실-수험표와 신분증 준비.","notes":"-대기실 입실 시 휴대폰 제출, 노트북 등 부피가 큰 전자기기는 전원 꺼서 가방에 넣어둠.-대기실 입실 후 종이로 된 서류만 읽을 수 있음.","qa":[{"q":"생기부를 보니까 뭐 전교 부회장, 동아리장, 실장 등등 많은 임원 활동을 했는데, 활동했던 것중에서 가장 기억에 남는 거 있나요?","a":"저는 전교 부회장이었을 당시 진행했던, 후배들에게 선택과목을 알려주었던 활동을 말씀드리고 싶습니다. 저는 1학년 당시 선택과목에 대한 고민이 많았기 때문에 같은 고민을 가지고 있는 후배들을 도와주고자 해당 프로그램을 기획했고, 지원자들과 함께 담당 선생님께 계획을 말씀드렸으나 반려 당하였습니다. 하지만 저는 프로그램에 대한 확신을 가지고 지원자들을 독려하여 직접 프로그램을 실행하는 것처럼 모의 진행을 선생님께 보여드렸고, 마침내 허가를 받아내어 후배들에게 선택과목에 대한 설명을 충분히 진행할 수 있었습니다. 후배들에게 직접적인 도움을 주었다는 뿌듯함이 느껴져 가장 인상 깊었던 활동인 것 같습니다."},{"q":"네, 그리고 또 생기부에 보니까 공감 능력이 뛰어나다고 적혀있어요. 그리고 뭐 전교부회장 활동하면서 유기견이나 유기묘에 대해서도 관심을 가지고 있는 것 같은데... 주변 빈곤 국가나 유기견, 그런 것에도 관심이 있나요?","a":"네, 특히 유기동물에 대해 관심이 있어 유기견, 유기묘 관련 학생회 사업을 진행했었습니다. 유기견과 유기묘와 관련하여 디자인을 공모받고 선정된 디자인으로 스마트톡을 만들어 학생들에게 판매하고, 그로 얻은 수익을 기부했습니다. 또한 저희 학교에도 실제로 유기묘 세 마리가 있고, 학생들이 간식을 주면서 챙겨주기 때문에 유기동물에 대한 관심이 많습니다."},{"q":"만약 그 고양이들이 엄청나게 번식을 해서 감당할 수 없을 정도로 수가 많아지면 어떡하죠?","a":"어... (고민)"},{"q":"주민들 민원 들어오고 그러면 어떡하나요?","a":"만약 개체 수가 많아진다면 학생회 sns 등을 통하여 분양받을 사람들을 모집할 것 같습니다. 지금도 학교에서 많은 학생들이 고양이들을 돌봐주고 있기 때문에 분양받을 학생이 많을 것이라고 생각합니다."},{"q":"만약 분양 가서도 엄청나게 번식하며 어떡해요?","a":"아... (고민)"},{"q":"(웃으며)네, 여기까지 생각해볼 일이 사실 없죠. 다음 질문 할게요.","a":"네."},{"q":"학생 성적을 보면 국어 같은 경우는 성적이 계속 좋고, 영어는 학년이 갈수록 등급이 떨어졌어요. 이유가 뭘까요?","a":"네, 저에게는 영어 과목이 특히나 어려웠습니다. 한국어와는 다른 문법과 높은 난이도의 어휘들, 학년이 올라갈수록 높은 독해력이 요구되다 보니 해당 과목 성적이 떨어진 것 같습니다."},{"q":"네, 성적이 낮다고 뭐라고 한 건 아니고, 그냥 그런 걸 극복한 사례가 있나 해서 물어본 거예요.","a":"아, 네."},{"q":"학생 보니까 책도 정말 많이 읽었어요, 거의 60권 정도를 읽었는데, 그중에서 ‘소크라테스의 변명’이라는 책을 읽었네요. 이거 되게 어려운 책인데. 무슨 내용인지 말해줄 수 있나요?","a":"네, 수행평가를 위해 발췌해서 읽었기 때문에 인상 깊었던 부분을 말씀드리겠습니다. 이 책은 소크라테스가 산파술로 사람들에게 혼란을 제공했다는 점에서 재판이 열리고, 그의 내용이 담겨 있습니다. 그중에서도 소크라테스가 최후 변론에서 본인의 의지를 굽히지 않고, 변론한 내용을 후회하지 않는다고 말한 부분이 가장 인상 깊었습니다."},{"q":"네, 이제 시간이 다 돼서. 마지막으로 하고 싶은 말 있으면 해보세요.","a":"네. 저는 나태주 시인의 ‘혼자서’라는 시를 읽으며 외로운 상황을 많이 견뎌냈습니다. 이렇듯 글과 그로 이루어진 문학에는 사람의 마음을 돌볼 수 있는 힘이 있다고 생각합니다. 숭실대학교 국어국문학과에 입학하여 국어학과 국문학을 배우며 국어의 본질에 대해 배우고, 사람에게 도움을 주는 문학 작품을 널리 알릴 수 있다고 확신합니다. 지금까지 제 이야기를 들어주신 것에 감사드리며, 꼭 입학하여 두 분을 다시 뵙고 싶습니다. 감사합니다.후배들을 위한 조언 ∙두괄식으로 말하는 것 계속해서 연습하세요. 시간에 쫓겨서 하고 싶은 말을 장황하게 늘어놓는 것보다 조금 생각할 시간을 가지더라도 머릿속에서 말할 것을 정리한 후에 깔끔하게 두괄식으로 답변한다면 훨씬 질 좋은 답변을 내놓을 수 있을 겁니다.∙저 같은 경우는 예상 질문이 하나밖에 나오지 않았어요. 생각지도 못한 부분에서 대답을 요구할 수 있으니 본인 생기부에 대한 내용을 꼼꼼하게 보는 것이 중요할 것 같습니다.∙압박 면접이 이런 식으로 진행되는 줄 몰랐는데, 생각보다 엄청난 창의력과 순발력이 요구됩니다. 다양한 질문에 대한 답변을 준비해야 될 것 같습니다.∙면접관님이 두 분이셨는데 두 분 다 정말 친절하시고 답변에 계속 고개 끄덕거려주시고, 눈 맞춰주시면서 웃어주셨어요. 정말 생각보다 떨리지 않았고 편하게 이야기할 수 있었습니다. 그래도 평소에 긴장 많이 하시는 분은 청심환 드시는 것을 추천합니다.∙들어갈 때 자신 있게 인사하는 것, 나올 때 자세 유지하는 것은 기본입니다. 대답할 때도 자신 있게 대답하고, 말끝을 흐리지 않는 게 정말 중요한 것 같습니다.∙본인 어필을 많이 하세요. 꼭 이 학교의, 이 학과에 진학을 해야만 한다는 자신감을 어투 속에 내재시키세요.∙전공 관련 질문이 아니더라도 최대한 열심히, 좋은 답변을 생각해내세요. 생기부 속 사소한 단어 하나에 관련한 질문을 받을 수도 있습니다.∙기 죽지 마세요. 압박 면접을 진행한다는 것은 본인이 더 알아가고 싶은 지원자라는 것일 수 있습니다!2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"국제법무학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"옆 강의실에서 대기하다가 수험범호 부르면 앞에서 대기하다가 입장","notes":"","qa":[{"q":"떨리겠지만 떨지말고 차분히 말해보자~","a":"넵"},{"q":"자신의 진로량 연관해서 이 학과에 와야하는 이유?","a":"저는 3년동안 소외계층을 위해 활동하는 국제인권변호인이 되기 위해 노력해왔습니다. 다른 학과와 달리 숭실대학교 국제법무학과는 영미법과 국제법, 국내법을 모두 배울 수 있는 학과라고 알고있습니다. 이러한 학과의 커리큘럼은 국제인권변호사를 꿈꾸는 저에게 가장 잘 맞는다고 생각해 지원하게 되었습니다."},{"q":"자소서 1번에 위안부 문제를 언급했는데 위안부 문제가 왜 잘못되었다고 생각하나?","a":"일단 위안부 문제는 상대방의 동의없이 강제적으로 그들을 끌고가 성노예로 대했다는 사실이 가장 큰 잘못이라고 생각합니다. 또한 그 일이 있고난 후 능동적인 책임 인정이나 진솔한 사과와 같은 행동이 이뤄지지 않았기에 아직까지 위안부 문제가 해결되지 않고 있다고 생각합니다."},{"q":"그러면 위안부 문제를 피해자와의 상의없이 정부가 해결하는 거에 대해 어떻게 생각하냐?","a":"잘못되었다고 생각은 하나 어쩔 수 없는 상황이라고 생각합니다. 일단 국제사회는 다양한 이해관계가 얽혀있습니다. 이런 상황에서 국제적인 압박이나 다른 문제와의 상호 연결된 이유로 인해 불가피한 상황이었다고 생각합니다. 하지만 이후 할머니들에게 충분한 배상과 사과와 같은 향후 조치가 취해졌어야 한다고는 생각합니다."},{"q":"International Organization % Treaty 수업을 듣고 싶다고 했는데 다른 수업 듣고싶은 거 있니?","a":"저는 국제법 뿐만 아니라 국내법에도 관심이 있기 때문에 국내법 수업을 적극적으로 수강하고 싶습니다."},{"q":"언론사 로직도 언급했는데 왜 하고싶은 거니?","a":"언론사 로직은 국제법무학과 뿐만 아니라 법과대학 전체 언론사로 알고있습니다. 그 만큼 뿌리 깊은 역사를 가지고 있는 것으로 알고 있는데요, 다양한 법적 지식을 사람들에게 알리고 법률지식이 부족한 소외계층 분들게 법률자문서비스를 구하는 등 실무경험을 쌓을 수 있는 활동이라고 생각해 꼭 가입하고 싶습니다."},{"q":"좋아하는 과목과 잘하는 과목은?","a":"저는 영어과목을 좋아합니다. 비록 영어 내신 성적이 그리 좋은 편은 아니지만 3년동안 영어과목에 지속적인 관심을 가지고 활동해왔습니다. 영어경시대회나 영어독후감쓰기 대회에서 수상을 하기도 했습니다."},{"q":"마지막 하고싶은 말?","a":"일단 너무 긴장해서 저의 역량을 100% 다 보여드리지 못한 거 같아 매우 아쉽습니다. 하지만 숭실대학교에 입학하게 된다면 최선을 다하는 모습 보여드리겠습니다. 또한 숭실대학교의 진리와 봉사라는 슬로건 아래 함꼐 성장하고 싶습니다. 감사합니다. 후배들을 위한 조언 2023 대입 면접후기"}],"result":"추가합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"글로벌통상학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"대기실에 모두 집합 후 가번호 순서대로 인솔자와 함께 이동합니다. 면접은 학생부기반+자기소개서 기반 질문이 주가 되었으며 꼬리질문이 있습니다. 면접은 10분 내외로 진행되었습니다.가번호와 명찰을 착용해야 하는 면접이었습니다. 명찰이 수험번호에","notes":"따라 부여되는데 면접 시에는 가번호가 보이는 면만 보여야 합니다. 또한 교수님 2분이 계셨고 유의사항(출신고교, 사회적 지위 등)에 대해 주의해주세요","qa":[{"q":"자기소개 해주세요.","a":"한국의 통상문제 해결에 이바지하고 세계 빈곤 문제 해결에 앞장서는 국제통상전문가로 성장하고 싶습니다. 중남미 국가들의 빈곤과, 무역을 통한 한국의 급진적 성장을 탐구하며 빈곤 극복 방안으로서의 국제통상의 가치를 인식했습니다. 나아가 한국 수출 다변화의 교역국으로의 중남미 시장 가치를 탐구하며 중남미와 같은 교역국과 한국의 동시 성장을 목표로 통상 전략을 개발하고 싶다는 꿈을 가지게 되어 글로벌통상학과에 지원하였습니다."},{"q":"중남미에 대해 특별히 관심을 가지게 된 계기가 있나요?","a":"저는 3년간 스페인어와 스페인어권 문화에 대해 배운 것이 중남미에 대한 관심으로 이어졌고 현재 중남미 시장이 많은 인구의 소비시장과 이커머스 시장이 성장하고 있는 점이 결정적 요인으로 작용했습니다."},{"q":"중남미로 왜 진출해야 한다고 생각해요?","a":"중남미의 풍부한 자원과 산업의 성장이 우리나라의 제조업과 수출의 상호 보완관계에 있기 때문입니다."},{"q":"요즘 이슈에 대한 관심이 필요하다고 생각하는데 어떤게 있다고 생각하시나요?","a":"다른 많은 이슈들이 있지만 미국의 금리 인상 이슈가 중요하다고 생각합니다. 보통 미국 금리가 인상될 경우 환율이 올라 수출이 많아지게 되지만 정작 총 수출액은 금리 변동 전에 비해 더 낮아졌습니다. 그 원인을 찾아보니 우리나라의 미국에 대한 자원 의존도가 높았고 이러한 점이 악재로 작용하였습니다. 따라서 더 많은 국가와의 통상으로 원자재 확보 국가를 늘려야 한다고 생각합니다."},{"q":"자기소개서를 보니 무역이 빈곤을 해결할 수 있다고 생각하시는데 무역이 빈곤 해결의 방안이라면 왜 개도국은 무역을 피하려고 할까요?","a":"여러 이유들이 있겠지만 개발도상국은 보통 1차 산업에 강점이 있습니다. 하지만 1차 산업에 특화되어있을 경우 궁핍화 성장이 일어날 수 있기 때문에 이를 고려하여 무역을 피하려 하는 것 같습니다."},{"q":"폴 크루그먼의 지리경제학을 읽었다고 했는데 어떤 내용인가요?","a":"핵심부와 주변부가 생기는 이유에 대해서 설명하는데 규모의 경제와 고정비용이 전제가 됩니다. 주변부에 거주하는 사람들은 핵심부의 사람들에 비해 다양성의 이익을 누릴 수 없고 규모의 경제의 정도가 낮기 때문에 핵심부로 이주할 유인을 얻게 됩니다."},{"q":"내시균형에 대해 설명해보세요.","a":"3학년 심리학 시간에 관련 탐구를 진행했는데요 협동을 하면 모두에게 이익이 됨에도 배반을 하는 경우 경쟁자의 대응에 따라 합리적 선택을 했을 때 서로가 자신의 선택을 더 바꿀 필요를 느끼지 않는 상태에 도달하게 된다는 이론으로 알고 있습니다."},{"q":"”자유로서의 발전“을 읽으셨네요, 한 문장으로 정리해볼까요?","a":"”자유는 부자유를 제거함으로 얻을 수 있는데 이는 사람들의 기본적 권리를 보장해줄 수 있는 인프라나 사회 제도가 선행되고 이후에 시장 경제에 참여해야 한다”입니다.후배들을 위한 조언 현재 이슈와 자신이 읽은 책, 이론에 대해 확실하게 알아두시면 좋을 것 같습니다. 저는 답변에 대해 자신감이 조금 부족했는데 자신의 내용에 대해 확실히 파악한다면 떨려도 잘 말할 수 있다고 생각합니다. 부디 힘내시길 바랍니다!2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"독어독문학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"-면접관: 2명 / 학생: 1명-면접 대기실->면접실 앞 대기->면접 후 개별 퇴실-면접 시간: 10분","notes":"-전자기기 수거-수험표 및 신분증 필수 지참","qa":[{"q":"(남) 아이고 반갑습니다. 일단 면접 유의사항부터 말씀드리고 시작하겠습니다. 우선 면접에 참여해주셔서 감사합니다. 우리 학교는 기본적인 확인 면접이니 긴장하지 말고 최대한 간결하게 대답해주시면 감사하겠습니다. 시작할까요?","a":"네!"},{"q":"(남) 3학년 1학기 수상을 보니까 독일어 에세이 쓰기 대회에서 우수상을 받았는데, 이게 독일어 영어과 학생 65명이 수상을 했다고 뜨는데, 그러면 영어과 학생들도 같이 본 거예요?","a":"학교의 특성상 정확히는 말씀드리기 어렵지만, 같이 보진 않았습니다."},{"q":"(남) 그럼 영어과 대회도 따로 있어요?","a":"네 그렇습니다."},{"q":"(남) 창의적 체험 활동에서 가장 기억에 남는 활동이 무엇인가요?","a":"저는 1학년 사회 참여 동아리에서 미디어 리터러시 교육을 주제로 탐구하고 실질적인 정책으로 제안했던 것이 가장 기억에 남는 것 같습니다. 조사하는 과정에서 독일이 미디어 리터러시 교육뿐만 아니라 미디어 법체계에서도 전 세계적으로 인정받고 있다는 것을 알게 되면서 미디어 리터러시 교육 전문가라는 꿈을 가지게 되었던 것 같습니다. 청소년 참여 포털에서 독일의 사례를 통해 한국도 미디어 필수 교육 과정을 도입해야 한다는 목소리를 내고 직접 정책을 제안하면서 비록 실질적인 정책으로 이어지는 데에는 어려움이 있었지만, 제가 평소 가지고 있던 생각을 단순히 생각에서 그치는 것이 아닌 직접 정책을 제안해볼 수 있었던 뜻깊은 기회였다고 생각합니다."},{"q":"(남) 교과 과목 외에 기억에 남는 독일어 관련 활동은?","a":"저는 독일어권 심화 탐구 동아리에서 했던 모의의회 활동이 가장 기억에 남는 것 같습니다. 모의의회를 준비하는 과정에서 독일어로 대본을 작성하면서 많은 어려움이 있었던 거로 기억하고 있습니다. 저는 단순히 파파고나 구글 번역기로 한국어 대본을 독일어로 해석하는 것이 아닌 직접 독일의 DUDEN사전을 활용하여 해석하고 작문하면서 독일어 실력이 크게 향상할 수 있었던 것 같습니다."},{"q":"(남) 여기 보니까 교외 봉사활동이 상당히 많네요? 본인에게 가장 소중했던 봉사 경험이 있다면 말씀해주세요.","a":"제가 가장 소중했다고 생각하는 봉사활동은 3년 동안 꾸준히 참여했던 환경정화 봉사활동입니다. 저는 평소 학교에서 환경 문제에 대해 문제점과 해결방안은 제시하는데 그에 대한 실천이 간과되고 있다는 점이 매우 아쉽다고 생각하여 직접 제가 사는 동네를 돌며 쓰레기를 줍고 분리수거 방법을 배워나갔던 것 같습니다. 이러한 경험을 살려 숭실대학교에 진학하여 환경 봉사 소모임을 만들어 환경 보호를 위한 노력을 이어나가고 싶습니다."},{"q":"(여) 혹시 읽었던 문학책 중에 가장 기억에 남는 책이 뭐예요?","a":"제가 가장 기억에 남는 책은 하인리히 뵐의 카타리나 블룸의 잃어버린 명예라는 책입니다. 이 책에서는 주인공 카타리나가 언론이라는 하나의 권력에 의해 어떻게 삶이 망가지는지에 대한 이야기를 담고 있습니다. 제가 가장 기억에 남는 구절은 ‘계란 케이크가 수류탄 같은 것을 의미하진 않는지, 딸기와 함께 곁들인 아이스크림이 폭탄을 의미하지는 않는지 세심한 주의를 기울여야 하지만’이었습니다. 이 구절을 통해 허위 보도를 한 기자도 문제지만, 사람들이 왜 이러한 기사에 관해 의심하지 못할까에 대한 문제의식을 느끼게 되었습니다. 따라서 대중들이 올바르게 뉴스를 소비하려면 미디어 리터러시 능력을 키워야 한다고 생각하여 제가 미디어 리터러시 교육 전문가가 된다면 이러한 사회 문제를 극복해나가야겠다는 목표를 가지게 해줬던 책이라고 생각합니다."},{"q":"(여) 교과 성적을 보니까 아주 성적이 많이 상승했어요. 고생 많이 한 것 같네요. ㅎㅎ 혹시 그 이유가 있을까요?","a":"1학년 때는 막연히 기자라는 꿈만 가지고 있었다면 2학년 때부터는 독일의 선진 사례를 바탕으로 한 미디어 리터러시 교육 전문가라는 구체적인 목표를 설정하게 되었던 것 같습니다. 이러한 확고한 목표를 설정했던 것이 제가 꿈을 이루기 위해 무엇을 해야 하고 어느 곳에 시간을 쏟아야 하는지 깨닫게 해주었던 것 같습니다. 그래서 교내 활동뿐만 아니라 공부도 최선을 다하면서 최대한 시간을 효율적으로 활용하려고 했던 것 같습니다."},{"q":"(여) 말씀 들어보니까 꿈이 바뀐 것 같은데 기자에서 미디어 리터러시 교육 전문가로 꿈이 바뀐 이유가 뭔가요?","a":"저는 카타리나 블룸의 잃어버린 명예라는 책을 보고 미디어 리터러시 교육 전문가라는 꿈을 가지게 되었습니다. 처음에는 제가 기자가 되어 현재 언론이 가진 문제점을 해결해나가야 한다고 생각했습니다. 하지만 이 책을 읽으면서 “언론의 구조적 문제를 해결하기 위해서는 기자가 되는 것도 좋지만 언론인과 뉴스 소비자들에게 뉴스를 올바르게 생산하고 소비하는 방법을 알려주는 역할이 필요하지 않을까?”라는 생각을 가지게 되었습니다."},{"q":"(여) 근데 미디어 리터러시 교육 전문가라는 직업이 한국에서 학원 선생님이나 교사처럼 잘 알려진 직업이 아니잖아요? 혹시 미디어 리터러시 교육 전문가가 어떻게 되는 것인지 말씀해주실 수 있나요?","a":"면접관님이 말씀하신 것처럼 미디어 리터러시 교육 전문가는 교사처럼 정해진 꿈이 아닌 제가 가진 목표입니다. 그렇기 때문에 제가 가진 진로계획에 대해 말씀드리자면, 저는 한국 언론 진흥 재단에서 미디어 교류 사업을 담당하면서 독일과 한국의 국제 교류를 활성화해 독일의 미디어 교육 선진 사례를 수용하여 한국의 바람직한 언론 문화를 조성하고자 하는 목표를 가지고 있습니다."},{"q":"(남) 독일과 한국 속담 비슷한 게 뭐가 있는지 말해볼래요?","a":"속담을 말씀드리게 되면 독일어를 언급할 수도 있는데 괜찮을까요?(외국어 금지 면접)"},{"q":"(남) 아 그러면 한국말로 돌려서 설명해주세요.","a":"네. 독일에는 아침에 일찍 일어나는 사람이 입에 금을 문다는 속담이 있다고 알고 있습니다. 이 속담이 한국의 아침에 일찍 일어나는 새가 벌레를 잡아 먹는다처럼 부지런한 마음가짐으로 일하라는 조언이 담긴 속담이 매우 유사하다고 생각합니다."},{"q":"(남) 독일과 한국의 다른 식문화 설명해볼래요?","a":"한국에서는 라면과 같은 면 종류를 먹을 때 후루룩 소리를 내는 것이 종종 복스럽고 맛있게 먹는 것으로 여겨지는 반면, 독일에서는 면을 먹을 때 소리를 내는 것이 매우 예의 없는 행동으로 여겨진다는 점에서 차이가 있다고 생각합니다."},{"q":"(남) 벌써 10분이 다 지났네요. 혹시 이제 마지막으로 하고 싶은 날 있으면 다 해볼까요?","a":"먼저 이렇게 숭실대학교 독어독문학과에서 면접 볼 기회를 주신 면접관분들께 진심으로 감사하다는 말씀드리고 싶습니다. 독일에서는 한 분야의 장인을 마이스터라고 부른다고 알고 있습니다. 저도 숭실대학교 독어독문학과에서 미디어 리터러시 교육 마이스터로서 한국과 독일 두 나라를 연결하는 교량 역할을 담당하는 인재로 성장해나가고 싶습니다. 감사합니다!"},{"q":"(남) 아이고 수고했네요~","a":""},{"q":"(여) 집에 조심히 가요~후배들을 위한 조언 제가 본 면접 중에 가장 면접관분들이 생기부를 정독하신 티가 났습니다. 면접관 두 분과 저의 거리가 책상 하나 정도로 매우 가까웠던 것 같습니다. 면접관 두 분 다 교수님이셨고 매우 잘 웃어주시고 분위기도 좋았습니다. 작년에는 자소서에서 많이 나왔다고 했는데, 올해는 생기부에서 많이 나온 것 같습니다. 매년 다른 것 같으니 뭐든 꼼꼼히 준비하시는 게 최고인 것 같습니다. 대기 시간이 다른 학교보다 길고 추우니 따뜻하게 입고 가시는 것을 추천해 드립니다. 기독교 학교라 그런지 앞에 사이비들이 많습니다. 번호랑 이름 물어봐도 절대 알려주지 마시길. 2023 대입 면접후기","a":""}],"result":"불합격","resultNote":"예비 4번","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"컴퓨터학부","jeonhyeong":"학생부종합(고른기회1. 8시 30분까지 면접 대기 장소에 모여 면접 번호 순으로 자리에 앉음 (내 면접에는 SW인재전형과 고른기회전형이 같이 모여있었음))","method":"2. 휴대폰을 걷음과 동시에 공지사항 공지와 수험표 및 본인 확인 진행3. 면접순서가 되면 모든 짐을 챙겨 복도에 설치되어있는 의자에 앉아있음. 4. 이후에 바로 앞 면접자가 끝나면 면접을 보러 들어감. 5. 전공교수님 한분과 면접관님 한분이 둘이서 면접을 보는 같음.6. 이후 면접이 끝나면 휴대폰을 받고 집으로 귀가","notes":"신분증, 수험표를 챙겨야하며 휴대폰 외 전기제품들은 제출해야함","qa":[{"q":"간단한 자기소개 부탁드립니다.","a":"동적 계획법을 토대로 이 학과에 지원하게 됨"},{"q":"파이썬이 객체지향프로그램이라고 하는데 객체 지향 프로그램이 무엇인가요?","a":"잘 모르겠습니다."},{"q":"부실장을 하면서 의견 수립하는데 갈등을 어떻게 해결했는지?","a":"각 의견들을 들어보면서 각 의견들의 장단점들을 파악하고 각 의견들의 장점들을 모두 아우를수 있는 또한 단점들을 최대한 보완할 수 있는 의견을 찾아내어 조원들을 설득시키려 했던 것 같습니다."},{"q":"일상생활에 불편한 점들을 프로그래밍으로 어떻게 해결할 수 있을까요?","a":"예를들어 버스를 탈때 버스를 놓쳐서 다음 버스를 타게 되는 경우에 프로그램을 통해 예약시스템을 만들어 해결할 수 있을것 같습니다"},{"q":"(꼬리질문) 버스와 스케쥴 조정에 관한 문제는 어떻게 최적화 할수 있을까요?","a":"사용자의 스케쥴을 프로그램에 입력하면 그 스케쥴에 맞는 가장 빠른 버스 시간을 알려주고 또한 사람이 많은 버스에는 그만큼 많은 사람들이 타고 내리면서 시간이 지체되는데 그러한 부분들까지 고려해서 최적화하면 될것 같습니다"},{"q":"고급수학은 성취도가 높지만 미적분에 어려움을 느낀 것 같아요. 어떤 어려움과 어떻게 극복 하였나요?","a":"킬러 문제에 어려움을 느꼈습니다 그 킬러문제가 어려운 이유를 생각해 봤더니 그 문제를 접근하는 과정이 어려웠던것 같습니다 그래서 이를 해결하기 위해 수학적인 논리력을 키우려고 많이 노력하였습니다. 예를들어 근을 구할때에도 접근방식을 달리하면서 인수분해를 이용해 문제를 풀다가 안되면 다른 접근 방식인 근의 공식으로 문제를 풀려고 노력하였습니다"},{"q":"과학에 관심이 많은데 과학이 아니라 컴공을 지원한 이유를 아까 한 얘기 말고 다른것으로 얘기해 주세요.","a":"프로그래밍을 공부하다가 과학 분야가 코딩에 많이 사용되었는데 이때 물리적인 부분을 코딩하기 위해 관련 내용을 공부했습니다. 물리적인 코딩을 위해 물리 개념에 대해 먼저 탐구하고 분석하였는데 이 과정에서 과학에 관심이 생겼던것 같습니다. 그래서 컴공을 지원하게 되었습니다."},{"q":"마지막으로 하고 싶은 말 있으신가요?","a":"2학년에 여러 프로그램을 코딩하면서 프로그래밍에 관심이 생겼고 이 관심은 인공지능코딩에도 이어졌습니다. 인공지능 코딩을 위한 간단한 지식을 위해 공동교육과정을 통해 인공지능 기초 수업을 들었고, 이 수업에서 인공지능이 학습하는 여러 기계학습 방법들 중에 강화학습에 대해 배웠습니다. 강화학습의 방식이 인간처럼 시행착오를 겪고 경험하여 발전하는 것과 매우 비슷했기에 가장 인상깊었습니다. 그래서 숭실대학교에 진학하여 AI에 대해 공부하고 강화학습을 하는 AI를 코딩해보고 싶습니다. 감사합니다.후배들을 위한 조언 면접 준비할 때 최대한 많은 분들께 면접을 받아보는 것을 추천합니다. 그리고 최대한 꼼꼼하게 생기부를 봐야합니다. 그리고 생기부에 있는 개념들 그 개념들에 대한 꼬리질문까지 생각하면서 공부하고 포스트잇에 써서 생기부에 붙여놓고 공부하는 것이 가장 많이 도움된 것 같아요.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"컴퓨터학부","jeonhyeong":"학생부종합(SW우수자)","method":"대기실에서 대기하며 핸드폰 제출 → 신분증 검사 → 호명이 되면 도우미를 따라 면접실 앞에서 대기 → 면접실로 입실수험표 신분증 필수. 가서 전자기기(핸드폰) 꺼서 내야함(안 내면 부정","notes":"행위, 태블릿/노트북은 전원만 끄면 됨). 모르는 거 있으면 미리 꼭 전화로 물어보거나 해야 됨.","qa":[{"q":"GAN 기술에 대해 알아보았다는데, 설명할 수 있나?","a":"GAN 기술이란 딥페이크의 기반이 되는 기술로, 식별자와 생성자가... (공부해간 내용대로 말함)"},{"q":"도서 추천 프로그램을 구현했다는데, 어떻게 구현했나?","a":"C언어를 활용해서 팀을 이뤄 구현함. 검색/추가 기능을 만들고 장르를 구분해 추천받을 장르를 입력하면 해당 장르 내에서 랜덤으로 도서를 출력하는 프로그램을 제작함."},{"q":"(꼬리질문) 도서 추천 프로그램 제작에서 어떤 역할을 했나? if문 같은 걸 활용했나?","a":"주제 선정, 계획, 추진하는 역할을 리더십있게 수행함. if문과 for문은 도서 검색/추가 기능에서 활용했고, 도서 추천 기능을 구현할 때 랜덤함수와 문자열 비교 함수를 활용함."},{"q":"확률과 통계 수업에서 몬테카를로 알고리즘을 활용해서 원의 넓이를 구하는 프로그램을 구현했는데, 이에 대해 설명할 수 있나?","a":"몬테카를로 알고리즘이란.. (공부한대로 설명함). 수많은 점을 찍는 실행을 통해 원의 넓이를 구할 수 있도록 구현함. (점을 무한개 찍으면 넓이를 어떻게 아냐고 해서 반지름이 1인 원의 넓이를 입력해두고 그와 비교하면 된다고 설명하니 그러면 알고리즘을 쓰는 의미가 있냐는 식으로 답변받음.)"},{"q":"포인터 구현해보았나? 구조체 구현해보았나?","a":"두 질문 모두 구현해본 적은 없지만 공부는 해보았다고 답변함. (포인터 그럼 공부한대로 설명해보라고 하심) 포인터는 특정 변수의 주소값을 나타내는 것으로 알고있다고 말함."},{"q":"기하를 집중이수했는데, 내적이 왜 쓰이나?","a":"(모르겠어서 전공 엮어서 대답함) 내적은 코사인 유사도에서 쓰이는 것으로, 코사인 유사도는 협업 필터링에서 쓰이는 것임. 협업 필터링이란 인공지능의 추천 방식 중 하나로... (공부한 내용 말함), (답변 다 하고 나니까 질문 의도는 그냥 수학적인걸 물어본거였다고 말하심)후배들을 위한 조언 해당 전형이 작년까진 특기자였는데 올해 우수자로 변경된 거였음. 전형 특성 상 전공지식 관련 질문이 많을 거라고 예상했고, 예상대로 마지막 수학 질문을 제외한 모든 질문이 전공지식 관련 질문이었음. 기하 개념 질문이 나올 거라고 전혀 생각 못했어서 시간 있으면 전공지식이랑 수학 공부 해 가는게 좋을 듯. 전공지식 공부할 때 대충하지 말고 정확히 하길 바람. 몰아서 하지 말고 착실하게 준비하길!2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"화학공학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"오전에 도착해서 순차가 될 때까지 기다리다가 순서가 되어서 대기실 앞에서 대기했습니다. 면접 도우미분들께서 노크를 해주셨고 면접을 하고 자기소개와 생기부 검증 마지막으로 하고픈 말을 하고 나왔습니다.생각보다 피곤해서 자는 친구들이 많았습니다. 저는 오히려 자고 일어나니 한결 편해져서 익살스럽게 응시했으나 자신의 컨디션에 맞게 조","notes":"절하고 면접관들 앞에서 혹시라도 하품같은 행실을 조심했으면 합니다.질문 수준을 봤을 때 현재 기업들이 사용하는 촉매나 밀웜이 어떤 플라스틱에서 먹이 반응이 활발한지 모두 알고 계시는 걸 보면 두 분 다 교수님인 것 같았습니다.","qa":[{"q":"플라스틱 종류 말해보세요.","a":"폴리에틸렌 폴리스틸렌 폴리프로필렌, LDPE, LLDPE, HDPE 예시 들어서 밀도랑 같이 설명함."},{"q":"플라스틱은 어떻게 만드나요?","a":"다양한 반응이 있으나 하나 예를 들어본다면 C2H2+H2=>C2H4 가 있습니다."},{"q":"그럼 C2H2는 어떻게 만드나요? (화학반응식 생각이 나지 않아 속으로 이산화탄소, 유기물을 고민하다가 석유가 생각남)","a":"석유로 만듭니다."},{"q":"네, 석유로 만들죠.(석유로 만드는 걸 알고 있는지 확인하고 싶어하셨던 것 같음)","a":""},{"q":"LG화학에서 플라스틱 만들때 사용하는 촉매가 어떤 것인지 알고 있나요?","a":"아 CO2 이산화탄소 를 사용해서 만드는 반응 이야기하시는 건가요??"},{"q":"아뇨 그냥 일반 반응이요.","a":"아, 이산화탄소 기체를 사용하는 건 알고 있는데 그건 모르겠습니다."},{"q":"그럼 그거 말해보세요.","a":"구리 촉매입니다."},{"q":"화생방이라는 동아리에 있었네요 화생방이 뭔가요?","a":"화학 생명 동아리입니다."},{"q":"그럼 왜 화생동이 아니라 화생방인가요?","a":"어.. 제가 꼭 선배님께 여쭤보도록 하겠습니다. (두 분이 같이 웃으심)"},{"q":"동아리에서 아스피린 합성 실험을 했었네요 설명해보세요.","a":"실험 재료 명칭이 생각이 안나지만 과정을 설명한다면 COOH 카르복시산과 알코올이 반응하여 물이 빠져나가 에스테르화가 됩니다 이를 통해 아스피린을 합성합니다.(교수님이 웅얼거리셔서 못듣고 다시 얘기해주시겠습니까 부탁드림)"},{"q":"키트 그런걸 사용한 건가요?","a":"아뇨 피스톤이 없어서 주사기랑 고무찰흙 갖고 직접 아스피린을 얻었습니다. <감압 장치를 피스톤이라 잘못 이야기함>(한 교수님이 엄청 빵긋 웃으심-실험 직접한 티가 나서 그런것 같음)"},{"q":"밀웜 실험을 진행했었는데 과정을 한번 더 설명해볼까요?","a":"밀웜이 플라스틱을 먹고 미세플라스틱을 만드는 것인지, 양분으로 삼는건지 궁금해 실험을 진행했었습니다 첫실험에서는 동족포식과 탈피껍질을 먹는 등의 오류가 생겨 다시 밀웜을 한 마리씩 소분하여 실험을 진행한 결과 밀웜이 성충까지 발현하는 것을 확인할 수 있었습니다."},{"q":"모든 플라스틱에서 그랬나요?","a":"저희 주변에 있는 플라스틱을 사용했는데 폴리에틸렌에서는 이빨자국이 조금 나타나긴 했지만 아사했고, 라면 봉지와 스티로폼 박스 같은 폴리스티렌에서 먹이 반응이 가장 활발했습니다."},{"q":"답변을 잘하네요 근데 3학년으로 갈수록 성적이 낮아지네요?","a":"(당황해서) 1학년때는 온라인클래스가 있다보니 제 공부 시간이 더 많았습니다. 하지만 2, 3학년으로 올라가면서 다양한 관심사를 갖고 탐구를 하며 조금 미흡했던 것 같습니다. 그래도 화학1에서 몰에 대한 이해 부족으로 4가 나왔으나 열심히 공부해 더 심화 내용인 몰농도와 몰랄 농도 등을 잘 해결해 화학2에서는 높은 성적을 받을 수 있었습니다. (교수님 또 빵긋하심)그리고 마지막 멘트 후배들을 위한 조언 긴장을 하지 않았으면 합니다. 청심환을 먹을거면 그전에 1~2번 모의면접 때 먹어보고 액체를 먹을지, 환을 먹을지 정해 경험해보며 너무 처지진 않는지 잘 이야기가 되는지 미리 경험해보세요. 자신한테 맞는 방법을 찾고 면접 내용을 최대한 많이 공부하여 면접을 볼 때 아쉬움이 남지 않았으면 좋겠습니다. 저도 모든 내용을 복습하고 실험이론을 암기하고 들어갔고 셔츠를 전날 다려서 옷걸이에 걸어 가져가서 옷이 어떠했느니 안경이 어땠니 핑계 대지말고 못보면 내가 못한거다. 아쉬움남지 않게 최선을 다하자라는 생각을 하고 임했고 좋은 결과를 이룰 수 있었습니다. 침착하게 긴장을 푸는 법을 찾아 적용하고 최선을 다했으면 좋겠습니다.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"회계학과","jeonhyeong":"학생부종합(SSU미래인재)","method":"서류 기반 면접(생기부 + 자소서)면접 평가 요소시험장 분위기 및 기타사항- 온도가 고사실 다리 떨 정도가 절대 아니므로 다리를 떨면 안 됨.- 분위기는 답변마다 끄덕여 주시며 친절한 편임.- 체감상 시간은 3분 그러나 실제는 10분임.","notes":"- 입학사정관과 전공 교수님이 1명씩 총 2분이 들어왔고 입학사정관 먼저 서류에 대한 기본사항을 진위를 따지고 전공 교수님이 궁금한 사항들을 질문하시며 평가하는 흐름임.- 저는 자기소개서에서 진위여부 파악하시고 세특, 창체활동에서는 전혀 나오지 않음.- 저는 숭실대학교 회계학과 교수님의 얼굴을 익혀 들어갔기에 교수님과 입학사정관 두 분을 구별하여 면접에 임했습니다.","qa":[{"q":"(입학사정관) 안녕하세요. 우선 자기소개와 지원 동기를 말씀해주시겠습니까?","a":"넵, 저는 진정한 회계사가 되기 위해서 도전 의식과 자기 주도성을 갖추기 위해 노력해왔습니다. 고등학교 당시, 공동교육과정을 통해 다양한 경험을 쌓았고 이를 추후 학교 활동으로 연계해 나가면서 건설적인 학습에 대한 보람을 느꼈습니다. 이를 토대로 앞으로 회계 투명성 제고뿐만 아니라 어려움을 겪는 기업의 재무 컨설팅을 통해 사회 이익에 공헌하는 진정한 회계사가 되고자 숭실대학교 회계학과에 지원했습니다."},{"q":"(입학사정관) 그 자기소개서에 투자 프로젝트 활동과 관련된 재무제표 살피는 법을 배웠다고 하셨는데 어떻게 접하셨죠?","a":"1학년 때 온라인 공동교육과정을 통해 회계 원리 교과를 배우며 자산, 부채. 자본 등의 기본 개념을 이해한 후 2학년 때 창의 경영에서 전자공시 사이트에서 기업 사업 보고서에서 직접 당기 순이익, 매출액, 부채 총계 등을 찾아본 경험을 살려서 해당 프로젝트 활동에서 적용해보았습니다."},{"q":"(입학사정관) 그 해당 교과서에서 나온 건가요?","a":"전자 공시라고 하는 사이트에서 직접 실제 재무제표를 뽑아 살펴보았습니다."},{"q":"(전공 교수) 그럼 재무제표에서 유동비율과 부채비율을 찾아보았다고 하셨는데 그 개념이 무엇인가요?","a":"둘 다 기업의 재무 안정성을 판단할 수 있는 지표로 유동비율은 유동부채 분의 유동자산이며 단기 지급 능력을 따질 수 있고 부채비율은 자기자본 분의 타인 자본의 비로 재무 건전성을 따질 수 있는 지표입니다. 특히 부채비율이 높으면 이자 비용이 높아지므로 리스크 관리가 필요하다고 판단했습니다."},{"q":"(입학사정관) 국채 금리의 장단기 금리를 비교하는 자료는 어디서 구하신건가요?","a":"제가 직접 투자 관련 사이트에서 2년채 국채 금리와 10년채 국채 금리 추이를 비교한 그래프를 2021년 기준금리 인상 기점을 기준으로 캡처하여 분석했었습니다.***********************여기까지가 서류에 대한 진위여부 파악**********************"},{"q":"(전공 교수) 회계사가 되고 싶었다고 하셨는데 회계사로서 필요한 덕목이 무엇이라고 생각하세요?","a":"저는 오블레스 노블리주라고..아! 노블레스 오블리주라고 생각합니다. (여기서 교수님께서 피식 웃으심) 왜냐하면 회계사는 기본적으로 감사보고서를 작성하게 되는데 감사보고서의 소견을 통해 여러 경제 이해관계자들에게 기초적인 판단의 지표로 작용되기 떄문에 자본주의 체제에서 막강한 권한을 가지고 있는 만큼 그 책임감이 필요하다고 생각하기 때문입니다."},{"q":"(전공 교수) 자기소개에서 자기주도성? 자기 능동성? 인가를 강조하셨는데 본인에게 해당 사례는 무엇이 있을까요?","a":"저는 사실 처음에 회계에 깊은 관심을 가졌다기보단 연말정산을 하시는 부모님을 뵈오며 세무에 처음 관심을 가졌었습니다. 그러다 1인기업 세무과외라는 도서에서 세무를 알기 위해서는 회계를 선행적으로 이해해야 한다는 사실을 꺠닫고 온라인 공동교육과정을 통해 직접 회계원리 과목을 수강하였고 분개와 계정과목 등 여러 개념을 주도적으로 알기위해 노력했던 경험이 있습니다."},{"q":"(전공 교수) 회계 관련 시사 뉴스에 대해 아시는 것이 있나요?","a":"레고랜드 사태에 대해서 접한 적이 있습니다. 채무 불이행으로 인해서 채권 시장에 유동성 경색으로 많은 기업이 자금 조달에 어려움을 겪고 있다는 내용으로 알고 있습니다."},{"q":"(전공 교수)(꼬리질문) 그럼 회계사로서 레고랜드에 대해 기업에게 컨설팅한다면?","a":"(당황해서 살짝 얼버무림) 저는 헷지 전략을 제안하지 않을까 싶습니다. 유동성 경색이 되었기에 재무구조적으로 리스크를 줄이기 위한 변동성을 줄여야하기 떄문입니다.(그냥 교수님이 넘어가신 건지 잘 모르겠음ㅎㅎ)"},{"q":"(입학사정관) 마지막으로 할 말 있으신가요?","a":"저는 하고 싶은 것도 할 수 있는 것도 많은 학생이라고 생각합니다. 문과 학생임에도 불구하고 빅데이터 분석이나 프로그래밍 교과목을 들으며 융합적 소양을 기르고자 노력했습니다. 저의 최종 목표는 과학적 접근에 기반한 유용한 회계정보를 창출해 사회에 기여하는 것입니다. 만약 숭실대학교 회계학과에 진학하게 된다면 저의 꿈과 목표를 이뤄가는 모습을 꼭 보여드리도록 하겠습니다. 감사합니다. 후배들을 위한 조언 숭실대의 특징 - 전문성, 자기 주도성을 강조함. 특히 실무적인 인재 양성을 위한 대학이라는 느낌이 많이 들었고 과거의 생기부보다는 미래에 어떠할 것이다라는 내용의 질문을 많이 함. 예를 들어 미래에 oo의 직업을 가진다면 가장 필요한 덕목을 질문한다는 것이 있음. 회계학과 특성상 회계사를 많이 배출하고 실적을 올리고 싶어하는 특성이 무조건 있을 수 밖에 없기에 회계사가 되고자하는 뚜렷한 목표의식을 가지고 있음을 어필하는 것을 추천함.2023 대입 면접후기"}],"result":"합격","resultNote":"X","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"숭실대학교","dept":"기계공학부","jeonhyeong":"학생부종합전형(고른기회)","method":"ZOOM 프로그램을 활용해 면접을 진행하고 면접을 볼 땐 교수님 2분과 면접을 시작한다.","notes":"면접 대기실에선 ZOOM 화면에서 나갈 때는 허락을 받아야 하고 면접 자료를 볼 수 있다.","qa":[{"q":"나중에 지능형 로봇을 만들고 싶다고 했는데, 왜 머신 러닝 말고 딥 러닝을 적용시키고 싶은 건가요?","a":"머신 러닝은 딥 러닝의 하위 개념입니다. 머신 러닝은 노래를 사용자에 맞게 추천하는 정도의 수준이지만 딥 러닝은 우리가 알고 있는 알파고 적용되는 인공지능입니다. 저는 지능형 로봇에 더 발전된 인공지능을 적용시키고 싶어 딥 러닝을 적용시키고 싶었습니다."},{"q":"인공지능 관련 학과가 아닌 기계공학부에 지원하게 된 이유는 무엇인가요?","a":"저는 1학년 로봇기술마을에 가서 휴머노이드 로봇을 직접 개발하고 코딩했던 경험은 저를 로봇 기계 연구원이라는 명확한 꿈을 갖게 해주었습니다. 그러던 중 한국사 시간에 전태일 분실 자살 사건을 보고 근로자에 대해 관심을 갖게 되었습니다. 그 이후 근로환경에 대해 관심을 꾸준히 갖고 여러 근로환경 문제를 보면서 근로환경을 개선할 수 있는 기계를 만들어야겠다고 생각했습니다. 인공지능은 부전공으로도 배울 수 있지만 4대 역학은 부전공으로 배우기 매우 힘들 것이라 생각했고 기계의 관절 부분 등에 들어가는 역학을 배우고 싶기 때문입니다.4-1. 지원동기에 있던 근로자를 위한 기계를 만들게 되면 근로자가 일자리를 잃는 것에 대해서는 어떻게 생각하시나요?저의 목표는 근로자와 로봇이 조화를 이루면 안전 근로환경을 만들어내는 것이 목표입니다. 하지만 로봇이 발전하게 되면 어쩔 수 없이 일자리를 잃게 될 것입니다. 하지만 미국의 뉴딜정책 중 하나인 테네시 계곡 개반 정책을 보면 댐을 지으면 일자리를 창출하고 댐을 관리하는 인원 곧 또 다시 일자리를 만들어 낸 것처럼 로봇을 관리하는 사람이 생겨야 할 것이므로 일자리는 그대로 유지될 것입니다.5-1. 지능형로봇시스템 연구실에서 경험을 쌓고 싶다고 했는데 여기 교수님이 누구신지 어떤 연구하는지 알고 있나요?제가 기계공학부 홈페이지를 찾아봤지만 이러한 연구실이 있다고만 있다고 봤지 어떠한 연구를 주로 하는지 교수님은 어떠한 분이신지는 잘 모르겠습니다.5-2. 그럼 아무것도 모르고 적어두신 건가요?아닙니다. 저는 대학원에 진학할 것이기 때문에 지능형로봇시스템 연구실이 있다는 것만으로도 충분히 제가 배우고 싶은 학문을 배울 수 있다고 생각했습니다."},{"q":"마지막으로 할 말이 있으시면 해주세요.","a":"고등학교 3년은 저에게 “나도 노력하면 할 수 있구나.”라는 생각을 심어준 시간이었습니다. 숭실대학교 기계공학부에서 기계, 로봇, 인공지능에 대한 학문들을 배우고 로봇 대학원에 진학하고 싶습니다. 쉽지 않은 길이 되겠지만 고등학교 때에 경험은 빛을 바랠 것이라고 생각합니다.꼭 숭실대학교에서 저의 목표를 이뤄내고 싶습니다. 감사합니다.후배들을 위한 조언 생기부에 모든 내용을 읽어보면서 한글파일로 이 활동에 대해서 교수님들이 궁금해할 내용이 어떤 것인지 예측해보고 활동을 정리해서 준비하는 것이 좋다.내신이 낮아도 끝까지 생활기록부를 채웠으면 좋겠다."}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"숭실대학교","dept":"물리학과","jeonhyeong":"학생부 종합(SSU미래인재전형)","method":"면접시간 10분 / 면접위원 2명 (교수님1, 입사관1)","notes":"","qa":[{"q":"양자역학이 무엇인가?","a":"미시적인 계의 현상을 다룸, 확률적"},{"q":"자소서에 이중슬릿 실험을 했다고 되어 있는데, 이를 거시적인 관점에서 봤을 때는 어떨까?(예를 들면 축구공만한 크기의 전자?)","a":"잘 모르는 내용이라 자신 없지만 아는 대로 답변함. 교수님이 설명해주심."},{"q":"왜 숭실대학교에 지원했는가? (학교 지원 동기)","a":"원래 천문 분야에 관심이 많았음. 동아리활동, 책, 영상을 계기로 꿈이 변경됨. 숭실대의 양자나노융합 전공 프로그램이 꿈을 실현하는 데 적합하다고 생각해서 지원함."},{"q":"과학실험탐구 대회에서 어떤 실험을 했는가?","a":"직접 실험하는 대회가 아니라 실험상황이 주어지고 과학적으로 해결하는 대회였음을 답변함."},{"q":"어떤 문제가 있었나?","a":"고정 도르래가 여러 개 연결되어 있고 한쪽에서 힘을 주면 다른 쪽에서 얼마만큼의 힘을 받는지 구하는 문제 등"},{"q":"1학년 동아리에서 몬티홀 딜레마가 있는 데 무엇인지 설명해봐라","a":"아는 대로 상황 설명"},{"q":"2학년 자성유체 실험 관련, 별 모양이란?","a":"별, 뿔, 자성 유체에 네오디늄 자석을 대면 평평한 액체가 모양을 띰."},{"q":"왜 나타나는가?","a":"자성유체에 철가루가 있어서"},{"q":"양자역학의 쓰임이 다양한 데 특히 어느 분야에 관심이 있나?","a":"반도체 관련 분야, 그 이유 설명"}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"숭실대학교","dept":"물리학과","jeonhyeong":"학생부 종합(SSU미래인재전형)","method":"면접시간 10분 내외 / 면접위원 2명","notes":"","qa":[{"q":"자네는 과학을 하고 싶은데 기자가 되려는 건가 아니면 기자가 되고 싶은데 과학을 배우고 싶은 건가?","a":"당연히 과학을 하고 싶은데 기자가 되려는 겁니다."},{"q":"과학부기자가 되려고하면 그 루트에 대해서 알고 있는게 있나?","a":"학부를 졸업한 후에 언론고시를 통해서 과학부기자 되는 방법이 있고 석사, 박사학위를 취득한 후에 특채로 입사하는 방법도 있다고 알고 있습니다. 사실 저는 과학을 대중에게 전달하는 꿈을 이루기 위해 과학부 기자의 길을 정한것인데, 최근에 양자역학에 관한 강연을 들으면서 여러 물리학과 교수님들이 대중들과 과학으로 소통하는 것을 보고 과학을 주제로 대중과 소통할 수 있는 방법이 많다는 것을 알았습니다. 그래서 제가 숭실대학교에 입학하면 우선 물리를 집중적으로 배우고 싶고 진로에 대해서는 나중에 생각해도 괜찮을 것 같습니다."},{"q":"그러면 하이젠 베르크의 불확정성의 원리에 대해 설명해보세요,","a":"불확정성의 원리는 드브로이의 물질파 이론에서부터 시작됩니다. 모든 물질은 파동성을 가지고 있다는 이론인데 그렇다면 모든 물질은 파동함수로서 표현할 수 있다고 볼 수 있습니다. 물질을 파동함수로서 나타낼 때에 위치의 불확정성이 낮아지면 파장이 다양한 파동함수를 사용하여 표현 해야 하는데, 파장은 운동량과 반비례하므로 파장이 다양해질수록 운동량 또한 다양해저 운동량에 불확정성은 높아집니다. 반대로 위치의 불확정성이 높아지면 적은 파동함수로 표현하므로 운동량의 불확정성은 낮아집니다."},{"q":"압전소자에 관한 연구를 진행했는데 쇠공을 이용한 실험에서 압전소자에 가한 운동량이 중요한 것 같나? 아님 충격량이 중요한 것 같나?","a":"어.... 운동량이 중요한 것 같습니다."},{"q":"운동량에 따른 전력량을 측정했다고 했는데 그럼 전류를 측정한 건가, 전압을 측정한건가?","a":"둘 다 측정하였고 같은 실험을 10번씩 진행했습니다."},{"q":"그랬더니 운동량이란 발생한 전류 전압이 비례한가?","a":"아뇨, 비례하게 안 나왔습니다."},{"q":"그 이유가 뭐라고 생각하나?","a":"압전소자 자체와 전선, 그리고 전압계에서의 전력손실이 원인이라고 생각합니다."},{"q":"실험자의 너의 잘못은 없는건가?","a":"아 당연히 제가 실험을 진행함에 있어 실수를 한 것도 있는 것 같습니다. 제가 실험이후에 보고서를 작성할 때에 오차에 대한 원인에서 작성한 것들을 말하다보니 그렇게 말씀드렸던 겁니다."},{"q":"음 알겠습니다. 수고하셨습니다.","a":"네 안녕히 계세요."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"숭실대학교","dept":"법학과","jeonhyeong":"학생부 종합(SSU미래인재전형)","method":"면접시간 10분 내외 / 면접위원 2명","notes":"순서는 미리 정해져 있음.1대 2 면접. 교수님이 면접관임","qa":[{"q":"그럼 자기소개하고 지원동기 말해주세요.","a":"안녕하십니까. 학년간 갈등 해결이나 급우 간 갈등 해결을 경험하면서 다른 사람들을 도울 때 행복함을 느꼈습니다. 저의 장점은 강한 리더십으로 3년간의 임원 경험을 토대로 하며 변호사가 되고 싶었습니다. 정의를 구현하고 사람들을 아우르고 도와주는 변호사가 되고 싶습니다."},{"q":"성적이 꾸준히 올랐네요, 어떻게 가능했나요?","a":"1학년 때는 성적에 크게 관심이 없었지만, 변호사라는 꿈이 정해지고 난 후 제 꿈을 이루기 위해서는 공부가 필요하다고 깨달았습니다. 그래서 관련 교과부터 먼저 관심을 가지고 공부하였습니다. 국어나 한문 공부는 법전 해석에 도움이 되기에 꾸준히 임했습니다. 다른 교과에서 배운 내용을 적용해 공부하였습니다. 국어 비문학에서 공리주의 관련 지문을 읽고 윤리 시간에 관련 내용을 학습했습니다. 연계공부가 저의 비법입니다."},{"q":"동아리 활동은 어떻게 진행하였습니까?","a":"정의구현 동아리에서 영상을 보고 관심사를 정해 모둠 과제를 설정했습니다. 저는 노인 문제에 대해 탐구하였습니다. 요양원에서 봉사활동 중 노인 복지에 관심이 생겨 이에 대해 친구들과 영역을 나누어 저는 재산상속법과 연관하여 노인부양의무에 대해 토의하였습니다. 이외에도 동아리에서 지리탐구활동 중 지도 맞추기 활동을 하였던 일이 기억납니다. 처음에는 서로 미루었지만 제가 먼저 나서서 하다 보니 다른 친구들도 자연스레 참여하였고, 모둠 과제에서 협력의 중요성을 깨달았습니다."},{"q":"정의란 무엇인가? 열차 딜레마에 대해 어떻게 생각하는가?","a":"열차 딜레마에서 저는 공리주의에 따라 더 적은 피해를 입는 쪽으로 열차가 틀어서 진행되어야 한다고 봅니다. 최대 다수의 최대 행복을 추구하는 것이 사회정의라고 보기 때문입니다."},{"q":"마지막으로 하고 싶은 말?","a":"열심히 하겠습니다. 미국의 법원장처럼 공명정대한 법조인이 되겠습니다."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"숭실대학교","dept":"벤처중소기업학과","jeonhyeong":"학생부 종합(SSU미래인재전형)","method":"면접시간 약 10분 / 면접위원 2명","notes":"","qa":[{"q":"가장 인상 깊은 교내 활동은?","a":"학교 협동 조합 활동이 가장 기억에 남습니다."},{"q":"협동 조합의 장단점을 알고 있나요?","a":"협동 조합의 장점은 학생들의 손으로 학생의 편익을 위한 일들을 해낼 수 있다는 것이고, 단점은 잘 모르겠습니다."},{"q":"창업계획서 경진 대회 아이템의 장점과 단점의 동기와 역할은?","a":"셀프 빙수는 손님 개개인의 취향을 고려할 수 있다는 장점이 있습니다. 친구와 빙수를 먹으러 가서 생긴 의견 충돌 때문에 셀프 빙수를 발상하게 되었습니다. 저는 아이디어를 제시하고 기대 효과를 예측하는 역할을 도맡아 수행하였습니다."},{"q":"벤처중소기업학과에 와야하는 이유는?","a":"경영학과와 달리 현장 경영에 필요한 실무적 지식을 배우기 위해 지원하였습니다."},{"q":"마지막으로 어필할 점","a":"뽑아주신다면 숭실대를 빛낼 사회적 기업가가 되겠습니다."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"숭실대학교","dept":"일어일문학과","jeonhyeong":"학생부 종합(SSU미래인재전형)","method":"면접시간 10분 / 면접위원 2명","notes":"","qa":[{"q":"많이 기다렸죠?","a":"아닙니다. 너무 긴장한 나머지 시간이 빨리 갔습니다."},{"q":"기다리면서 더 긴장했겠네요.","a":"너무나도 오고 싶은 학교라서 너무 긴장한 나머지 아침에 밥이 잘 넘어가지 않았습니다."},{"q":"아니에요, 긴장하지 말고 자신의 이야기 다 말해주세요. A: 네!","a":""},{"q":"생기부를 쭉 보면 히가시노 게이고, 미야자와 겐지 등등 많이 공부했는데 왜 일본어에 관심이 갔나요?","a":"저는 원래 언어에 굉장히 관심이 많습니다. 그 중에서 일본어가 매력적으로 다가 왔던 이유는 다른 언어와는 다르게 3가지 문자를 사용하기 때문이었습니다. 히라가나, 가타카나, 한자가 담겨진 문장을 보면서 외관상으로 끌리게 되었고 더 깊게 공부해보니 일본어와 한국어의 문장배열이 비슷했습니다. 그래서인지 이해하기 쉬웠고 정이 갔고 더욱 공부하고 싶은 언어로 남았던 것 같습니다."},{"q":"기억에 남는 일본 문화가 있나요?","a":"제가 진행했던 일본문화지브리스튜디오전에서 기모노 입기, 켄다마 대회, 애니메이션 명언 읽고 쓰기 등의 문화를 학생들에게 공유했던 경험이 가장 기억에 남습니다. 일본의 전통 의상 기모노를 직접 입어보고, 전통놀이 켄다마 대회도 해보고 유명한 애니메이션을 둘러보는 등 일본 문화를 학생들에게 부담 없이 공유할 수 있었던 것이 너무 좋았습니다."},{"q":"켄다마 놀이는 어디서 알게 되었나요?","a":"평소 일본 프로그램을 많이 시청하는데 명절 기획 프로그램에서 특히 켄다마 놀이를 많이 하는 것을 보았습니다."},{"q":"그 일본 문화 지브리 스튜디오전은 몇 명과 했나요?","a":"저희 동아리에서 10명과 같이 진행했습니다."},{"q":"대상이 누구였죠? A: 전교생을 대상으로 진행하였습니다.","a":""},{"q":"날을 잡아서 진행했나요?","a":"날을 잡기보다는 계획서를 제출하고 수렴되고 나서 학생들이 보다 더 많이 참여할 수 있도록 점심시간에 홈베이스에서 진행하였습니다."},{"q":"여기 보니까 어버이날 기념으로 부모님께 효 편지를 쓰면서 눈물을 보이는 모습이 인상 깊었다고 나와 있는데, 자신이 생각할 때 부모님을 기쁘게 해드렸던 것은 무엇이고, 반대로 슬프게 해드렸던 것은 뭔지 말씀해보세요.","a":"제가 기쁘게 해드렸던 것은 제가 저에게 주어진 일을 최선을 다할 때 부모님이 기쁘셨던 것 같습니다. 어렸을 때부터 부모님께서는 자신에게 주어진 일은 꼭 다해야 한다고 강조하셨습니다. 그것을 바탕으로 학업에 충실히 임하고 원하는 진로에 대해 끈기 있게 해 나가다 보니 부모님도 저의 꿈을 믿어주시고 지지해주시게 된 것 같습니다. 반대로 슬프게 해드렸던 것은 제가 작은 일에도 크게 좌절할 때 부모님께서 더 안타까워하시고 슬프셨던 것 같습니다. 제가 완벽주의 성향이 강해서 조금만 잘못해도 굉장히 크게 무너지는데 그런 모습을 보일 때 부모님께서 슬퍼하시지 않았나 생각합니다."},{"q":"시간이 조금 남았는데 조금만 더 해볼까요? 수상내역을 보면 교내 말하기 대회에 참가했는데 어떤 주제로 참가했나요?","a":"제가 총 2번의 말하기 대회를 참가했는데 첫 번째는 왜 사람들은 꿈을 가질까, 꿈의 형태에 대해 말했고, 두 번째는 제가 살고 있는 지역을 일본인에게 소개하는 것을 주제로 참가했습니다."},{"q":"그럼 이 최우수상은 학교에서 한명인가요?","a":"네!!!!! (이 답변 들으시고 교수님께서 오~~하는 표정을 지으심.)"},{"q":"학생 희망진로를 보면 3년 내내 일본어 교사로 기재되어있는데 어떻게 하면 일본어 교사가 될 수 있다고 생각하나요?","a":"본격적으로 1학년 때 일본어에 관심을 가지고 멘토-멘티 활동을 통해 제가 가르치는 것이 특기라는 것을 발견하게 되었습니다. 앞으로 숭실대학교 일어일문학과에서 다양한 학문 학습과 교직이수 과정을 이수하면서 저의 꿈인 일본어 교사를 이룰 수 있다고 생각합니다."},{"q":"원래 학생은 사람들 앞에서 자신감 있게 자신의 의견을 표출하는 성격인가요?","a":"아닙니다. 저는 사람들 앞에서 저의 의견을 말하는 것에 굉장한 두려움을 느꼈던 학생입니다. 하지만 저희 학교에서 강조하는 중요한 요소가 소통이고, 다양한 발표, 그리고 말하기의 경험을 통해 제가 이렇게까지 발전할 수 있었던 것 같습니다."},{"q":"마지막으로 할 말 있나요?","a":"저는 일본어 전공자의 일원이 될 사람으로서 일본에 대해 정확하고 객관적인 사실을 많은 사람들에게 공유하기에 아주 적합한 사람이라고 생각합니다. 숭실대학교에서 체계적인 인문학적 교육과 다양한 해외 교류 프로그램으로 일본어 교사의 자질과 덕목을 기르고 싶습니다."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"숭실대학교","dept":"정치외교학과","jeonhyeong":"학생부 종합(SSU미래인재전형)","method":"면접위원 2명","notes":"본인의 개인정보를 이야기하면 안됨.","qa":[{"q":"아침부터 오는데 힘들지 않았어요?","a":"제가 정말 오고 싶은 숭실대학교에서 면접을 본다는 생각에 많이 긴장했습니다. 그래서 아버지랑 이야기하면서 긴장 풀면서 왔습니다!"},{"q":"그럼 먼저 숭실대학교 지원동기 말씀해주시겠어요?","a":"제 좌우명은 ‘하고자하고 되고자하면 이룰 수 있다.’ 입니다. 이론과 현장을 연결하는 교육을 통해 현실 정치 감각을 기를 수 있는 숭실대학교에서 제 꿈을 펼쳐나가고 싶습니다."},{"q":"정치참여 포스터 대회에서 어떤 내용으로 포스터를 작성했나요?","a":"공동교육과정에서 정치적 무관심에 대해 연구했던 경험이 있습니다. 연구결과 정치적 무관심은 사회 발전을 저하시키는 문제이고, 시민의 정치참여가 발전된 사회를 만들어낼 수 있다는 것을 알 수 있었습니다. 함께 참여한 친구에게 이러한 이야기를 담고 싶다는 말을 전했고, 실제로 친구들과 대화와 협의를 통해 ‘한명 한명의 참여가 발전된 사회를 만듭니다.’ 라는 말을 담았습니다."},{"q":"민간외교봉사활동을 했네요? 민간외교 봉사활동이 뭔가요? 기자단으로 활동했는데 특별한 이유나 의미가 있었나요?","a":"다문화 민간외교는 지식을 매개로 수행하는 민간외교입니다. 특히 세계인들과 소통하며 다양한 국제적인 시사 문제에 대해 논할 수 있는 기자단으로 활동했습니다. 가장 인상 깊었던 기사는 북미 정상회담에 관해 작성했던 칼럼이었습니다."},{"q":"남북문제에 관심이 많네요? 그 이유가 있나요?","a":"저는 정치학의 다양한 분야 중에서 국제정치에 관심이 많습니다. 그런데 최근 동아시아 지역의 많은 국제적 문제가 주목되면서 동아시아 국제정치에 관심을 가지게 되었고, 동아시아 국제정치에 있어 빠질 수 없이 중요하게 여겨지는 토픽이 남과 북의 문제이기 때문에 관심을 가지게 되었습니다."},{"q":"동아시아 국제정치에 관심이 많은 것 같은데 홍콩 송환법이 왜 일어난 것 같나요?","a":"(잠시 생각할 시간을 가지겠습니다하고 말함) 먼저 시초는 한 남성이 여자 친구를 살해했고 이 남성을 송환하려는 중국의 시도에 의한 것이었습니다. 제가 생각한 원인은 오로지 송환법 뿐만 아니라 청년층의 빈곤 문제와 같은 불만과 홍콩이 중국에 의한 영향력에서 벗어나 민주국가로 나아가고 싶은 욕구가 표출되면서 시위가 더욱 격화된 것 같습니다."},{"q":"송환법이 무엇인가요?","a":"송환법은 다른 국가에서 자국민이 범죄를 저질렀을 때 그 국민을 자신의 국가로 송환하는 법입니다."},{"q":"짧게 마지막으로 하고 싶은 말 있으면 해주세요.","a":"작년 여름 숭실대학교에 방문한 적이 있습니다. 그때 이곳에서 꼭 공부하고 싶다는 다짐을 했었습니다. 그런데 지금 그 숭실대학교에서 공부할 수 있는 기회에 한 발자국 가까워진 것 같아 마음이 기쁘고 벅찹니다. 이후 이 숭실대학교에서 꼭 좋은 교수님들과 좋은 교육을 통해 저 또한 좋고 세계적인 시각을 가진 교수가 되고 싶습니다. 감사합니다."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"}],"official":[{"category":"전공적합성","jeonhyeong":"","q":"지원 전공 분야에 대해 알고 있는 현재 이슈가 있는지 특히 관심있는 분야는 무엇인가요","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"전공적합성","jeonhyeong":"","q":"분야가 유망하다고 생각하는 이유를 말해보세요 의 활용사례에 대해 말해보세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성, 잠재력","jeonhyeong":"","q":"학업계획에 ○○가 꿈이라고 했는데 관심 갖게 된 동기가 무엇인가요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성, 잠재력","jeonhyeong":"","q":"○○라는 진로를 결정하게 된 결정적인 활동을 구체적으로 설명해 보세요","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"건축학부","jeonhyeong":"","q":"전공적합성➀ 학교생활기록부를 보니 1학년 때부터 꾸준히 건축에 대한 관심을 키워온 것을 확인할 수 있었는데요, 혹시 좋아하는 건축물이 있나요?(예시답) 최근 파리 올림픽을 정말 열심히 시청했는데, 펜싱경기가 열린 그랑팔레가 너무 아름다웠습니다. 관심을 가지고 정보를 찾아보니 1900년에 당시 최첨단 건축 기술을 집약해 건축된 곳이더라고요. 파리만국박람회 용도로 건축되었지만 지금까지 파리 문화 예술의 중심지로 활용되고 있는 그랑팔레처럼, 저도 우리나라를 아름답게 드러내고 실제로도 많은 분야에서 활용되는 실용적인 공간을 건축하고 싶다는 생각을 하게 되었습니다.➁ 1학년 때부터 3년간 건축동아리 활동을 한 것을 보아 건축가의 꿈을 일찍부터 키워온 것을 알 수가 있는데요, 그렇다면 3학년 때 했던 탐구 활동이 건축 분야에 대해 가장 진지하게 탐구했던 내용이 아닐까 싶습니다. 수학과제탐구 시간에 했던 탐구 활동에 대해서 설명해주세요.(예시답) 네. 말씀하신 대로 수학과제탐구 시간에 사회문제와 연관지어 건축에 대해 탐구해보는 활동을 열심히 하였습니다. 당시 튀르키예 지진이 발생하여 지진 대피 장소에 대해 생각해 보았고, 지진 발생 시 대피 장소 1순위가 운동장임을 알게 되었습니다. 그러므로 미리 운동장을 주차장처럼 규격화해놓은 정보를 만들어 놓는다면, 구호물품을 배분하는 등에 있어 효율적 지원이 가능할 것으로 생각되었습니다. 또한 공간에 대한 연구 및 설계가 재난이나 여러 가지 상황이 발생했을 때 효율적 대처가 가능하게 한다는 점을 깨달을 수 있었습니다.➂ 건축동아리에서 가장 열심히 했던 활동은 어떤 게 있을까요?(예시답) 저는 건축가의 꿈을 가지고 건축동아리 활동을 하였는데, 2학년 때 부산 엑스포 파빌리온 설계를 스케치해본 것이 가장 열심히 한 활동입니다. 엑스포의 특성상 한국의 기술력을 보여주고 나라의 특성을 보여주어야 했기 때문에 한옥에서 본 딴 지붕에 부산이라는 바다를 덧붙여 다양한 설계 스케치안들을 내었고, 팅커캐드라는 3D 프로그램을 이용해서 직접 설계해 보고 우드락으로 잘라 모형을 만들며 실제 건축가처럼 작업을 해보았습니다. ➃ 이 활동에서 나아가 3학년 때는 신도시건설 프로젝트를 진행했는데, 좀 더 자세히 설명해 주시겠어요?(예시답) 앞서 말씀드린 활동은 동아리원들이 개별적으로 설계를 진행하고 합치는 방향으로 진행하였습니다. 단순히 멋있고 효율적인 개별 건물을 합치게 된다고 해서 전체적으로 좋은 공간들이 구성되지 않는다는 점을 깨닫고, 3학년 때에는 동아리 모둠원들과 함께 토의하며 도로부터 건물, 그리고 휴식 공간 등을 적절하게 배치하며 개별적인 건물을 설계하는 방향으로 진행하였습니다. 이 경험을 통해 건물의 배치, 도로의 연결망 등과 같은 도시 계획의 중요성에 대해서 깨달았습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"건축학부","jeonhyeong":"","q":"잠재력➀ 물리Ⅰ, 물리Ⅱ, 물리학실험 과목까지 위계에 맞게 잘 이수하고, 3학년 때 고급물리학 과목을 이수하였는데요, 어떤 목표를 갖고 고급물리학까지 선택하게 되었고, 물리학 공부를 통해 어떤 성취감을 얻을 수 있었는지 궁금합니다.(예시답) 먼저 물리Ⅰ 수업에서 지진과 면진, 파동, 트러스 구조 등을 배웠는데, 건축에 꼭 필요한 공부라고 느끼게 되어 더 열심히 했고, 물리 관련해서 할 수 있는 과목 선택은 다 해보려고 한 것 같습니다. 3학년 고급물리학에서는 트러스 구조의 프로그램을 직접 다루어 보는 시간을 가짐으로써 학습한 내용을 통해 희망진로를 구체화하는데 활용할 수 있어 매우 만족스러웠습니다. 앞서 말씀드린 대로 저는 사회문제와 사회문제를 해결할 수 있는 대체 공간의 도시 건설에 관심이 많은데, 그러한 가능성을 건축을 통해 엿볼 수 있었습니다.➁ 2학년 때 화법과 작문 세특 내용을 보면 선량한 차별주의자 책을 선정해서 두 달 동안 모둠원들의 참여를 이끌어내며 모둠 전체가 큰 칭찬을 받았다고 되어 있습니다. 구체적으로 어떤 소통을 했으며, 공동의 완성물을 내기 위해 모둠장으로서 어떤 노력을 했는지 말씀해 보세요.(예시답) 저는 사회문제 관련 책을 많이 읽어서 이러한 활동에 관심이 매우 많았습니다. 그러나 모둠원들인 친구들은 자신의 진로와도 연결하기 어려운 책에 대해서는 별 흥미가 없었습니다. 그래서 모둠장으로서 어떻게 이 문제를 해결해야 할까 고민하였고, 자신의 진로와 관련된 활동에는 관심이 많다는 점을 떠올려 모둠원들의 각 관심 분야 및 진로와 연결하여 책 각 장마다 토의를 할 수 있도록 하였습니다. 그랬더니 친구들의 참여 태도가 적극적으로 변했고 매 회차마다 즐겁게 토의하고 선생님으로부터도 매우 좋은 평가를 받았습니다.➂ 숭실대학교에 입학해서 건축을 공부하고 난 후, 어떤 공간을 건축하고 싶나요? (예시답) 저는 기회가 된다면 차별 없는 학교를 건축하고 싶습니다. ○○학교라는 장애인들을 위해 설계된 학교가 있는데요, 이 학교는 복도도 넓고 문턱이 없는 등 건축 설계에 차별이 없고 모든 공간에 장애학생들이 쉽게 접근할 수 있게 되어 있습니다. 이처럼 차별 없는 학교를 건축해서, 사회문제를 해결하는 데 도움을 주는 건축가가 되고 싶습니다. 숭실대학교에서 이러한 제 꿈을 이뤄나갔으면 좋겠습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"경영학부","jeonhyeong":"","q":"전공적합성➀ 학교생활기록부를 보니 교육청과 연계된 꿈의 대학 프로그램을 통해 경영학과 경영회계 관련 수업을 17시간씩 들었네요? 왜 해당 전공 분야의 강의를 선택했나요? (예시답) 제가 이 수업을 들었을 당시에는 회계사의 꿈을 가지고 있었습니다. 그런데 회계라는 분야는 학교에서 교과목으로 배우기 어려운 과목이다 보니 온라인 수업을 통해 회계를 배우고 싶었습니다. 이를 통해 회계사가 어떤 일을 하는지도 알 수 있었고, 3학년에 올라와서 경영학과를 가야 하는 이유도 찾을 수 있었습니다. 경영학을 공부하더라도 회계가 필수라고 생각했기 때문에 회계 수업을 들었던 점은 큰 도움이 되었습니다.➁ 그럼 오히려 회계학과를 지망해야 맞지 않았을까요?(예시답) 제가 회계사에 관심을 갖게 된 이유는 기업의 비리를 감사하는 일을 하기 때문입니다. 그래서 2학년 때는 회계사가 되고 싶었습니다. 그런데 3학년에 올라와 경영 관련 직업탐구를 하면서 회계사는 기업의 비리가 일단 드러난 후 이를 바로잡는 일을 한다는 것을 깨달았습니다. 그렇다면 비리가 일어나지 않게 기업을 감사하는 직업은 무엇이 있을까 고민하던 중 경영컨설턴트를 알게 되었습니다. 경영컨설턴트가 되어 많은 기업의 비리가 일어나지 않게 도움을 주는 사람이 되고 싶었고, 최종적으로 경영학부를 지원하게 되었습니다.➂ 경영 관련 분야로 진지하게 진로를 탐구해 보다가 최종적으로 경영학을 선택했군요. 그렇다면 3학년 때 했던 탐구 활동은 깊이 있게 진행되었을 것 같은데요. 사회문제탐구 세특 내용을 보면 기업의 윤리적인 활동이 소비자에게 어떤 영향을 미치는지 탐구한 활동이 있습니다. 구체적으로 어떤 탐구를 했고, 어떤 과정을 거쳐 진행했는지 이야기해 보세요. (예시답) 우선 기업의 윤리적인 활동이 소비자에게 어떤 영향을 끼치는지 설문조사를 하였습니다. 가상으로 두 개의 기업의 윤리적인 활동을 설정하고 구매를 결정할 것인지에 설문조사를 했습니다. 반 친구들, 동아리, 임원 등 인맥을 최대한 동원해 100명이 넘는 학생들을 조사했습니다. 결론은 소비자가 긍정적으로 기업을 바라보게 되면 구매에 소폭 영향을 미치게 된다는 것을 알 수 있었습니다. 이번 탐구를 통해 이런 작은 영향력들이 결국 기업의 윤리경영으로 이어질 수 있지 않을까 생각하게 되었습니다.➃ 활동을 마치고 아쉬운 점이 있었다면 어떤 것인지, 이후 이를 보완하기 위해 어떤 노력을 했나요? (예시답) 제가 설정한 가상 기업은 컴퓨터 제품을 판매하는 기업이었는데요, 고가의 제품이다 보니 소비자 구매에 가격이 상당한 영향을 미친다는 점을 고려하지 못했고 이런 이유로 결과가 뚜렷이 나타나지 않았던 점이 아쉬웠습니다. 만약에 활동을 보완할 수 있다면, 손쉽게 구매 가능한 우유와 같은 제품을 판매하여 결과를 조금 더 뚜렷하게 도출해보고 싶습니다. 또한 활동이 끝난 후 기업 사례를 찾아보기 위한 노력을 했습니다. ESG 경영 사이트에 올라와 있는 ESG 등급 조사결과를 토대로 기업 사례를 분석하였고, 소비자의 구입 사례를 통해 소비자에게 영향을 끼치는 사례를 찾아보았습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"경영학부","jeonhyeong":"","q":"잠재력➀ 학교생활기록부를 보니 수학과목의 성취도가 좋고 수학을 매우 열심히 공부한 것 같아요. 왜 수학을 열심히 공부하였는지, 그리고 3년 동안 수학을 공부하며 어떤 점을 발전시켜 나갔는지 궁금합니다. (예시답) 저는 경영학에 대한 꿈을 갖기 시작하고 수학의 중요성을 깨달았습니다. 수학을 잘하진 못했지만, 수학의 중요성을 깨닫고 수학 과목에 노력을 기울이기 시작하였습니다. 그 결과 1, 2학년 때 수학에선 매우 좋은 성과가 있었습니다. 하지만 3학년 때 미적분 수업은 이과 성향의 친구들이 너무 많아 성적을 받기 어려웠습니다. 그럼에도 불구하고 경제수학에서 미적분은 꼭 필요하다고 생각해 열심히 공부하였고, 3등급 성적으로 마무리할 수 있었습니다. 원래 수학을 잘하지 못했었기 때문에 너무 힘들었지만, 경영학을 공부하는 데 수학적 능력은 분명 도움이 될 것이라는 걸 알았기 때문에 계속 노력할 수 있었습니다.➁ 도서반 활동을 꾸준히 하면서 여러 가지 활동을 주도하고 기획하면서 탁월한 의사소통능력을 보여줬다고 하는데, 학생부에 기재되지 않은 실제 사례가 있다면 구체적으로 말씀해 주시겠어요? (예시답) 저는 도서부 동아리에서 부장으로서 활동하였는데요, 2학년 축제 시즌에 부스를 운영하면서 있었던 에피소드를 말씀드리겠습니다. 친구들과 부스 운영을 논의하며 북카페, 방탈출 운영으로 의견이 갈리는 일이 있었습니다. 그러나 저는 부장으로서 두 의견을 다 수용하여야 한다고 생각해 방탈출과 북카페를 동시에 운영하였습니다. 방탈출을 성공하면 북카페의 음료를 주는 등 상호 보완할 수 있도록 하였고, 결과적으로 모두가 만족하는 기획을 하였습니다. 동아리 부장으로서 행사가 잘 이루어질 수 있도록 의사소통능력을 잘 발휘하였다고 생각합니다.➂ 숭실대 경영학부가 다른 학교랑 어떤 점이 차별화된다고 생각하고 지원했는지 궁금합니다. (예시답) 많은 대학에 경영학과가 있지만 제가 숭실대학교를 선택한 이유는 IT대학의 장점을 가지고 있기 때문입니다. 숭실대학교는 정보기술과 관련된 전공수업과 프로그램들이 많습니다. 또한, 경영학에서도 인공지능을 잘 알아야 하는데 숭실대학교 경영학부에서 미래 사회의 경영컨설턴트가 될 수 있는 준비를 잘 시켜주리라는 믿음이 있었습니다. 그래서 숭실대학교에 지원하게 되었고 꼭 뽑아주셨으면 좋겠습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"전공적합성 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"○○교과 선생님이 작성한 ○○탐구활동과 연계한 후속 활동 내용을 구체 적으로 설명해 보세요.","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"전공적합성 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"현재 이슈가 되는 ○○문제에 대해 아는 수준에서 해결방안 아이디어를 이야기해 줄 수 있나요?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"전공적합성 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"수소연료전지의 원리는? / 유전자 발현 과정을 배운 대로 설명해 보세요.","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"전공적합성 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"다양한 진로탐색 활동 중 아쉬웠던 점과 이를 개선하기 위한 구체적 노력은?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"전공적합성 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"고교 3년간 노력해서 얻은 가장 큰 성취와 그 과정에서 배운 점은?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"잠재력 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"팀 프로젝트에서 팀원들과 원활히 과제를 수행하기 위해 기울인 노력은?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"잠재력 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"동아리·자율활동 중 가장 성장한 경험은 무엇인가요?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"잠재력 (50%)","jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","q":"활동 과정에서 실패하거나 어려웠던 점과 이를 어떻게 해결했는지 말해보세요.","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"}],"admission":[{"jeonhyeong":"학생부종합 - SSU 미래인재전형(면접형)","select":"- 3배수: 인문대학 내 모집단위·국제법무학과·정보보호학과 1단계 - 3.5배수: 그 외 모집단위 전체 2단계 1단계 50% + 면접 50%","type":"서류기반 개별 면접","method":"면접위원(2인) : 지원자(1인), 12분 내외 개별면접 (최고점: 50점, 최저점: 0점)","schedule":"2026.11.27.(금) 전 모집단위","notes":"","areas":[{"area":"전공적합성 (50%)","questions":["○○교과 선생님이 작성한 ○○탐구활동과 연계한 후속 활동 내용을 구체 적으로 설명해 보세요.","현재 이슈가 되는 ○○문제에 대해 아는 수준에서 해결방안 아이디어를 이야기해 줄 수 있나요?","수소연료전지의 원리는? / 유전자 발현 과정을 배운 대로 설명해 보세요.","다양한 진로탐색 활동 중 아쉬웠던 점과 이를 개선하기 위한 구체적 노력은?","고교 3년간 노력해서 얻은 가장 큰 성취와 그 과정에서 배운 점은?"]},{"area":"잠재력 (50%)","questions":["팀 프로젝트에서 팀원들과 원활히 과제를 수행하기 위해 기울인 노력은?","동아리·자율활동 중 가장 성장한 경험은 무엇인가요?","활동 과정에서 실패하거나 어려웠던 점과 이를 어떻게 해결했는지 말해보세요."]}]},{"jeonhyeong":"학생부종합 - SW우수자전형","select":"1단계 서류 100% (3배수) 2단계 1단계 50% + 면접 50%","type":"서류기반 개별 면접","method":"면접위원(2인) : 지원자(1인), 12분 내외 개별면접 (최고점: 50점, 최저점: 0점)","schedule":"2026.11.28.(토) 컴퓨터학부, 글로벌미디어학부, AI소프트웨어학부","notes":"","areas":[]}]};
